package FSM::Scheduler::ISF::LoweringIR;

use v5.20;
use strict;
use warnings;
use feature qw(signatures postderef);
no warnings 'experimental::signatures';
use POSIX qw(log);
use Carp qw(confess);
use Scalar::Util qw(refaddr weaken);
use FSM::Package::IntegerLiteralSupport;
use FSM::Package::Symbols;
use FSM::Scheduler::ISF::ATLGeneratedTop qw(
    atl_generated_top_report_entry
    mark_atl_data_link_child_interface_ports
);
use FSM::Scheduler::ISF::ControlFlowEffects;
use FSM::Scheduler::ISF::LogicalControllers;
use FSM::Scheduler::ISF::DomainSource qw(_domain_actor_for_scheduled_artifact);
use FSM::Scheduler::ISF::ChildStorageOwnership qw(prepare_child_storage_writes connect_child_storage_writes plan_child_storage_write_handoffs select_child_storage_reads connect_child_storage_reads plan_child_storage_read_handoffs);
use FSM::Scheduler::ISF::ChildActivation qw(guard_child_activation);
use FSM::Scheduler::ISF::LibraryPortOwnership qw(connect_library_output_readbacks);
use FSM::Scheduler::ISF::ChildCompletionOutputs qw(prepare_child_completion_outputs connect_child_completion_outputs plan_child_completion_outputs);
use FSM::Scheduler::ISF::ChildCompletion qw(retain_child_completions);
use FSM::Support::HDLInstanceIdentifierPolicy;
use FSM::Support::ISFInterfacePortMetadata qw(snapshot_interface_port_metadata);
use FSM::Scheduler::ISF::RecordSamples;
use FSM::Support::ISFRecordPortContexts qw(validate_actor_record_contexts);
use FSM::Support::ISFRecordPortSamples qw(actor_has_record_port);

sub new($class, %args) { bless { debug => ($args{debug} // 0) }, $class }

my %CONTROL_FLOW_EFFECT_CHECK_CACHE;

my %SUPPORTED_TRANSACTION_CLAUSES = (
    transaction => {
        map { $_ => 1 } qw(
            on drive await sample update phase point shift_left shift_right assemble
            extract complete when switch repeat latency do spawn await_all
            await_any params stage store load wait while until set
            atl_trigger atl_trigger_batch local assert cover assume
        )
    },
    when => {
        map { $_ => 1 } qw(
            drive await sample complete repeat update set shift_left shift_right
            assemble extract when store load wait do spawn await_all await_any
            exit-when continue-when
        )
    },
    switch => {
        map { $_ => 1 } qw(
            drive await sample repeat update set shift_left shift_right assemble
            extract when store load wait do spawn await_all await_any
        )
    },
    repeat => {
        map { $_ => 1 } qw(
            drive await sample update set shift_left shift_right assemble extract
            store load wait do spawn await_all await_any repeat
        )
    },
    while => {
        map { $_ => 1 } qw(
            drive await sample complete repeat update set shift_left shift_right
            assemble extract when store load wait do spawn await_all await_any
            exit-when continue-when
        )
    },
    until => {
        map { $_ => 1 } qw(
            drive await sample complete repeat update set shift_left shift_right
            assemble extract when store load wait do spawn await_all await_any
            exit-when continue-when
        )
    },
);

my %TRANSACTION_CONTEXT_LABEL = (
    transaction => 'transaction body',
    when        => 'when body',
    switch      => 'switch branch',
    repeat      => 'repeat body',
    while       => 'while body',
    until       => 'until body',
);

sub _prepare_module_source($self, $actor) {
    validate_actor_record_contexts(actor => $actor, whole_output_writes_only => 1)
        if actor_has_record_port(actor => $actor);
    $self->_validate_static_zero_repeat_child_activation_prune_surface($actor);
    $self->_validate_child_transaction_refs($actor);
    $self->_validate_activation_domain_names($actor);
    my %generated_children = $self->_collect_generated_child_transaction_refs($actor);
    my %pruned_static_zero_children =
        _pruned_static_zero_child_transaction_targets($actor, \%generated_children);
    my $domain_partition = $self->_build_domain_partition($actor, \%pruned_static_zero_children);
    $self->_validate_transaction_parameter_clauses($actor, \%generated_children, \%pruned_static_zero_children);
    $self->_validate_transaction_port_bindings($actor);

    return (\%generated_children, \%pruned_static_zero_children, $domain_partition);
}

sub build_module($self, $actor) {
    my ($generated, $pruned, $domain_partition) = $self->_prepare_module_source($actor);
    my %generated_children = %$generated;
    my %pruned_static_zero_children = %$pruned;

    my $child_products = $self->_build_module_child_products($actor, $generated);
    my %child_irs = %{$child_products->{children}};
    my @library_instances = @{$child_products->{library_uses}};
    my @atl_top_instances = @{$child_products->{atl_top_instances}};

    my $parent_ir = $self->_build_parent_ir($actor, \%generated_children, \%pruned_static_zero_children);
    my $connected = connect_child_storage_writes($parent_ir, \%child_irs);
    $connected += connect_child_storage_reads($parent_ir, \%child_irs);
    $connected += connect_child_completion_outputs($parent_ir, \%child_irs);
    $connected += connect_library_output_readbacks($parent_ir, \@library_instances);
    _finalize_ir($parent_ir) if $connected;
    $parent_ir->{children} = \%child_irs;
    $parent_ir->{library_uses} = \@library_instances;
    $parent_ir->{atl_top_instances} = \@atl_top_instances;
    if (@atl_top_instances) {
        $parent_ir->{actor_network}{generated_tops} = [
            map { atl_generated_top_report_entry($_) } @atl_top_instances
        ];
    }
    $parent_ir->{domain_partition} = $domain_partition if $domain_partition;
    return $parent_ir;
}

# These modules and composition records are constructed before the parent
# declaration merge. Share the same admission/order with source preparation.
sub _build_module_child_products($self, $actor, $generated) {
    my %child_irs = %{$self->_build_generated_transaction_children($actor, $generated)};

    my @library_instances;
    for my $use (@{$actor->{library_uses} || []}) {
        my $module = $use->{module};
        confess "Library use '$use->{instance}' is missing a generated module name\n"
            unless defined($module) && !ref($module) && length($module);
        confess "Library use '$use->{instance}' generated module '$module' conflicts with another generated child\n"
            if exists $child_irs{$module};
        $child_irs{$module} = $self->_build_library_child_ir($use, $actor);
        push @library_instances, _library_instance_metadata($use);
    }

    for my $resolution (_resolved_atl_actor_type_resolutions($actor)) {
        my $instance = $resolution->{instance};
        confess "ATL static actor instance resolution is missing an instance name\n"
            unless defined($instance) && !ref($instance) && length($instance);

        my $module = $resolution->{module};
        confess "ATL static actor instance '$instance' is missing a generated module name\n"
            unless defined($module) && !ref($module) && length($module);
        confess "ATL static actor instance '$instance' generated module '$module' conflicts with another generated child\n"
            if exists $child_irs{$module};

        $child_irs{$module} = $self->_build_resolved_atl_child_ir($resolution, $actor);
    }

    my @atl_top_instances = $self->_select_atl_generated_top_instances($actor, \%child_irs);
    mark_atl_data_link_child_interface_ports(\%child_irs, \@atl_top_instances);

    return {children => \%child_irs, library_uses => \@library_instances,
        atl_top_instances => \@atl_top_instances};
}

sub _build_generated_transaction_children($self, $actor, $generated) {
    my %children;
    for my $name (sort keys %$generated) {
        my ($tx) = grep { $_->{name} eq $name } @{$actor->{transactions}};
        next unless $tx;
        $children{$name} = $self->_build_child_ir($tx, $actor, $name);
    }
    return \%children;
}

# Prepare the detached lexical resolver's inputs from parsed source. Run the
# production module admission and per-transaction lowering checks without a
# parent merge that would conflate still-unallocated formal names. A monitor
# collision solely with an unprojected direct formal is retained as a deferred
# physical obligation; executable builds always apply the strict collision check.
# This is not physical reservation, backend validation or production rewriting.
sub prepare_formal_source($self, $source_actor) {
    my $actor = _clone_isf_value($source_actor);
    my ($generated, $pruned, $partition) = $self->_prepare_module_source($actor);
    my $static = _formal_expression_static_symbols($actor);
    my %drives = map { $_ => 1 } keys %{$actor->{drives} || {}};
    my (%contexts, %products, %deferred);
    my %fixed_names = map { $_ => 1 } (
        keys %{_build_signal_width_map($actor, {clauses => []})}, keys %$static,
        map {$_->{name}} @{$self->_build_ports($actor)},
    );
    $fixed_names{$actor->{clock}} = 1 if defined($actor->{clock}) && !ref($actor->{clock});
    $fixed_names{$actor->{reset}{name}} = 1
        if ref($actor->{reset}) eq 'HASH' && defined($actor->{reset}{name});
    my %points;
    my $ordinal = 0;
    for my $tx (@{$actor->{transactions} || []}) {
        my $name = $tx->{name};
        next if $pruned->{$name};
        my %child_points;
        my %unprojected = map { $_->{name} => _clone_isf_value($_) }
            grep { !exists $_->{_isf_formal_identity} }
            map { @{($tx->{ports} || {})->{$_} || []} } qw(inputs outputs);
        my $preallocation = $generated->{$name} ? undef : {
            formals => \%unprojected, fixed_names => \%fixed_names, collisions => [],
        };
        my @products = $self->_build_transaction($tx, $actor, $generated->{$name} ? 0 : $ordinal++,
            $generated->{$name} ? undef : $generated,
            $generated->{$name} ? \%child_points : \%points, $preallocation);
        $deferred{$name} = _clone_isf_value($preallocation->{collisions})
            if $preallocation && @{$preallocation->{collisions}};
        my @fields = qw(states counters dt_blocks local_do_refs spawn_refs
            temporal_contracts signal_widths storage_roles bank_accesses reset_values
            immediate_assertions);
        confess "Unexpected transaction lowering product count\n" unless @products == @fields;
        my %product;
        @product{@fields} = @products;
        # Products may retain source references. Keep both returned projections
        # independent, including between transactions, before callers inspect them.
        $products{$name} = _clone_isf_value(\%product);
        my %locals = map { $_->[1] => 1 }
            grep { ref($_) eq 'ARRAY' && @$_ && $_->[0] eq 'local' }
            @{$tx->{clauses}};
        my %params = map { $_->{name} => 1 } @{_transaction_param_declarations($tx, $actor)};
        my %pruned_repeats;
        _formal_pruned_repeat_paths($tx->{clauses}, ['clauses'], $actor, $name, \%pruned_repeats);
        $contexts{$name} = {
            locals => \%locals,
            # Direct transaction parameters are compile-time count/width inputs,
            # not emitted parent expression symbols. Generated children emit them.
            static_symbols => { %$static, $generated->{$name} ? %params : () },
            static_count_symbols => { %$static, %params },
            pruned_repeats => \%pruned_repeats,
            named_drives => { %drives },
        };
    }
    my $activation_products = $self->_formal_parent_activation_products(
        $actor, $generated, \%products);
    my $wiring_products = $self->_formal_parent_wiring_products(
        $actor, $generated, \%products, $activation_products);
    my $point_products = $self->_formal_parent_point_products(
        $actor, $generated, \%products, $wiring_products, \%points);
    my $resource_products = _formal_resource_signal_products($actor);
    my $child_products = $self->_build_module_child_products(_clone_isf_value($actor), $generated);
    my $declaration_names = _formal_parent_declaration_names(
        $actor, $generated, \%products, $activation_products, $wiring_products,
        $point_products, $resource_products);
    my $payload_products = _local_rule_payload_snapshot_products(
        $actor, $declaration_names, $point_products->{states}, $activation_products->{dt_blocks});
    $declaration_names->{$_} = 1 for keys %{$payload_products->{signal_widths}};
    my $completion_products = _formal_parent_completion_products(
        $actor, $declaration_names, $activation_products, $point_products);
    my %connection_names = (%$declaration_names,
        map { $_ => 1 } keys %{$completion_products->{signal_widths}},
            map { $_->{name} } @{$completion_products->{dt_blocks}});
    my $write_products = plan_child_storage_write_handoffs(
        $actor->{actor_name}, $activation_products->{spawn_instances},
        $child_products->{children}, \%connection_names);
    $connection_names{$_} = 1 for keys %{$write_products->{signal_widths}},
        map { $_->{name} } @{$write_products->{dt_blocks}};
    my $read_products = plan_child_storage_read_handoffs(
        $actor->{actor_name}, $activation_products->{spawn_instances},
        $child_products->{children}, \%connection_names);
    $connection_names{$_->{name}} = 1 for @{$read_products->{ports}}, @{$read_products->{dt_blocks}};
    my $local_completions = _formal_local_completion_contracts(
        $actor, $completion_products, $activation_products, $generated, \%products,
        $child_products->{children});
    my $named_completion_products = plan_child_completion_outputs(
        $actor->{actor_name}, $activation_products->{spawn_instances},
        $child_products->{children}, \%connection_names, $local_completions);
    my %domain_products;
    if ($partition && ($partition->{kind} // '') eq 'multi_domain') {
        for my $domain (@{$partition->{domains}}) {
            my $domain_actor = _domain_actor_for_scheduled_artifact(
                $actor, $domain, $partition->{default_domain});
            # The canonical constructor clears clock_domains, so preparation
            # terminates at this independent module scope. Keep its real local
            # transaction ordinals and injected external-activation products.
            $domain_products{$domain->{name}} = {
                identity => ['actor_domain', $actor->{actor_name}, $domain->{name}],
                domain => _clone_isf_value($domain),
                preparation => $self->prepare_formal_source($domain_actor),
            };
        }
    }
    return {
        actor => $actor,
        generated_children => { %$generated },
        pruned_transactions => { %$pruned },
        domain_partition => _clone_isf_value($partition),
        domain_source_products => \%domain_products,
        transactions => \%contexts,
        # Actual producer inputs for the checked reservation collector. Final
        # executable declarations are verified separately against these scopes.
        transaction_products => \%products,
        # Preserve authored report endpoints before physical projection. The
        # same producer supplies ordinary executable binding report metadata.
        transaction_binding_report_products => _clone_isf_value(_transaction_port_binding_metadata($actor)),
        # These products are not executable IR. A projected actor must pass
        # build_module, including collision checks, before any emission.
        deferred_formal_collisions => \%deferred,
        parent_activation_products => $activation_products,
        parent_wiring_products => $wiring_products,
        parent_point_products => $point_products,
        parent_payload_snapshot_products => $payload_products,
        resource_signal_products => $resource_products,
        parent_completion_products => $completion_products,
        parent_storage_write_products => _clone_isf_value($write_products),
        parent_storage_read_products => _clone_isf_value($read_products),
        parent_named_completion_products => _clone_isf_value($named_completion_products),
        # Real children have independent module scopes. Detach both retained
        # views; parent ownership connections and outer domains remain separate.
        generated_child_products => _clone_isf_value({
            map { $_ => $child_products->{children}{$_} } sort keys %$generated,
        }),
        reusable_child_products => _clone_isf_value({
            children => {map { $_ => $child_products->{children}{$_} }
                grep { !$generated->{$_} } sort keys %{$child_products->{children}}},
            library_uses => $child_products->{library_uses},
            atl_top_instances => $child_products->{atl_top_instances},
        }),
        actor_context => {
            locals => {}, static_symbols => { %$static },
            static_count_symbols => { %$static }, pruned_repeats => {},
            named_drives => { %drives },
        },
    };
}

sub _formal_local_completion_contracts {
    my ($actor, $completion, $activation, $generated, $transactions, $children) = @_;
    my %targets;
    for my $spawn (@{$activation->{spawn_instances}}) {
        my $child = $children->{$spawn->{child}} || next;
        $targets{$_->{name}} = 1 for @{$child->{actor_completion_outputs} || []};
    }
    my @blocks = (@{$completion->{states}}, @{$activation->{dt_blocks}});
    for my $tx (@{$actor->{transactions}}) {
        next if $generated->{$tx->{name}} || !exists $transactions->{$tx->{name}};
        push @blocks, @{$transactions->{$tx->{name}}{dt_blocks}};
    }
    my %completed = map { $_->{lhs} => 1 }
        grep { ($_->{source_kind} // '') eq 'complete_pulse' }
        map { @{$_->{assignments} || []} } @blocks;
    my %contracts;
    for my $output (@{$actor->{interface}{outputs} || []}) {
        next unless $completed{$output->{name}} && $targets{$output->{name}};
        $contracts{$output->{name}} = {
            width => $output->{width} // 1,
            reset_value => $output->{reset_value} // 0,
            (defined($output->{type}) ? (type => $output->{type}) : ()),
        };
    }
    return \%contracts;
}

sub _formal_parent_declaration_names {
    my ($actor, $generated, $products, $activation, $wiring, $points, $resources) = @_;
    # Parent helper allocation reads declaration membership, not widths or roles.
    # Keep that namespace separate from all raw transaction declarations: their
    # widths may conflict before physical formal allocation.
    my %storage = _declared_storage_signal_widths($actor);
    my %names = map { $_ => 1 } grep { defined $_ } (
        keys %storage, $actor->{clock}, (($actor->{reset} || {})->{name} // ()),
        (map { $_->{name} } @{_actor_constant_declarations($actor)},
            @{_actor_param_declarations($actor)}, @{$wiring->{ports}},
            @{$points->{states}}, @{$activation->{dt_blocks}}),
        (map { keys %{$_->{counters}} } $activation, $wiring, $points),
        (map { $_->{declaration}{name} } @$resources),
    );
    for my $tx (@{$actor->{transactions}}) {
        my $name = $tx->{name};
        next if $generated->{$name} || !exists $products->{$name};
        my $product = $products->{$name};
        $names{$_} = 1 for keys %{$product->{counters}}, keys %{$product->{signal_widths}},
            map { $_->{name} } @{$product->{dt_blocks}};
    }
    for my $movement (@{(($actor->{actor_network} || {})->{data_movements}) || []}) {
        for my $field (qw(source_signal sink_signal)) {
            my $name = $movement->{$field};
            $names{$name} = 1 if defined($name) && !ref($name);
        }
    }
    return \%names;
}

sub _formal_parent_completion_products {
    my ($actor, $declaration_names, $activation, $points) = @_;
    my %names = %$declaration_names;
    # This detached phase context is never finalized or emitted. The counter
    # inputs are membership only; returned counter widths come from fresh
    # signal_widths populated exclusively by the real completion producer.
    my $context = {
        actor_name => $actor->{actor_name}, counters => \%names,
        states => _clone_isf_value($points->{states}),
        spawn_instances => _clone_isf_value($activation->{spawn_instances}),
        signal_widths => {}, storage_roles => {}, reset_values => {},
        dt_blocks => [], explicit_internal_signals => [],
    };
    my $allocation = retain_child_completions($context) || {input_names => {}, instances => {}};
    return _clone_isf_value({
        %$allocation, counters => $context->{signal_widths},
        map { $_ => $context->{$_} } qw(states signal_widths storage_roles reset_values
            dt_blocks explicit_internal_signals),
    });
}

sub _formal_resource_signal_products {
    my ($actor) = @_;
    my @declarations;
    for my $resource (@{$actor->{resources} || []}) {
        next unless ($resource->{arbiter} // '') eq 'round_robin'
            && _resource_kind_supports_round_robin_rule_users($resource->{kind})
            && @{$resource->{users} || []};
        push @declarations, {
            resource => $resource->{name}, kind => $resource->{kind},
            declaration => _round_robin_pointer_declaration($resource->{name}, $resource->{users}),
        };
    }
    # Potential declarations only. User/member/grant and physical collision
    # admission still belong to executable arbitration; no grants are fabricated.
    return _clone_isf_value([sort {$a->{resource} cmp $b->{resource}} @declarations]);
}

sub _formal_parent_point_products($self, $actor, $generated, $products, $wiring_products, $points) {
    my $states = _clone_isf_value($wiring_products->{states});
    my @assertions;
    for my $tx (@{$actor->{transactions}}) {
        my $name = $tx->{name};
        next if $generated->{$name} || !exists $products->{$name};
        push @assertions, @{_clone_isf_value($products->{$name}{immediate_assertions})};
    }
    my %counters;
    my %defaults = _declared_interface_output_default_values($actor);
    _resolve_at_references(\@assertions, $points, $states, \%counters);
    _apply_interface_output_defaults_to_entry_states($states, \%defaults);
    # Only products of this stage: generated point counters and resolved checks
    # remain separate from transaction declarations and earlier wiring products.
    return _clone_isf_value({
        states => $states, counters => \%counters, immediate_assertions => \@assertions,
        point_bindings => $points, output_defaults => \%defaults,
    });
}

sub _formal_parent_wiring_products($self, $actor, $generated, $products, $activation_products) {
    my @states;
    for my $tx (@{$actor->{transactions}}) {
        my $name = $tx->{name};
        next if $generated->{$name} || !exists $products->{$name};
        push @states, @{_clone_isf_value($products->{$name}{states})};
    }
    my $ports = _clone_isf_value($activation_products->{ports});
    # These producers only add/promote handshake counters; they do not read
    # counter widths. Keep their additions separate from the still-unallocated
    # transaction maps instead of merging potentially conflicting declarations.
    my %counters;
    $self->_wire_do_children(\@states, \%counters, $actor, $generated);
    $self->_wire_external_activations(\@states, $ports, \%counters, $actor);
    return _clone_isf_value({states => \@states, ports => $ports, counters => \%counters});
}

sub _formal_parent_activation_products($self, $actor, $generated, $products) {
    my $ports = $self->_build_ports($actor);
    my (%counters, %roles, %local_drive_callers, %spawn_drive_sources);
    my (@dts, @rule_trigger_dts, @bank_accesses, @instances);
    my %transactions = map { $_->{name} => $_ } @{$actor->{transactions}};
    for my $tx (@{$actor->{transactions}}) {
        my $name = $tx->{name};
        next if $generated->{$name} || !exists $products->{$name};
        my %uses = _collect_named_drive_call_names($tx->{clauses}, $actor->{drives} || {});
        $local_drive_callers{$_}{$name} = 1 for keys %uses;
        # Registration replaces source binding records with handoff metadata.
        # Never let that mutation reach the retained transaction products.
        for my $instance (@{_clone_isf_value($products->{$name}{spawn_refs})}) {
            _register_generated_activation_instance($instance, $name, 'transaction',
                $actor, $ports, \%counters, \%roles, \@dts, \%transactions,
                \%spawn_drive_sources);
            push @instances, $instance;
        }
    }
    for my $instance (_rule_trigger_generated_refs($actor, $generated)) {
        _register_generated_activation_instance($instance, $instance->{owner}, 'rule',
            $actor, $ports, \%counters, \%roles, \@rule_trigger_dts, \%transactions,
            \%spawn_drive_sources);
        push @instances, $instance;
    }
    push @dts, $self->_build_rules($actor, \%counters, \@bank_accesses, $generated, \%roles);
    push @dts, @rule_trigger_dts;
    my $local_filter = keys(%$generated)
        ? {map {$_ => 1} keys %local_drive_callers} : undef;
    $self->_build_drive_dts($actor, \@dts, \%counters, $local_filter,
        \%local_drive_callers, \%spawn_drive_sources, \%roles);
    # These are actual producer products, not a parent IR. No transaction maps
    # are merged and no finalization, ownership connection or emission occurs.
    return _clone_isf_value({
        ports => $ports, counters => \%counters, storage_roles => \%roles,
        dt_blocks => \@dts, bank_accesses => \@bank_accesses,
        spawn_instances => \@instances,
    });
}

sub _formal_expression_static_symbols {
    my ($actor) = @_;
    my %names = map { $_->{name} => 1 }
        (@{_actor_constant_declarations($actor)}, @{_actor_param_declarations($actor)});
    my $enums = $actor->{enum_symbols} || {};
    for my $name (keys %{$enums->{local} || {}}) {
        $names{"$name.$_"} = 1 for keys %{$enums->{local}{$name}};
    }
    my $constants = ($actor->{constant_symbols} || {})->{packages} || {};
    my %packages = map { $_ => 1 } (keys %$constants, keys %{$enums->{packages} || {}});
    for my $package (keys %packages) {
        my $symbols = FSM::Package::Symbols->new(constants => $constants->{$package} || {});
        $names{"$package.$_"} = 1 for
            keys %{$symbols->constant_scalar_leaves}, keys %{$symbols->constant_aggregate_paths};
        for my $enum (keys %{$enums->{packages}{$package} || {}}) {
            $names{"$package.$enum.$_"} = 1 for keys %{$enums->{packages}{$package}{$enum}};
        }
    }
    return \%names;
}

# The detached output-view planner uses the same resolved static namespace as
# formal lowering. Do not reconstruct imported constants or enum paths there.
sub child_output_read_scope($self, $actor, $tx) {
    confess "Child output reads require an actual source transaction\n"
        unless ref($actor) eq 'HASH' && ref($tx) eq 'HASH'
            && grep { refaddr($_) == refaddr($tx) } @{$actor->{transactions} || []};
    my ($index) = grep {refaddr($actor->{transactions}[$_]) == refaddr($tx)}
        0 .. $#{$actor->{transactions}};
    $actor = _clone_isf_value($actor);
    $tx = $actor->{transactions}[$index];
    my %locals = map { $_->[1] => 1 }
        grep { ref($_) eq 'ARRAY' && @$_ && $_->[0] eq 'local' }
        @{$tx->{clauses} || []};
    my %ports = _transaction_port_map($tx);
    $locals{$_} = 1 for keys %ports, map { $_->{source_name} } values %ports;
    my %static = (%{_formal_expression_static_symbols($actor)},
        map { $_->{name} => 1 } @{_transaction_param_declarations($tx, $actor)});
    return {
        locals => \%locals, static_symbols => \%static,
        constants => _actor_constant_declarations($actor),
        params => _transaction_param_declarations($tx, $actor),
        enum_declarations => _actor_enum_declarations($actor),
        type_declarations => _actor_type_declarations($actor),
        package_imports => _actor_package_imports($actor),
        package_roots => _actor_package_roots($actor),
    };
}

sub _formal_pruned_repeat_paths {
    my ($clauses, $path, $actor, $owner, $pruned, $start) = @_;
    $start //= 0;
    for my $i ($start .. $#$clauses) {
        my $cl = $clauses->[$i];
        next unless ref($cl) eq 'ARRAY' && @$cl;
        my @here = (@$path, $i);
        if ($cl->[0] eq 'repeat' && _is_static_zero_repeat_count($cl->[1], $actor, $owner)) {
            $pruned->{join('/', @here)} = 1;
        } elsif ($cl->[0] =~ /\A(?:when|while|until|repeat)\z/) {
            # Keep source array indexes, including the opcode and condition slots.
            _formal_pruned_repeat_paths($cl, \@here, $actor, $owner, $pruned, 2);
        } elsif ($cl->[0] eq 'switch') {
            for my $branch (2 .. $#$cl) {
                _formal_pruned_repeat_paths($cl->[$branch], [@here, $branch], $actor, $owner, $pruned, 1);
            }
        }
    }
}

# --- Child IR (separate module) ---

sub _build_child_ir($self, $tx, $actor, $cname) {
    my %point_bindings;   # ISF-TRIGGER-ANCHOR.5
    my ($states, $ctrs, $dts, $do_children, $spawn_refs, $contracts, $signal_widths, $storage_roles, $bank_accesses, $reset_values, $asserts) =
        $self->_build_transaction($tx, $actor, 0, undef, \%point_bindings);
    _resolve_at_references($asserts, \%point_bindings, $states, $ctrs);
    $states = [@$states]; $ctrs = { %$ctrs }; $dts = [@$dts];
    my %local_ports = map { $_->{name} => 1 }
        map { @{($tx->{ports} || {})->{$_} || []} } qw(inputs outputs);
    # Actor metadata belongs to actor identities, not same-named child ports.
    # Remove inherited entries before merging the transaction's own declarations.
    my %module_reset_values = (
        _declared_storage_reset_values($actor),
        _declared_interface_output_reset_values($actor),
    );
    my %module_signal_widths = _declared_storage_signal_widths($actor);
    my %module_storage_roles = _declared_storage_roles($actor);
    my %module_signal_type_refs = (
        _actor_interface_signal_type_refs($actor),
        _declared_storage_signal_type_refs($actor),
    );
    for my $map (\%module_reset_values, \%module_signal_widths,
                 \%module_storage_roles, \%module_signal_type_refs) {
        delete @{$map}{keys %local_ports};
    }
    $module_reset_values{$_} = $reset_values->{$_} for keys %{$reset_values || {}};
    _merge_signal_type_refs(\%module_signal_type_refs, { _transaction_port_signal_type_refs($tx) });
    _merge_signal_widths(\%module_signal_widths, $signal_widths, $tx->{name});
    _merge_storage_roles(\%module_storage_roles, $storage_roles, $tx->{name});

    my %used_drives = _collect_named_drive_call_names($tx->{clauses}, $actor->{drives} || {});
    _register_drive_call_signal_widths($actor, $ctrs, \%used_drives, \%module_storage_roles);

    my $ports = $self->_build_child_ports($actor, $tx, $states, $dts, \%used_drives);

    my $ir = {
        actor_name => $cname,
        clock      => $actor->{clock},
        reset      => $actor->{reset},
        reset_provenance => _clone_isf_value($actor->{reset_provenance}),
        # Generated transaction ports are private, not actor declarations.
        interface_port_metadata => undef,
        watchdog   => $actor->{watchdog},
        actor_phases => _actor_metadata_declarations($actor, 'phases'),
        actor_stages => _actor_metadata_declarations($actor, 'stages'),
        verification_observations => _verification_observation_declarations($actor),
        verification_bridge => _verification_bridge_declaration($actor),
        package_imports => _actor_package_imports($actor),
        package_roots => _actor_package_roots($actor),
        type_declarations => _actor_type_declarations($actor),
        enum_declarations => _actor_enum_declarations($actor),
        constants  => _actor_constant_declarations($actor),
        params     => _transaction_param_declarations($tx, $actor),
        ports      => $ports,
        states     => $states,
        dt_blocks  => $dts,
        counters   => $ctrs,
        declared_storage => _declared_storage_for_ir($actor),
        signal_widths => \%module_signal_widths,
        signal_type_refs => \%module_signal_type_refs,
        storage_roles => \%module_storage_roles,
        reset_values => \%module_reset_values,
        children   => {},
        temporal_contracts => $contracts,
        immediate_assertions => ($asserts || []),
        bank_accesses => $bank_accesses,
    };

    prepare_child_completion_outputs($ir, $tx, $actor);
    prepare_child_storage_writes($ir, $tx);
    select_child_storage_reads($ir, $tx, $actor);
    $ir->{explicit_interface_ports} = [map { { %$_ } } @{$ir->{ports}}];

    # Inject entry state if missing (spawn targets need start handshake)
    if (!(grep { $_->{kind} eq 'entry' } @{$ir->{states}})) {
        unshift @{$ir->{states}}, {
            name        => "${cname}_idle_0",
            kind        => 'entry',
            transaction => $tx->{name},
            guard       => { port => 'start' },
            assignments => [],
            transitions => [],
        };
        # Link idle -> first state
        $ir->{states}[0]{transitions} = [{ target => $ir->{states}[1]{name}, condition => $ir->{states}[0]{guard} }];
    }

    my ($entry) = grep { $_->{kind} eq 'entry' } @{$ir->{states}};
    if ($entry) {
        $entry->{guard} = { port => 'start' };
        $entry->{transitions} = [];
        my ($n) = grep { $_->{kind} ne 'entry' && $_->{name} !~ /_timeout$/ } @{$ir->{states}};
        push @{$entry->{transitions}}, { target => $n->{name}, condition => $entry->{guard} } if $n;

        for my $state (@{$ir->{states}}) {
            next unless $state->{kind} eq 'terminal';
            $state->{transitions} = [{ target => $entry->{name} }];
        }
    }
    guard_child_activation($ir, $entry) if $entry;
    FSM::Scheduler::ISF::RecordSamples->apply_to_module($ir, $actor, [$tx]);
    _finalize_ir($ir);
    $ir->{logical_controllers} = FSM::Scheduler::ISF::LogicalControllers->inventory($ir, $actor);
    return $ir;
}

sub _build_library_child_ir($self, $use, $parent_actor) {
    my $child_actor = _clone_isf_value($use->{actor});
    confess "Library use '$use->{instance}' does not carry a reusable actor shell\n"
        unless ref($child_actor) eq 'HASH';

    $child_actor->{actor_name} = $use->{module};
    my $ir = $self->_build_parent_ir($child_actor, {});
    $ir->{library_origin} = {
        parent_actor   => $parent_actor->{actor_name},
        library        => $use->{library},
        export         => $use->{export},
        instance       => $use->{instance},
        library_source => $use->{library_source},
    };
    return $ir;
}

sub _build_resolved_atl_child_ir($self, $resolution, $parent_actor) {
    my $child_actor = _clone_isf_value($resolution->{actor});
    confess "ATL static actor instance '$resolution->{instance}' does not carry a resolved actor shell\n"
        unless ref($child_actor) eq 'HASH';

    $child_actor->{actor_name} = $resolution->{module};
    my $ir = $self->_build_parent_ir($child_actor, {});
    $ir->{library_origin} = {
        parent_actor   => $parent_actor->{actor_name},
        library        => $resolution->{library},
        export         => $resolution->{export},
        instance       => $resolution->{instance},
        library_source => $resolution->{library_source},
        usage          => 'atl_static_instance',
    };
    return $ir;
}

sub _select_atl_generated_top_instances($self, $actor, $child_irs) {
    my @resolutions = _resolved_atl_actor_type_resolutions($actor);
    return () unless @resolutions;

    my $network = $actor->{actor_network} || {};
    my @triggers = grep { ($_->{context} // '') eq 'transaction_body' }
        @{$network->{transaction_triggers} || []};
    my @event_waits = @{$network->{event_waits} || []};
    my @data_movements = @{$network->{data_movements} || []};
    return () unless @triggers || @event_waits;

    my $actor_name = $actor->{actor_name};
    my $context = "ATL generated top for actor '$actor_name'";

    confess "$context cannot combine generated child wiring with static group metadata in the current subset\n"
        if @{$network->{groups} || []};
    my $has_temporary_schedule_metadata =
        @{$network->{association_schedules} || []} || @{$network->{group_schedules} || []};
    my $uses_selected_trigger_batch_top = _is_selected_atl_trigger_batch_generated_top(
        $network,
        \@resolutions,
        \@triggers,
        \@event_waits,
        \@data_movements,
    );
    confess "$context cannot combine generated child wiring with temporary association or group schedules except for the selected two-resolved-child temporary trigger-batch generated top; that subset requires exactly two resolved children, one same-cycle transaction-body trigger batch, source-ordered waits to both triggered children, no static group metadata, and no ATL data movement\n"
        if $has_temporary_schedule_metadata && !$uses_selected_trigger_batch_top;

    my $top_module = "${actor_name}_top";
    confess "$context generated top module '$top_module' conflicts with a generated child module\n"
        if exists $child_irs->{$top_module};

    if (@resolutions == 2 && @triggers == 2 && @event_waits == 2 && !@data_movements) {
        my %resolution_by_instance = map { $_->{instance} => $_ } @resolutions;
        my %seen_instance;
        my @children;
        for my $index (0 .. 1) {
            my $trigger = $triggers[$index];
            my $event_wait = $event_waits[$index];
            my $instance = $trigger->{instance};
            confess "$context two-child handoff pair requires trigger and event to target the same resolved actor instance\n"
                unless defined($instance)
                    && length($instance)
                    && ($event_wait->{instance} // '') eq $instance;
            confess "$context two-child handoff sequence targets instance '$instance' more than once in the current subset\n"
                if $seen_instance{$instance}++;
            confess "$context cannot find resolved actor metadata for child instance '$instance'\n"
                unless exists $resolution_by_instance{$instance};
            push @children, _atl_generated_top_child_entry(
                $context,
                $actor,
                $child_irs,
                $resolution_by_instance{$instance},
                $trigger,
                $event_wait,
                [],
            );
        }

        return ({
            kind                 => $uses_selected_trigger_batch_top
                ? 'resolved_children_trigger_batch_event_sequence'
                : 'resolved_children_trigger_event_sequence',
            top_module           => $top_module,
            top_fsm              => "$top_module.fsm",
            parent_module        => $actor_name,
            parent_scheduled_fsm => "$actor_name.fsm",
            children             => \@children,
            clock                => $actor->{clock},
            reset                => ref($actor->{reset}) eq 'HASH' ? $actor->{reset}{name} : undef,
        });
    }

    if (@resolutions == 2
        && @data_movements >= 1
        && !(grep { !_is_atl_actor_route_handoff_kind($_->{kind} // '') } @data_movements)
        && (@triggers >= 2 || @event_waits >= 2))
    {
        confess "$context two-child data route requires exactly one transaction trigger per source and sink child in the current subset; repeated activation remains deferred\n"
            unless @triggers == 2;
        confess "$context two-child data route requires exactly one event wait per source and sink child in the current subset; repeated waits remain deferred\n"
            unless @event_waits == 2;

        my $movement = $data_movements[0];
        for my $route (@data_movements) {
            confess "$context two-child data route requires all generated-child actor-to-actor data movements to share the same source and sink child in the current subset; fan-in and fan-out remain deferred\n"
                unless ($route->{source_instance} // '') eq ($movement->{source_instance} // '')
                    && ($route->{sink_instance} // '') eq ($movement->{sink_instance} // '');
        }
        my @ordered_instances = ($movement->{source_instance}, $movement->{sink_instance});
        my %resolution_by_instance = map { $_->{instance} => $_ } @resolutions;
        my %seen_instance;
        my @child_specs;
        my @route_owners = map { $_->{transaction} } @data_movements;
        my @children;

        for my $instance (@ordered_instances) {
            confess "$context two-child data route references an empty child instance name\n"
                unless defined($instance) && length($instance);
            confess "$context two-child data route targets instance '$instance' more than once in the current subset\n"
                if $seen_instance{$instance}++;
            confess "$context cannot find resolved actor metadata for data-route child instance '$instance'\n"
                unless exists $resolution_by_instance{$instance};

            my $trigger = _single_atl_entry_for_instance($context, \@triggers, $instance, 'transaction trigger');
            my $event_wait = _single_atl_entry_for_instance($context, \@event_waits, $instance, 'event wait');
            push @route_owners, $trigger->{owner_transaction}, $event_wait->{transaction};
            push @child_specs, [
                $resolution_by_instance{$instance},
                $trigger,
                $event_wait,
            ];
        }

        my %route_owners = map { $_ => 1 }
            grep { defined($_) && !ref($_) && length($_) } @route_owners;
        confess "$context two-child data route requires source trigger, source event wait, data drive call, sink trigger, and sink event wait to belong to one parent transaction in the current subset; cross-transaction route continuation remains deferred\n"
            unless keys(%route_owners) == 1;
        my ($route_transaction_name) = keys %route_owners;
        my ($transaction) = grep { ($_->{name} // '') eq $route_transaction_name }
            @{$actor->{transactions} || []};
        confess "$context two-child data route cannot find parent transaction '$route_transaction_name'\n"
            unless ref($transaction) eq 'HASH' && ref($transaction->{clauses}) eq 'ARRAY';

        my @route_indices = _atl_two_child_data_route_clause_indices(
            $context,
            $transaction,
            \@child_specs,
            \@data_movements,
        );

        for my $idx (1 .. $#route_indices) {
            confess "$context two-child data route requires source trigger, source event wait, data drive call, sink trigger, and sink event wait in that order\n"
                unless $route_indices[$idx - 1] < $route_indices[$idx];
        }
        for my $idx (1 .. $#route_indices) {
            confess "$context two-child data route requires source trigger, source event wait, data drive call, sink trigger, and sink event wait to be contiguous in the current subset; interleaved parent work remains deferred\n"
                unless $route_indices[$idx] == $route_indices[$idx - 1] + 1;
        }

        my $clauses = $transaction->{clauses};
        my $first_route_index = $route_indices[0];
        my $last_route_index = $route_indices[-1];
        my $start_boundary_count = 0;
        my $completion_boundary_count = 0;
        my %parent_input_widths = map { $_->{name} => ($_->{width} // 1) }
            @{$actor->{interface}{inputs} || []};
        my %parent_output_widths = map { $_->{name} => ($_->{width} // 1) }
            @{$actor->{interface}{outputs} || []};
        for my $clause_idx (0 .. $#$clauses) {
            next if $clause_idx >= $first_route_index && $clause_idx <= $last_route_index;
            my $clause = $clauses->[$clause_idx];
            if ($clause_idx < $first_route_index) {
                confess "$context two-child data route requires simple '(on PORT)' and '(complete PORT)' boundaries around the route in the current subset; activation-body samples and completion payloads remain deferred\n"
                    if ref($clause) eq 'ARRAY'
                        && @$clause
                        && ($clause->[0] // '') eq 'on'
                        && !(@$clause == 2
                            && defined($clause->[1])
                            && !ref($clause->[1])
                            && length($clause->[1]));
                confess "$context two-child data route requires the route segment to be the only executable parent transaction-body work in the current subset; pre/post route parent work remains deferred\n"
                    unless ref($clause) eq 'ARRAY'
                        && @$clause == 2
                        && ($clause->[0] // '') eq 'on'
                        && defined($clause->[1])
                        && !ref($clause->[1])
                        && length($clause->[1]);
                confess "$context two-child data route requires scalar parent interface boundaries '(on INPUT_PIN)' and '(complete OUTPUT_PIN)' in the current subset; interface remapping and boundary expressions remain deferred\n"
                    unless exists $parent_input_widths{$clause->[1]}
                        && ($parent_input_widths{$clause->[1]} || 1) == 1;
                ++$start_boundary_count;
                next;
            }
            confess "$context two-child data route requires simple '(on PORT)' and '(complete PORT)' boundaries around the route in the current subset; activation-body samples and completion payloads remain deferred\n"
                if ref($clause) eq 'ARRAY'
                    && @$clause
                    && ($clause->[0] // '') eq 'complete'
                    && !(@$clause == 2
                        && defined($clause->[1])
                        && !ref($clause->[1])
                        && length($clause->[1]));
            confess "$context two-child data route requires the route segment to be the only executable parent transaction-body work in the current subset; pre/post route parent work remains deferred\n"
                unless ref($clause) eq 'ARRAY'
                    && @$clause == 2
                    && ($clause->[0] // '') eq 'complete'
                    && defined($clause->[1])
                    && !ref($clause->[1])
                    && length($clause->[1]);
            confess "$context two-child data route requires scalar parent interface boundaries '(on INPUT_PIN)' and '(complete OUTPUT_PIN)' in the current subset; interface remapping and boundary expressions remain deferred\n"
                unless exists $parent_output_widths{$clause->[1]}
                    && ($parent_output_widths{$clause->[1]} || 1) == 1;
            ++$completion_boundary_count;
        }
        confess "$context two-child data route requires exactly one start boundary and exactly one completion boundary around the route in the current subset; activation fan-in and completion fan-out remain deferred\n"
            unless $start_boundary_count == 1
                && $completion_boundary_count == 1;

        _validate_atl_two_child_route_generated_handoffs(
            $context,
            $actor,
            \@data_movements,
            \@child_specs,
        );

        for my $child_spec (@child_specs) {
            push @children, _atl_generated_top_child_entry(
                $context,
                $actor,
                $child_irs,
                $child_spec->[0],
                $child_spec->[1],
                $child_spec->[2],
                \@data_movements,
            );
        }

        return ({
            kind                 => 'resolved_children_trigger_event_sequence',
            top_module           => $top_module,
            top_fsm              => "$top_module.fsm",
            parent_module        => $actor_name,
            parent_scheduled_fsm => "$actor_name.fsm",
            children             => \@children,
            clock                => $actor->{clock},
            reset                => ref($actor->{reset}) eq 'HASH' ? $actor->{reset}{name} : undef,
        });
    }

    confess "$context requires exactly one resolved ATL static actor instance in the current subset\n"
        unless @resolutions == 1;
    confess "$context requires exactly one transaction trigger and exactly one event wait in the current subset\n"
        unless @triggers == 1 && @event_waits == 1;

    my $resolution = $resolutions[0];
    my $instance = $resolution->{instance};
    my $module = $resolution->{module};
    my $trigger = $triggers[0];
    my $event_wait = $event_waits[0];

    confess "$context requires trigger and event handoffs to target the same resolved actor instance '$instance'\n"
        unless ($trigger->{instance} // '') eq $instance
            && ($event_wait->{instance} // '') eq $instance;
    confess "$context requires trigger and event handoffs to belong to the same parent transaction\n"
        unless ($trigger->{owner_transaction} // '') eq ($event_wait->{transaction} // '');
    confess "$context expects the selected trigger sink to be an external handoff before top wiring\n"
        unless ($trigger->{sink} // '') eq 'external_handoff';
    confess "$context expects the selected event source to be an external handoff before top wiring\n"
        unless ($event_wait->{source} // '') eq 'external_handoff';

    my $child = _atl_generated_top_child_entry(
        $context,
        $actor,
        $child_irs,
        $resolution,
        $trigger,
        $event_wait,
        \@data_movements,
    );

    return ({
        kind                 => 'resolved_child_trigger_event_handoff',
        top_module           => $top_module,
        top_fsm              => "$top_module.fsm",
        parent_module        => $actor_name,
        parent_scheduled_fsm => "$actor_name.fsm",
        instance             => $child->{instance},
        child_module         => $child->{child_module},
        child_scheduled_fsm  => $child->{child_scheduled_fsm},
        target_transaction   => $child->{target_transaction},
        trigger_parent_port  => $child->{trigger_parent_port},
        trigger_child_port   => $child->{trigger_child_port},
        event                => $child->{event},
        event_parent_port    => $child->{event_parent_port},
        event_child_port     => $child->{event_child_port},
        data_links           => $child->{data_links},
        clock                => $actor->{clock},
        reset                => ref($actor->{reset}) eq 'HASH' ? $actor->{reset}{name} : undef,
    });
}

sub _is_selected_atl_trigger_batch_generated_top {
    my ($network, $resolutions, $triggers, $event_waits, $data_movements) = @_;
    my @associations = @{($network || {})->{association_schedules} || []};
    my @group_schedules = @{($network || {})->{group_schedules} || []};
    return 0 unless @associations == 1 && @group_schedules == 1;
    return 0 unless ref($resolutions) eq 'ARRAY' && @$resolutions == 2;
    return 0 unless ref($triggers) eq 'ARRAY' && @$triggers == 2;
    return 0 unless ref($event_waits) eq 'ARRAY' && @$event_waits == 2;
    return 0 if ref($data_movements) eq 'ARRAY' && @$data_movements;

    my $association = $associations[0];
    my $group_schedule = $group_schedules[0];
    return 0 unless ref($association) eq 'HASH' && ref($group_schedule) eq 'HASH';
    return 0 unless ($association->{kind} // '') eq 'temporary_trigger_batch';
    return 0 unless ($association->{lifetime} // '') eq 'task_scoped';
    return 0 unless ($group_schedule->{group} // '') eq ($association->{association} // '');

    for my $entry ($association, $group_schedule) {
        return 0 unless ($entry->{context} // '') eq 'transaction_body';
        return 0 unless ($entry->{schedule} // '') eq 'same_cycle_external_trigger_batch';
        return 0 unless ($entry->{storage} // '') eq 'none';
        return 0 unless ($entry->{source} // '') eq 'parent_trigger_state';
        return 0 unless ($entry->{sink} // '') eq 'external_handoff';
    }

    my @trigger_instances = map { $_->{instance} // '' } @$triggers;
    my @trigger_targets = map { $_->{target_transaction} // '' } @$triggers;
    my @trigger_signals = map { $_->{signal} // '' } @$triggers;
    my @event_instances = map { $_->{instance} // '' } @$event_waits;
    my @schedule_members = @{$association->{members} || []};
    my @schedule_targets = @{$association->{target_transactions} || []};
    my @schedule_signals = @{$association->{signals} || []};
    return 0 unless join("\0", @trigger_instances) eq join("\0", @event_instances);
    return 0 unless join("\0", @trigger_instances) eq join("\0", @schedule_members);
    return 0 unless join("\0", @trigger_targets) eq join("\0", @schedule_targets);
    return 0 unless join("\0", @trigger_signals) eq join("\0", @schedule_signals);

    for my $entry ($group_schedule) {
        return 0 unless join("\0", @trigger_instances) eq join("\0", @{$entry->{members} || []});
        return 0 unless join("\0", @trigger_targets) eq join("\0", @{$entry->{target_transactions} || []});
        return 0 unless join("\0", @trigger_signals) eq join("\0", @{$entry->{signals} || []});
    }

    my %owner_transactions = map { ($_->{owner_transaction} // '') => 1 } @$triggers;
    return 0 unless keys(%owner_transactions) == 1;
    my ($owner_transaction) = keys %owner_transactions;
    return 0 if $owner_transaction eq '';
    return 0 unless ($association->{owner_transaction} // '') eq $owner_transaction;
    return 0 unless ($group_schedule->{owner_transaction} // '') eq $owner_transaction;

    for my $trigger (@$triggers) {
        return 0 unless ($trigger->{context} // '') eq 'transaction_body';
        return 0 unless ($trigger->{sink} // '') eq 'external_handoff';
    }
    for my $wait (@$event_waits) {
        return 0 unless ($wait->{transaction} // '') eq $owner_transaction;
        return 0 unless ($wait->{context} // '') eq 'transaction_body';
        return 0 unless ($wait->{source} // '') eq 'external_handoff';
    }

    return 1;
}

sub _atl_two_child_data_route_clause_indices($context, $transaction, $child_specs, $data_movements) {
    my @clauses = @{($transaction || {})->{clauses} || []};
    my (%trigger_indices_by_signal, %wait_indices_by_signal, %drive_indices_by_name);

    for my $clause_idx (0 .. $#clauses) {
        my $clause = $clauses[$clause_idx];
        next unless ref($clause) eq 'ARRAY' && @$clause >= 2;
        my ($head, $name) = @$clause[0, 1];
        next unless defined($head) && !ref($head)
            && defined($name) && !ref($name) && length($name);

        if ($head eq 'atl_trigger') {
            push @{$trigger_indices_by_signal{$name}}, $clause_idx;
            next;
        }
        if ($head eq 'await') {
            push @{$wait_indices_by_signal{$name}}, $clause_idx;
            next;
        }
        if ($head eq 'drive') {
            push @{$drive_indices_by_name{$name}}, $clause_idx;
            next;
        }
    }

    my $source_trigger_index = _single_atl_clause_index(
        $context,
        'source transaction trigger handoff',
        $child_specs->[0][1]{signal},
        \%trigger_indices_by_signal,
    );
    my $source_wait_index = _single_atl_clause_index(
        $context,
        'source event wait handoff',
        $child_specs->[0][2]{signal},
        \%wait_indices_by_signal,
    );
    my $sink_trigger_index = _single_atl_clause_index(
        $context,
        'sink transaction trigger handoff',
        $child_specs->[1][1]{signal},
        \%trigger_indices_by_signal,
    );
    my $sink_wait_index = _single_atl_clause_index(
        $context,
        'sink event wait handoff',
        $child_specs->[1][2]{signal},
        \%wait_indices_by_signal,
    );
    my @drive_indices = sort { $a <=> $b }
        map {
            _single_atl_clause_index(
                $context,
                'data movement drive call',
                $_->{drive},
                \%drive_indices_by_name,
            )
        } @{$data_movements || []};

    return (
        $source_trigger_index,
        $source_wait_index,
        @drive_indices,
        $sink_trigger_index,
        $sink_wait_index,
    );
}

sub _single_atl_clause_index($context, $label, $name, $indices_by_name) {
    confess "$context two-child data route requires $label to reference a scalar transaction-body clause name\n"
        unless defined($name) && !ref($name) && length($name);

    my $indices = $indices_by_name->{$name} || [];
    confess "$context two-child data route requires $label '$name' to appear exactly once in the selected parent transaction body\n"
        unless @$indices == 1;

    return $indices->[0];
}

sub _validate_atl_two_child_route_generated_handoffs($context, $actor, $movements, $child_specs) {
    my %declared = _atl_parent_declared_signal_origins($actor);
    my %generated;
    my @movements = ref($movements) eq 'ARRAY' ? @$movements : ();

    my @handoffs;
    if (ref($child_specs) eq 'ARRAY' && @$child_specs >= 2) {
        push @handoffs,
            [ 'source trigger handoff', $child_specs->[0][1]{signal} ],
            [ 'source event handoff',   $child_specs->[0][2]{signal} ],
            [ 'sink trigger handoff',   $child_specs->[1][1]{signal} ],
            [ 'sink event handoff',     $child_specs->[1][2]{signal} ];
    }

    for my $movement (@movements) {
        next unless ref($movement) eq 'HASH';
        push @handoffs,
            [ 'source data handoff', $movement->{source_signal} ],
            [ 'sink data handoff',   $movement->{sink_signal} ];

        my $drive = $movement->{drive};
        push @handoffs, [ 'named-drive request handoff', "${drive}_start" ]
            if defined($drive) && !ref($drive) && length($drive);
    }

    for my $handoff (@handoffs) {
        my ($role, $signal) = @$handoff;
        next unless defined($signal) && !ref($signal) && length($signal);

        if (my $origin = $declared{$signal}) {
            confess "$context two-child data route lowerer generated-handoff collision: $role signal '$signal' conflicts with $origin '$signal'\n";
        }

        if (my $prior_role = $generated{$signal}) {
            confess "$context two-child data route lowerer generated-handoff collision: $role signal '$signal' conflicts with already registered generated handoff '$signal' from $prior_role\n";
        }

        $generated{$signal} = $role;
    }
}

sub _atl_parent_declared_signal_origins($actor) {
    my %declared;

    for my $direction (qw(inputs outputs)) {
        for my $port (@{($actor->{interface} || {})->{$direction} || []}) {
            my $name = $port->{name};
            next unless defined($name) && !ref($name) && length($name);
            $declared{$name} //= 'parent interface port';
        }
    }

    for my $entry (@{$actor->{storage} || []}) {
        for my $signal (@{$entry->{signals} || []}) {
            my $name = $signal->{name};
            next unless defined($name) && !ref($name) && length($name);
            $declared{$name} //= 'declared actor-owned storage signal';
        }
    }

    return %declared;
}

sub _single_atl_entry_for_instance {
    my ($context, $entries, $instance, $label) = @_;
    my @matches = grep { ($_->{instance} // '') eq ($instance // '') } @{$entries || []};
    confess "$context two-child handoff sequence requires exactly one $label for child instance '$instance'\n"
        unless @matches == 1;
    return $matches[0];
}

sub _atl_generated_top_child_entry {
    my ($context, $actor, $child_irs, $resolution, $trigger, $event_wait, $data_movements) = @_;
    my $instance = $resolution->{instance};
    my $module = $resolution->{module};

    confess "$context cannot find resolved child module '$module'\n"
        unless exists $child_irs->{$module};

    my $child_actor = $resolution->{actor};
    confess "$context child instance '$instance' does not carry a resolved actor shell\n"
        unless ref($child_actor) eq 'HASH';
    confess "$context child instance '$instance' contains nested actor-network instances; recursive actor networks are deferred\n"
        if @{(($child_actor->{actor_network} || {})->{instances}) || []};
    confess "$context requires parent and child clocks to match before ATL child wiring; parent '$actor->{clock}' child '$child_actor->{clock}'\n"
        unless ($actor->{clock} // '') eq ($child_actor->{clock} // '');
    confess "$context requires parent and child reset policy to match before ATL child wiring\n"
        unless _atl_reset_signature($actor->{reset}) eq _atl_reset_signature($child_actor->{reset});

    my %child_tx_by_name = map { $_->{name} => $_ } @{$child_actor->{transactions} || []};
    my $target_transaction = $trigger->{target_transaction};
    my $child_tx = $child_tx_by_name{$target_transaction};
    confess "$context trigger targets missing child transaction '$target_transaction' on instance '$instance'\n"
        unless ref($child_tx) eq 'HASH';
    my $child_start_port = _atl_transaction_scalar_on_signal($child_tx, $context);

    my $child_ir = $child_irs->{$module};
    _ensure_atl_child_data_source_ports(
        $context,
        $instance,
        $child_ir,
        $child_actor,
        $data_movements,
    );
    my %child_ports = map { $_->{name} => $_ } @{$child_ir->{ports} || []};
    confess "$context child transaction '$target_transaction' scalar on signal '$child_start_port' is not a scalar child input port\n"
        unless exists($child_ports{$child_start_port})
            && ($child_ports{$child_start_port}{direction} || '') eq 'input'
            && ($child_ports{$child_start_port}{width} || 1) == 1;

    my $event_port = $event_wait->{event};
    confess "$context event '$event_port' is not a scalar child output port on instance '$instance'\n"
        unless exists($child_ports{$event_port})
            && ($child_ports{$event_port}{direction} || '') eq 'output'
            && ($child_ports{$event_port}{width} || 1) == 1;

    my @data_links = _atl_generated_top_data_links(
        $context,
        $instance,
        $trigger,
        $event_wait,
        $data_movements,
        \%child_ports,
    );

    return {
        instance             => $instance,
        child_module         => $module,
        child_scheduled_fsm  => "$module.fsm",
        target_transaction   => $target_transaction,
        trigger_parent_port  => $trigger->{signal},
        trigger_child_port   => $child_start_port,
        event                => $event_port,
        event_parent_port    => $event_wait->{signal},
        event_child_port     => $event_port,
        data_links           => \@data_links,
    };
}

sub _is_atl_actor_route_handoff_kind {
    my ($kind) = @_;
    return defined($kind)
        && !ref($kind)
        && ($kind eq 'scalar_actor_handoff' || $kind eq 'vector_actor_handoff');
}

sub _is_atl_pin_to_actor_handoff_kind {
    my ($kind) = @_;
    return defined($kind)
        && !ref($kind)
        && ($kind eq 'scalar_pin_to_actor_handoff' || $kind eq 'vector_pin_to_actor_handoff');
}

sub _is_atl_actor_to_pin_handoff_kind {
    my ($kind) = @_;
    return defined($kind)
        && !ref($kind)
        && ($kind eq 'scalar_actor_to_pin_handoff' || $kind eq 'vector_actor_to_pin_handoff');
}

sub _ensure_atl_child_data_source_ports {
    my ($context, $instance, $child_ir, $child_actor, $data_movements) = @_;
    return unless ref($child_ir) eq 'HASH' && ref($child_actor) eq 'HASH';

    my %declared_outputs = map {
        $_->{name} => $_
    } @{($child_actor->{interface} || {})->{outputs} || []};
    my %seen = map { $_->{name} => 1 } @{$child_ir->{ports} || []};

    for my $movement (@{$data_movements || []}) {
        next unless (_is_atl_actor_to_pin_handoff_kind($movement->{kind} // '')
                || _is_atl_actor_route_handoff_kind($movement->{kind} // ''))
            && ($movement->{source_instance} // '') eq $instance;

        my $port_name = $movement->{source_endpoint};
        my $width = $movement->{width} || 1;
        my $declared = defined($port_name) && !ref($port_name)
            ? $declared_outputs{$port_name}
            : undef;
        my $instance_role = _is_atl_actor_route_handoff_kind($movement->{kind} // '')
            ? 'source instance'
            : 'instance';
        my $port_label = (_is_atl_actor_route_handoff_kind($movement->{kind} // '')
                || _is_atl_actor_to_pin_handoff_kind($movement->{kind} // '')) && $width > 1
            ? 'child output port'
            : 'scalar child output port';
        # Numeric inspection must not change the caller's scalar flags.
        my $declared_width = ref($declared) eq 'HASH'
            ? $declared->{width}
            : undef;
        confess "$context data movement '$movement->{drive}' requires a $port_label '$port_name' on $instance_role '$instance'\n"
            unless ref($declared) eq 'HASH'
                && ($declared_width || 1) == $width
                && $width > 0;

        _push_port($child_ir->{ports}, \%seen, $port_name, 'output', $width)
            unless $seen{$port_name};
    }
}

sub _atl_generated_top_data_links($context, $instance, $trigger, $event_wait, $data_movements, $child_ports) {
    my @movements = @{$data_movements || []};
    return () unless @movements;

    for my $movement (@movements) {
        confess "$context data movement must belong to the same parent transaction as the trigger/event handoffs\n"
            unless ($movement->{transaction} // '') eq ($trigger->{owner_transaction} // '')
                && ($movement->{transaction} // '') eq ($event_wait->{transaction} // '');
        confess "$context data movement must be activated from a transaction body drive call in the current subset\n"
            unless ($movement->{context} // '') eq 'transaction_body'
                && defined($movement->{drive})
                && length($movement->{drive});
        confess "$context data movement must be a drive-call-cycle route without inserted storage\n"
            unless ($movement->{route_lifetime} // '') eq 'drive_call_cycle'
                && ($movement->{storage} // '') eq 'none';

        my $width = $movement->{width} || 1;
        confess "$context data movement '$movement->{drive}' must have a positive route width\n"
            unless $width > 0;
    }

    my @non_actor_movements = grep { !_is_atl_actor_route_handoff_kind($_->{kind} // '') } @movements;
    if (@non_actor_movements) {
        my $all_pin_to_actor = !grep { !_is_atl_pin_to_actor_handoff_kind($_->{kind} // '') } @movements;
        my $all_actor_to_pin = !grep { !_is_atl_actor_to_pin_handoff_kind($_->{kind} // '') } @movements;
        confess "$context cannot mix pin-to-resolved-child, resolved-child-to-pin, and actor-to-actor data movements in the current subset\n"
            unless $all_pin_to_actor || $all_actor_to_pin;
    }

    my $movement = $movements[0];
    my $width = $movement->{width} || 1;

    if (_is_atl_pin_to_actor_handoff_kind($movement->{kind} // '')) {
        my (@links, %top_source_ports, %child_sink_ports, %parent_sink_ports);
        for my $route (@movements) {
            my $route_width = $route->{width} || 1;
            my $port_label = $route_width > 1 ? 'child input port' : 'scalar child input port';
            confess "$context can only wire top-level input pin to resolved child input data movement when source is a top-level pin\n"
                unless ($route->{source} // '') eq 'top_level_pin'
                    && ($route->{sink} // '') eq 'external_handoff'
                    && ($route->{source_instance} // '') eq 'pins';
            confess "$context data movement must target resolved actor instance '$instance'\n"
                unless ($route->{sink_instance} // '') eq $instance;

            my $child_port = $route->{sink_endpoint};
            confess "$context data movement '$route->{drive}' requires a $port_label '$child_port' on instance '$instance'\n"
                unless defined($child_port)
                    && !ref($child_port)
                    && exists($child_ports->{$child_port})
                    && ($child_ports->{$child_port}{direction} || '') eq 'input'
                    && ($child_ports->{$child_port}{width} || 1) == $route_width;

            my $parent_port = $route->{sink_signal};
            my $top_port = $route->{source_signal};
            confess "$context data movement '$route->{drive}' requires generated parent sink handoff and top source pin signals\n"
                unless _non_empty_scalar($parent_port) && _non_empty_scalar($top_port);
            confess "$context data movement '$route->{drive}' reuses top-level input pin '$top_port' in the current one-to-one pin-ingress subset\n"
                if $top_source_ports{$top_port}++;
            confess "$context data movement '$route->{drive}' reuses child input port '$child_port' in the current one-to-one pin-ingress subset\n"
                if $child_sink_ports{$child_port}++;
            confess "$context data movement '$route->{drive}' reuses generated parent sink handoff '$parent_port'\n"
                if $parent_sink_ports{$parent_port}++;

            push @links, {
                kind             => 'scalar_pin_to_resolved_child_handoff',
                drive            => $route->{drive},
                top_source_port  => $top_port,
                parent_sink_port => $parent_port,
                child_sink_port  => $child_port,
                width            => $route_width,
            };
        }

        return @links;
    }

    if (_is_atl_actor_to_pin_handoff_kind($movement->{kind} // '')) {
        my (@links, %top_sink_ports, %child_source_ports, %parent_source_ports);
        for my $route (@movements) {
            my $route_width = $route->{width} || 1;
            confess "$context can only wire resolved child output to top-level output pin data movement when sink is a top-level pin\n"
                unless ($route->{source} // '') eq 'external_handoff'
                    && ($route->{sink} // '') eq 'top_level_pin'
                    && ($route->{sink_instance} // '') eq 'pins';
            confess "$context data movement must source from resolved actor instance '$instance'\n"
                unless ($route->{source_instance} // '') eq $instance;

            my $child_port = $route->{source_endpoint};
            my $port_label = $route_width > 1 ? 'child output port' : 'scalar child output port';
            confess "$context data movement '$route->{drive}' requires a $port_label '$child_port' on instance '$instance'\n"
                unless defined($child_port)
                    && !ref($child_port)
                    && exists($child_ports->{$child_port})
                    && ($child_ports->{$child_port}{direction} || '') eq 'output'
                    && ($child_ports->{$child_port}{width} || 1) == $route_width;

            my $parent_port = $route->{source_signal};
            my $top_port = $route->{sink_signal};
            confess "$context data movement '$route->{drive}' requires generated parent source handoff and top sink pin signals\n"
                unless _non_empty_scalar($parent_port) && _non_empty_scalar($top_port);
            confess "$context data movement '$route->{drive}' reuses child output port '$child_port' in the current one-to-one pin-egress subset\n"
                if $child_source_ports{$child_port}++;
            confess "$context data movement '$route->{drive}' reuses top-level output pin '$top_port' in the current one-to-one pin-egress subset\n"
                if $top_sink_ports{$top_port}++;
            confess "$context data movement '$route->{drive}' reuses generated parent source handoff '$parent_port'\n"
                if $parent_source_ports{$parent_port}++;

            push @links, {
                kind               => 'scalar_resolved_child_to_pin_handoff',
                drive              => $route->{drive},
                child_source_port  => $child_port,
                parent_source_port => $parent_port,
                top_sink_port      => $top_port,
                width              => $route_width,
            };
        }

        return @links;
    }

    if (_is_atl_actor_route_handoff_kind($movement->{kind} // '')) {
        my @links;
        for my $route (@movements) {
            my $route_width = $route->{width} || 1;
            confess "$context can only wire selected generated-child actor-to-actor data movement through parent handoffs\n"
                unless ($route->{source} // '') eq 'external_handoff'
                    && ($route->{sink} // '') eq 'external_handoff';

            if (($route->{source_instance} // '') eq $instance) {
                my $child_port = $route->{source_endpoint};
                my $port_label = $route_width > 1 ? 'child output port' : 'scalar child output port';
                confess "$context data movement '$route->{drive}' requires a $port_label '$child_port' on source instance '$instance'\n"
                    unless defined($child_port)
                        && !ref($child_port)
                        && exists($child_ports->{$child_port})
                        && ($child_ports->{$child_port}{direction} || '') eq 'output'
                        && ($child_ports->{$child_port}{width} || 1) == $route_width;

                my $parent_port = $route->{source_signal};
                confess "$context data movement '$route->{drive}' requires a generated parent source handoff signal\n"
                    unless _non_empty_scalar($parent_port);

                push @links, {
                    kind               => 'scalar_resolved_child_to_parent_handoff',
                    drive              => $route->{drive},
                    child_source_port  => $child_port,
                    parent_source_port => $parent_port,
                    width              => $route_width,
                };
                next;
            }

            if (($route->{sink_instance} // '') eq $instance) {
                my $child_port = $route->{sink_endpoint};
                my $port_label = $route_width > 1 ? 'child input port' : 'scalar child input port';
                confess "$context data movement '$route->{drive}' requires a $port_label '$child_port' on sink instance '$instance'\n"
                    unless defined($child_port)
                        && !ref($child_port)
                        && exists($child_ports->{$child_port})
                        && ($child_ports->{$child_port}{direction} || '') eq 'input'
                        && ($child_ports->{$child_port}{width} || 1) == $route_width;

                my $parent_port = $route->{sink_signal};
                confess "$context data movement '$route->{drive}' requires a generated parent sink handoff signal\n"
                    unless _non_empty_scalar($parent_port);

                push @links, {
                    kind             => 'scalar_parent_to_resolved_child_handoff',
                    drive            => $route->{drive},
                    parent_sink_port => $parent_port,
                    child_sink_port  => $child_port,
                    width            => $route_width,
                };
                next;
            }

            confess "$context data movement '$route->{drive}' does not involve child instance '$instance'\n";
        }

        return @links;
    }

    confess "$context can only wire top-level input pin to resolved child input, resolved child output to top-level output, or selected generated-child actor-to-actor data movement in the current subset\n";
}

sub _non_empty_scalar {
    my ($value) = @_;
    return defined($value) && !ref($value) && length($value);
}

sub _atl_transaction_scalar_on_signal {
    my ($tx, $context) = @_;
    my @on_clauses = grep {
        ref($_) eq 'ARRAY'
            && @$_
            && defined($_->[0])
            && !ref($_->[0])
            && $_->[0] eq 'on'
    } @{$tx->{clauses} || []};

    confess "$context target transaction '$tx->{name}' requires exactly one scalar '(on SIGNAL)' clause before ATL child wiring\n"
        unless @on_clauses == 1
            && defined($on_clauses[0][1])
            && !ref($on_clauses[0][1])
            && _is_hdl_identifier($on_clauses[0][1]);

    return $on_clauses[0][1];
}

sub _atl_reset_signature {
    my ($reset) = @_;
    return 'none' unless ref($reset) eq 'HASH'
        && defined($reset->{name})
        && length($reset->{name});

    return join("\0",
        $reset->{name},
        $reset->{kind} // '',
        $reset->{polarity} // '',
    );
}

# --- Parent IR (composition top, non-spawned transactions only) ---

sub _build_parent_ir($self, $actor, $generated_children, $pruned_transactions = undef) {
    my @ports  = @{$self->_build_ports($actor)};
    my %ctrs;
    my @states;
    my @dts;
    my @spawn_instances;
    my @temporal_contracts;
    my @immediate_assertions;
    my %point_bindings;   # ISF-TRIGGER-ANCHOR.5: name -> state for (point …)/(on … as …); for (at …)
    my @bank_accesses;
    my $transaction_port_bindings = _transaction_port_binding_metadata($actor);
    my %signal_widths = _declared_storage_signal_widths($actor);
    my %storage_roles = _declared_storage_roles($actor);
    # ISF-REGISTER-RESET-VALUES: signal -> hardware reset value (opt-in). Seed with the
    # actor-level storage var reset values; per-transaction local reset values merge in below.
    my %reset_values = (
        _declared_storage_reset_values($actor),
        _declared_interface_output_reset_values($actor),
    );
    my %output_defaults = _declared_interface_output_default_values($actor);
    my %signal_type_refs = (
        _actor_interface_signal_type_refs($actor),
        _declared_storage_signal_type_refs($actor),
    );
    my %local_drive_callers;
    my %spawn_drive_sources;
    my %transaction_by_name = map { $_->{name} => $_ } @{$actor->{transactions} || []};
    $pruned_transactions ||= {};
    my $ti = 0;

    for my $movement (@{(($actor->{actor_network} || {})->{data_movements}) || []}) {
        my $width = $movement->{width} || 1;
        $signal_widths{$movement->{source_signal}} = $width
            if defined($movement->{source_signal}) && !ref($movement->{source_signal});
        $signal_widths{$movement->{sink_signal}} = $width
            if defined($movement->{sink_signal}) && !ref($movement->{sink_signal});
    }

    for my $tx (@{$actor->{transactions}}) {
        next if $generated_children->{$tx->{name}};
        next if $pruned_transactions->{$tx->{name}};
        # The scheduler supplies private direct-formal names. Keep the raw IR
        # primitive strict: a remaining actor-pin alias is never executable.
        # Generated children have their own interfaces and do not enter here.
        my %formals = _transaction_port_map($tx);
        for my $direction (qw(inputs outputs)) {
            for my $port (@{$actor->{interface}{$direction} || []}) {
                confess "Transaction '$tx->{name}': formal '$port->{name}' collides with an actor interface port; separate direct formal physical identities are not supported yet\n"
                    if exists $formals{$port->{name}};
            }
        }
        my ($ss, $cs, $ds, $do, $sp, $contracts, $widths, $roles, $accesses, $resets, $asserts) =
            $self->_build_transaction($tx, $actor, $ti++, $generated_children, \%point_bindings);
        $reset_values{$_} = $resets->{$_} for keys %{$resets || {}};
        _merge_signal_widths(\%signal_widths, $widths, $tx->{name});
        _merge_signal_type_refs(\%signal_type_refs, { _transaction_port_signal_type_refs($tx) });
        _merge_storage_roles(\%storage_roles, $roles, $tx->{name});
        my %tx_drive_uses = _collect_named_drive_call_names($tx->{clauses}, $actor->{drives} || {});
        $local_drive_callers{$_}{$tx->{name}} = 1 for keys %tx_drive_uses;
        push @states, @$ss;
        for my $k (sort keys %$cs) {
            $ctrs{$k} = $cs->{$k};
        }
        push @dts, @$ds;
        push @temporal_contracts, @$contracts;
        push @immediate_assertions, @{$asserts || []};
        for my $d (@$do)  {
            next if ref($d) eq 'HASH' && $d->{generated_child};
            my $c = ref($d) eq 'HASH' ? $d->{child} : $d;
            $ctrs{"${c}_start"} = 1;
            $ctrs{"${c}_done"} = 1;
        }
        for my $s (@$sp)  {
            _register_generated_activation_instance(
                $s,
                $tx->{name},
                'transaction',
                $actor,
                \@ports,
                \%ctrs,
                \%storage_roles,
                \@dts,
                \%transaction_by_name,
                \%spawn_drive_sources,
            );
        }
        push @spawn_instances, map { _clone_isf_value($_) } @$sp;
        push @bank_accesses, @$accesses;
    }

    my @rule_trigger_dts;
    my @rule_trigger_instances = _rule_trigger_generated_refs($actor, $generated_children);
    for my $s (@rule_trigger_instances) {
        _register_generated_activation_instance(
            $s,
            $s->{owner},
            'rule',
            $actor,
            \@ports,
            \%ctrs,
            \%storage_roles,
            \@rule_trigger_dts,
            \%transaction_by_name,
            \%spawn_drive_sources,
        );
    }
    push @spawn_instances, map { _clone_isf_value($_) } @rule_trigger_instances;

    push @dts, $self->_build_rules($actor, \%ctrs, \@bank_accesses, $generated_children, \%storage_roles);
    push @dts, @rule_trigger_dts;
    $self->_wire_do_children(\@states, \%ctrs, $actor, $generated_children);
    $self->_wire_external_activations(\@states, \@ports, \%ctrs, $actor);
    my $local_drive_filter = keys(%$generated_children)
        ? { map { $_ => 1 } keys %local_drive_callers }
        : undef;
    $self->_build_drive_dts(
        $actor,
        \@dts,
        \%ctrs,
        $local_drive_filter,
        \%local_drive_callers,
        \%spawn_drive_sources,
        \%storage_roles,
    );

    # ISF-TRIGGER-ANCHOR.5: all transactions lowered — resolve (at NAME) leaves in checks to the
    # named point/activation's `state_active` (module-wide; an (at …) may reference a point in
    # another transaction). Unknown names fail closed.
    _resolve_at_references(\@immediate_assertions, \%point_bindings, \@states, \%ctrs);
    _apply_interface_output_defaults_to_entry_states(\@states, \%output_defaults);

    my $ir = {
        actor_name => $actor->{actor_name},
        clock      => $actor->{clock},
        reset      => $actor->{reset},
        reset_provenance => _clone_isf_value($actor->{reset_provenance}),
        interface_port_metadata => snapshot_interface_port_metadata($actor->{interface_port_metadata}),
        watchdog   => $actor->{watchdog},
        actor_phases => _actor_metadata_declarations($actor, 'phases'),
        actor_stages => _actor_metadata_declarations($actor, 'stages'),
        verification_observations => _verification_observation_declarations($actor),
        verification_bridge => _verification_bridge_declaration($actor),
        package_imports => _actor_package_imports($actor),
        package_roots => _actor_package_roots($actor),
        type_declarations => _actor_type_declarations($actor),
        enum_declarations => _actor_enum_declarations($actor),
        constants  => _actor_constant_declarations($actor),
        params     => _actor_param_declarations($actor),
        actor_network => _actor_network_for_ir($actor),
        ports      => \@ports,
        # +size carries width, not interface ownership. Keep authored ports
        # even when unused or undriven (including domain partitions).
        # Do not expose inferred storage or unrelated generated-child signals.
        explicit_interface_ports => [
            (map { { name => $_->{name}, direction => 'input', width => $_->{width} } }
                @{$actor->{interface}{inputs} || []}),
            (map { { name => $_->{name}, direction => 'output', width => $_->{width} } }
                @{$actor->{interface}{outputs} || []}),
        ],
        # Actor storage is owned by this parent/domain, regardless of whether
        # it has ordinary reads or writes. Generated children select ownership
        # separately; do not infer it from their copied width declarations.
        explicit_internal_signals => [
            (map { map { $_->{name} } @{$_->{signals} || []} }
                @{$actor->{storage} || []}),
            # A formal read with no assignment must not become an inferred
            # external input. Generated public formals are built separately.
            (sort grep { $storage_roles{$_} eq 'transaction_port' } keys %storage_roles),
        ],
        states     => \@states,
        dt_blocks  => \@dts,
        counters   => \%ctrs,
        declared_storage => _declared_storage_for_ir($actor),
        signal_widths => \%signal_widths,
        signal_type_refs => \%signal_type_refs,
        storage_roles => \%storage_roles,
        reset_values => \%reset_values,
        output_defaults => \%output_defaults,
        children   => {},
        spawn_instances => \@spawn_instances,
        temporal_contracts => \@temporal_contracts,
        immediate_assertions => \@immediate_assertions,
        bank_accesses => \@bank_accesses,
        transaction_port_bindings => $transaction_port_bindings,
    };
    $ir->{resource_arbitration} = _apply_rule_user_resource_arbitration($ir, $actor);
    $ir->{priority_resolution} = _merge_priority_resolution(
        _apply_rule_priority_resolution($ir, $actor),
        _apply_rule_transaction_priority_resolution($ir, $actor),
    );
    my %payload_names = map { $_ => 1 } grep { defined $_ } (
        keys %{$ir->{signal_widths}}, keys %{$ir->{counters}},
        (map { $_->{name} } @{$ir->{ports}}, @{$ir->{constants}}, @{$ir->{params}},
            @{$ir->{states}}, @{$ir->{dt_blocks}}),
        $ir->{clock}, (($ir->{reset} || {})->{name} // ()),
        (map { $_->{declaration}{name} } @{_formal_resource_signal_products($actor)}),
    );
    my $payload_products = _local_rule_payload_snapshot_products(
        $actor, \%payload_names, $ir->{states}, $ir->{dt_blocks});
    _apply_local_rule_payload_snapshots($ir, $payload_products);
    my $completion_products = retain_child_completions($ir);
    $ir->{child_completion_products} = $completion_products if $completion_products;
    FSM::Scheduler::ISF::RecordSamples->apply_to_module($ir, $actor,
        [grep {!$generated_children->{$_->{name}} && !$pruned_transactions->{$_->{name}}} @{$actor->{transactions}}]);
    _finalize_ir($ir);
    $ir->{logical_controllers} = FSM::Scheduler::ISF::LogicalControllers->inventory($ir, $actor);
    return $ir;
}

sub _actor_network_for_ir {
    my ($actor) = @_;
    my $network = $actor->{actor_network};
    return undef unless ref($network) eq 'HASH'
        && ref($network->{instances}) eq 'ARRAY'
        && @{$network->{instances}};

    my @event_waits = map {
        {
            transaction => $_->{transaction},
            context     => $_->{context},
            instance    => $_->{instance},
            event       => $_->{event},
            signal      => $_->{signal},
            source      => $_->{source},
        }
    } @{$network->{event_waits} || []};
    my @transaction_triggers = map {
        {
            owner_transaction  => $_->{owner_transaction},
            context            => $_->{context},
            instance           => $_->{instance},
            target_transaction => $_->{target_transaction},
            signal             => $_->{signal},
            sink               => $_->{sink},
        }
    } @{$network->{transaction_triggers} || []};
    my @data_movements = map {
        {
            kind            => $_->{kind},
            transaction     => $_->{transaction},
            context         => $_->{context},
            drive           => $_->{drive},
            source_instance => $_->{source_instance},
            source_endpoint => $_->{source_endpoint},
            source_signal   => $_->{source_signal},
            sink_instance   => $_->{sink_instance},
            sink_endpoint   => $_->{sink_endpoint},
            sink_signal     => $_->{sink_signal},
            width           => $_->{width},
            width_source    => $_->{width_source},
            route_lifetime  => $_->{route_lifetime},
            storage         => $_->{storage},
            source          => $_->{source},
            sink            => $_->{sink},
        }
    } @{$network->{data_movements} || []};
    my @groups = map {
        {
            name        => $_->{name},
            members     => [ @{$_->{members} || []} ],
            mode        => $_->{mode},
            declaration => $_->{declaration},
            source      => $_->{source},
            scheduling  => $_->{scheduling},
        }
    } @{$network->{groups} || []};
    my @group_schedules = map {
        {
            group               => $_->{group},
            owner_transaction   => $_->{owner_transaction},
            context             => $_->{context},
            members             => [ @{$_->{members} || []} ],
            target_transactions => [ @{$_->{target_transactions} || []} ],
            signals             => [ @{$_->{signals} || []} ],
            schedule            => $_->{schedule},
            dependency_policy   => $_->{dependency_policy},
            storage             => $_->{storage},
            source              => $_->{source},
            sink                => $_->{sink},
        }
    } @{$network->{group_schedules} || []};
    my @association_schedules = map {
        {
            association         => $_->{association},
            kind                => $_->{kind},
            lifetime            => $_->{lifetime},
            owner_transaction   => $_->{owner_transaction},
            context             => $_->{context},
            members             => [ @{$_->{members} || []} ],
            target_transactions => [ @{$_->{target_transactions} || []} ],
            signals             => [ @{$_->{signals} || []} ],
            schedule            => $_->{schedule},
            dependency_policy   => $_->{dependency_policy},
            storage             => $_->{storage},
            source              => $_->{source},
            sink                => $_->{sink},
        }
    } @{$network->{association_schedules} || []};

    return {
        kind      => $network->{kind} // 'static_declaration',
        instances => [
            map {
                my $instance = {
                    name        => $_->{name},
                    actor_type  => $_->{actor_type},
                    declaration => $_->{declaration},
                };
                for my $key (qw(type_resolution library alias export module scheduled_fsm)) {
                    $instance->{$key} = $_->{$key} if exists $_->{$key};
                }
                $instance;
            } @{$network->{instances}}
        ],
        groups => \@groups,
        generated_tops => [],
        association_schedules => \@association_schedules,
        group_schedules => \@group_schedules,
        event_waits => \@event_waits,
        transaction_triggers => \@transaction_triggers,
        data_movements => \@data_movements,
    };
}

sub _register_generated_activation_instance {
    my ($s, $owner, $owner_kind, $actor, $ports, $ctrs, $storage_roles, $dts, $transaction_by_name, $spawn_drive_sources) = @_;

    my $activation_kind = $s->{activation_kind} // 'spawn';
    my $context = $owner_kind eq 'rule'
        ? "Rule '$owner'"
        : "Transaction '$owner'";
    my $instance = $s->{instance};
    my $child = $s->{child};

    $ctrs->{"${instance}_start"} = 1;
    $ctrs->{"${instance}_done"} = 1;
    $storage_roles->{"${instance}_start"} = 'activation_start_handoff'
        if ref($storage_roles) eq 'HASH';
    $storage_roles->{"${instance}_done"} = 'activation_done_handoff'
        if ref($storage_roles) eq 'HASH';
    _ensure_port(
        $ports,
        "${instance}_start",
        'output',
        1,
        "$context: $activation_kind instance '$instance' generated start handoff",
    );
    _ensure_port(
        $ports,
        "${instance}_done",
        'input',
        1,
        "$context: $activation_kind instance '$instance' generated done handoff",
    );

    my $child_tx = $transaction_by_name->{$child};
    my @port_binding_assignments;
    my @port_binding_metadata;
    my %child_transaction_ports = _transaction_port_map($child_tx);

    if ($activation_kind eq 'trigger') {
        $ctrs->{"${instance}_done_seen"} = 1;
        $storage_roles->{"${instance}_done_seen"} = 'trigger_done_observe';
        push @port_binding_assignments, {
            lhs         => "${instance}_start",
            rhs         => $s->{trigger_source},
            op          => '=',
            source_kind => 'trigger_generated_start',
        };
        push @port_binding_assignments, {
            lhs         => "${instance}_done_seen",
            rhs         => "${instance}_done",
            op          => '=',
            source_kind => 'trigger_done_observe',
        };
    }

    for my $binding (@{$s->{port_bindings} || []}) {
        my $port = $child_transaction_ports{$binding->{port}};
        next unless $port;
        my $parent_port = "${instance}_$binding->{port}";
        if ($binding->{role} eq 'input') {
            _ensure_port(
                $ports,
                $parent_port,
                'output',
                $port->{width},
                "$context: $activation_kind instance '$instance' input binding '$binding->{port}' generated payload handoff",
            );
            my %assignment = (
                lhs         => $parent_port,
                rhs         => $activation_kind eq 'trigger'
                    ? _rule_trigger_payload_source_name($owner, $child, $port->{source_name}, $s->{trigger_ordinal})
                    : _activation_binding_actor_expr_text($binding),
                op          => '=',
                source_kind => "${activation_kind}_input_binding",
            );
            # Trigger payloads are already captured in a per-rule register.
            # Keep that snapshot visible after the start pulse, including waits.
            push @port_binding_assignments, \%assignment;
        } else {
            _ensure_port(
                $ports,
                $parent_port,
                'input',
                $port->{width},
                "$context: $activation_kind instance '$instance' output binding '$binding->{port}' generated payload handoff",
            );
            my %assignment = (
                lhs         => $binding->{actor_signal},
                rhs         => $parent_port,
                op          => '=',
                source_kind => "${activation_kind}_output_binding",
            );
            if ($activation_kind eq 'do') {
                $assignment{guard} = { port => "${instance}_done" };
            } elsif ($activation_kind eq 'trigger') {
                $assignment{guard} = { port => "${instance}_done_seen" };
            }
            push @port_binding_assignments, \%assignment;
        }
        $ctrs->{$parent_port} = $port->{width};
        $storage_roles->{$parent_port} = 'transaction_port_binding';
        push @port_binding_metadata, {
            role             => $binding->{role},
            child_port       => $binding->{port},
            parent_port      => $parent_port,
            actor_signal     => $binding->{actor_signal},
            actor_expr       => _clone_isf_value($binding->{actor_expr}),
            actor_expression => _activation_binding_actor_expr_text($binding),
            width            => $port->{width},
        };
    }

    if (@port_binding_assignments) {
        push @$dts, {
            name              => $activation_kind eq 'trigger'
                ? "${instance}_trigger_handoff"
                : "${instance}_port_bindings",
            kind              => $activation_kind eq 'trigger'
                ? 'trigger_generated_activation'
                : "${activation_kind}_port_binding",
            owner             => $owner,
            owner_kind        => $owner_kind,
            activation_kind   => $activation_kind,
            spawn_instance    => $instance,
            child_transaction => $child,
            assignments       => \@port_binding_assignments,
        };
    }
    if (@port_binding_metadata) {
        $s->{port_bindings} = \@port_binding_metadata;
    } else {
        delete $s->{port_bindings};
    }

    my %child_drive_uses = _collect_named_drive_call_names($child_tx->{clauses}, $actor->{drives} || {});
    my @drive_handoffs;
    for my $drive_name (sort keys %child_drive_uses) {
        my $prefix = "${instance}_${drive_name}";
        my @payloads;
        push @{$spawn_drive_sources->{$drive_name}}, {
            activation_kind   => $activation_kind,
            child_transaction => $child,
            drive             => $drive_name,
            instance          => $instance,
            owner             => $owner,
            owner_kind        => $owner_kind,
            prefix            => $prefix,
            source_kind       => 'spawn_drive_body',
        };
        _ensure_port(
            $ports,
            "${prefix}_start",
            'input',
            1,
            "$context: $activation_kind instance '$instance' named drive '$drive_name' generated request handoff",
        );
        $ctrs->{"${prefix}_start"} = 1;
        $storage_roles->{"${prefix}_start"} = 'drive_request';
        for my $param (@{($actor->{drives} || {})->{$drive_name}{params} || []}) {
            my $width = _drive_param_width($actor, $drive_name, $param);
            _ensure_port(
                $ports,
                "${prefix}_$param",
                'input',
                $width,
                "$context: $activation_kind instance '$instance' named drive '$drive_name' parameter '$param' generated payload handoff",
            );
            $ctrs->{"${prefix}_$param"} = $width;
            $storage_roles->{"${prefix}_$param"} = 'drive_payload';
            push @payloads, {
                parameter   => $param,
                child_port  => "${drive_name}_$param",
                parent_port => "${prefix}_$param",
                width       => $width,
            };
        }
        push @drive_handoffs, {
            drive   => $drive_name,
            request => {
                child_port  => "${drive_name}_start",
                parent_port => "${prefix}_start",
            },
            payloads => \@payloads,
        };
    }
    $s->{drive_handoffs} = \@drive_handoffs;

    return 1;
}

sub _collect_generated_child_transaction_refs($self, $actor) {
    return _generated_child_transaction_refs($actor);
}

sub _generated_child_transaction_refs {
    my ($actor) = @_;
    my %s;
    my $constant_values = _actor_constant_value_map($actor);
    for my $tx (@{$actor->{transactions}}) {
        for my $ref (_live_child_action_refs_from_transaction_clauses($tx->{clauses}, $tx->{name}, $actor)) {
            my $clause = $ref->{clause};
            my $label = $ref->{label};
            if ($clause->[0] eq 'spawn') {
                $s{$clause->[1]} = 1;
                next;
            }
            if (
                $clause->[0] eq 'do'
                && ($label eq 'transaction body' || $label eq 'repeat body'
                    || $label eq 'when body' || $label eq 'switch branch'
                    || $label eq 'while body' || $label eq 'until body')
                && @{_do_parameter_overrides($clause, $tx->{name}, $label, $constant_values, $actor)}
            ) {
                $s{$clause->[1]} = 1;
            }
        }
    }
    for my $rule (@{$actor->{rules} || []}) {
        my $rule_name = $rule->{name};
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY' && @$action;
            next unless defined($action->[0]) && !ref($action->[0]) && $action->[0] eq 'trigger';
            $s{$action->[1]} = 1
                if @{_trigger_parameter_overrides($action, $rule_name, 'rule action', $constant_values, $actor)};
        }
    }
    return %s;
}

sub _live_child_action_refs_from_transaction_clauses {
    my ($clauses, $tx_name, $actor) = @_;
    return _child_action_refs_from_transaction_clauses(
        $clauses,
        $tx_name,
        $actor,
        { skip_static_zero_repeats => 1 },
    );
}

sub _static_zero_child_action_refs_from_transaction_clauses {
    my ($clauses, $tx_name, $actor) = @_;
    my @refs;
    _push_static_zero_child_action_refs_recursive(\@refs, $clauses, $tx_name, $actor, 'transaction body');
    return @refs;
}

sub _push_static_zero_child_action_refs_recursive {
    my ($refs, $clauses, $tx_name, $actor, $label) = @_;
    return unless ref($clauses) eq 'ARRAY';

    for my $clause (@$clauses) {
        next unless ref($clause) eq 'ARRAY' && @$clause;
        next unless defined($clause->[0]) && !ref($clause->[0]);

        my $keyword = $clause->[0];
        if ($keyword eq 'repeat') {
            if (_repeat_clause_is_static_zero_for_refs($clause, $actor, $tx_name)) {
                _push_repeat_body_child_action_refs(
                    $refs,
                    $clause,
                    $label,
                    undef,
                    { static_zero_repeat => 1 },
                );
            }
            next;
        }

        if ($keyword eq 'when') {
            _push_static_zero_child_action_refs_recursive(
                $refs,
                [@{$clause}[2 .. $#$clause]],
                $tx_name,
                $actor,
                'when body',
            );
            next;
        }

        if ($keyword eq 'switch') {
            for my $branch (@{$clause}[2 .. $#$clause]) {
                next unless ref($branch) eq 'ARRAY' && @$branch >= 2;
                _push_static_zero_child_action_refs_recursive(
                    $refs,
                    [@{$branch}[1 .. $#$branch]],
                    $tx_name,
                    $actor,
                    'switch branch',
                );
            }
            next;
        }

        if ($keyword eq 'while' || $keyword eq 'until') {
            _push_static_zero_child_action_refs_recursive(
                $refs,
                [@{$clause}[2 .. $#$clause]],
                $tx_name,
                $actor,
                "$keyword body",
            );
        }
    }
}

sub _child_action_refs_from_transaction_clauses {
    my ($clauses, $tx_name, $actor, $options) = @_;
    $options ||= {};
    my @refs;
    my $top_level_do_ordinal = 0;
    my $repeat_do_ordinal = 0;

    for my $clause (@{$clauses || []}) {
        next unless ref($clause) eq 'ARRAY' && @$clause;
        next unless defined($clause->[0]) && !ref($clause->[0]);

        my $keyword = $clause->[0];
        if ($keyword eq 'do' || $keyword eq 'spawn') {
            my %ref = (
                clause  => $clause,
                keyword => $keyword,
                label   => 'transaction body',
            );
            $ref{do_ordinal} = $top_level_do_ordinal++ if $keyword eq 'do';
            push @refs, \%ref;
            next;
        }

        if ($keyword eq 'repeat') {
            my $static_zero_repeat = _repeat_clause_is_static_zero_for_refs($clause, $actor, $tx_name);
            next if $options->{skip_static_zero_repeats} && $static_zero_repeat;
            _push_repeat_body_child_action_refs(
                \@refs,
                $clause,
                'transaction body',
                \$repeat_do_ordinal,
                { static_zero_repeat => $static_zero_repeat ? 1 : 0 },
            );
            next;
        }

        if ($keyword eq 'when') {
            # Recurse through nested `when` clauses so repeats reached through
            # deeper branch nesting (when+ -> repeat) are discovered, in the same
            # source order the lowering assigns repeat-do ordinals.
            _push_nested_branch_repeat_refs(
                \@refs,
                [@{$clause}[2 .. $#$clause]],
                'when body',
                \$repeat_do_ordinal,
                $options,
                $actor,
                $tx_name,
            );
        }

        if ($keyword eq 'switch') {
            for my $branch (@{$clause}[2 .. $#$clause]) {
                next unless ref($branch) eq 'ARRAY' && @$branch >= 2;
                _push_nested_branch_repeat_refs(
                    \@refs,
                    [@{$branch}[1 .. $#$branch]],
                    'switch branch',
                    \$repeat_do_ordinal,
                    $options,
                    $actor,
                    $tx_name,
                );
            }
        }

        if ($keyword eq 'while' || $keyword eq 'until') {
            # A repeat directly inside a single (while ...)/(until ...) body may
            # activate a generated child via a same-domain generated (do ...);
            # discover those so the child is registered, validated, and built.
            for my $body_clause (@{$clause}[2 .. $#$clause]) {
                next unless ref($body_clause) eq 'ARRAY' && @$body_clause;
                next unless defined($body_clause->[0]) && !ref($body_clause->[0]);
                if ($body_clause->[0] eq 'do' || $body_clause->[0] eq 'spawn') {
                    # A direct `(do child)`/`(spawn child)` in a while/until body
                    # (ISF-CONDITIONAL-CHILD-ACTIVATION) — surfaced for sibling
                    # gating + validation; the clause-context allow-list governs.
                    push @refs, {
                        clause  => $body_clause,
                        keyword => $body_clause->[0],
                        label   => "$keyword body",
                    };
                    next;
                }
                if ($keyword eq 'while' && $body_clause->[0] eq 'when') {
                    _push_nested_branch_repeat_refs(
                        \@refs,
                        [@{$body_clause}[2 .. $#$body_clause]],
                        'when body',
                        \$repeat_do_ordinal,
                        $options,
                        $actor,
                        $tx_name,
                    );
                    next;
                }
                next unless $body_clause->[0] eq 'repeat';
                my $static_zero_repeat = _repeat_clause_is_static_zero_for_refs($body_clause, $actor, $tx_name);
                next if $options->{skip_static_zero_repeats} && $static_zero_repeat;
                _push_repeat_body_child_action_refs(
                    \@refs,
                    $body_clause,
                    "$keyword body",
                    \$repeat_do_ordinal,
                    { static_zero_repeat => $static_zero_repeat ? 1 : 0 },
                );
            }
        }
    }

    return @refs;
}

sub _repeat_clause_is_static_zero_for_refs {
    my ($clause, $actor, $tx_name) = @_;
    return 0 unless ref($clause) eq 'ARRAY'
        && ref($actor) eq 'HASH'
        && defined($tx_name)
        && @$clause >= 2;

    return _is_static_zero_repeat_count($clause->[1], $actor, $tx_name) ? 1 : 0;
}

sub _push_repeat_body_child_action_refs {
    my ($refs, $repeat_clause, $repeat_parent_label, $repeat_do_ordinal_ref, $attrs) = @_;
    $attrs ||= {};

    for my $body_clause (@{$repeat_clause}[2 .. $#$repeat_clause]) {
        next unless ref($body_clause) eq 'ARRAY' && @$body_clause;
        next unless defined($body_clause->[0]) && !ref($body_clause->[0]);
        next unless $body_clause->[0] eq 'do' || $body_clause->[0] eq 'spawn';
        my %ref = (
            clause              => $body_clause,
            keyword             => $body_clause->[0],
            label               => 'repeat body',
            repeat_parent_label => $repeat_parent_label,
            %$attrs,
        );
        $ref{repeat_do_ordinal} = $$repeat_do_ordinal_ref++
            if $body_clause->[0] eq 'do' && ref($repeat_do_ordinal_ref);
        push @$refs, \%ref;
    }
}

# Walk a branch body in source order, collecting repeat-body child-action refs
# from repeats reached through nested `when` clauses (when+ -> repeat). This
# mirrors the lowering recursion (`_expand_when`/`_expand_switch` recurse into
# nested `when` only; a nested `switch` is a validator-rejected clause), so the
# `$repeat_do_ordinal_ref` assignment order matches `_ir_repeat`'s instance
# naming. Used for the when/switch branches so deeper-nested generated children
# are discovered, not just direct repeat children.
sub _push_nested_branch_repeat_refs {
    my ($refs, $body_clauses, $label, $repeat_do_ordinal_ref, $options, $actor, $tx_name) = @_;
    $options ||= {};

    for my $bc (@{$body_clauses || []}) {
        next unless ref($bc) eq 'ARRAY' && @$bc;
        next unless defined($bc->[0]) && !ref($bc->[0]);
        my $kw = $bc->[0];
        if ($kw eq 'do' || $kw eq 'spawn') {
            # A direct `(do child)`/`(spawn child)` in a branch body (ISF-
            # CONDITIONAL-CHILD-ACTIVATION). Surfaced so `_wire_do_children` gates
            # the local sibling child and `_validate_child_transaction_refs` sees
            # it. The clause-context allow-list governs which contexts actually
            # lower (e.g. only `when` accepts `do` so far).
            push @$refs, {
                clause  => $bc,
                keyword => $kw,
                label   => $label,
            };
            next;
        }
        if ($kw eq 'repeat') {
            my $static_zero_repeat = _repeat_clause_is_static_zero_for_refs($bc, $actor, $tx_name);
            next if $options->{skip_static_zero_repeats} && $static_zero_repeat;
            _push_repeat_body_child_action_refs(
                $refs,
                $bc,
                $label,
                $repeat_do_ordinal_ref,
                { static_zero_repeat => $static_zero_repeat ? 1 : 0 },
            );
        }
        elsif ($kw eq 'when') {
            _push_nested_branch_repeat_refs(
                $refs,
                [@{$bc}[2 .. $#$bc]],
                'when body',
                $repeat_do_ordinal_ref,
                $options,
                $actor,
                $tx_name,
            );
        }
    }
}

sub _validate_static_zero_repeat_child_activation_prune_surface($self, $actor) {
    my %transactions = map { $_->{name} => 1 } @{$actor->{transactions} || []};

    for my $tx (@{$actor->{transactions} || []}) {
        my $tx_name = $tx->{name};
        for my $ref (_static_zero_child_action_refs_from_transaction_clauses($tx->{clauses}, $tx_name, $actor)) {
            my $clause = $ref->{clause};
            my $keyword = $ref->{keyword};
            my $target = $clause->[1];
            my $label = $ref->{label};

            _validate_child_action_clause($clause, $tx_name, $label);
            confess "Transaction '$tx_name': $keyword target must be a scalar transaction name\n"
                unless defined($target) && !ref($target) && length($target);
            confess "Transaction '$tx_name': $keyword target '$target' is not a declared transaction\n"
                unless $transactions{$target};
        }
    }

    return 1;
}

sub _pruned_static_zero_child_transaction_targets {
    my ($actor, $generated_children) = @_;
    $generated_children ||= {};

    my %transaction_by_name = map { $_->{name} => $_ } @{$actor->{transactions} || []};
    my %live_targets;
    for my $tx (@{$actor->{transactions} || []}) {
        for my $ref (_live_child_action_refs_from_transaction_clauses($tx->{clauses}, $tx->{name}, $actor)) {
            my $target = $ref->{clause}[1];
            $live_targets{$target} = 1
                if defined($target) && !ref($target) && length($target);
        }
    }
    for my $rule (@{$actor->{rules} || []}) {
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY'
                && @$action
                && defined($action->[0])
                && !ref($action->[0])
                && $action->[0] eq 'trigger';
            my $target = $action->[1];
            $live_targets{$target} = 1
                if defined($target) && !ref($target) && length($target);
        }
    }

    my %pruned;
    for my $tx (@{$actor->{transactions} || []}) {
        for my $ref (_static_zero_child_action_refs_from_transaction_clauses($tx->{clauses}, $tx->{name}, $actor)) {
            my $target = $ref->{clause}[1];
            next unless defined($target) && !ref($target) && exists($transaction_by_name{$target});
            next if $generated_children->{$target};
            next if $live_targets{$target};
            next if _transaction_has_external_entry_guard($transaction_by_name{$target}, $actor);
            $pruned{$target} = 1;
        }
    }

    return %pruned;
}

sub _transaction_has_external_entry_guard {
    my ($tx, $actor) = @_;
    return 0 unless ref($tx) eq 'HASH' && ref($actor) eq 'HASH';

    my %inputs = map { $_->{name} => 1 } @{$actor->{interface}{inputs} || []};
    for my $clause (@{$tx->{clauses} || []}) {
        next unless ref($clause) eq 'ARRAY'
            && @$clause >= 2
            && defined($clause->[0])
            && !ref($clause->[0])
            && $clause->[0] eq 'on';
        my $guard = $clause->[1];
        return 1 if defined($guard) && !ref($guard) && $inputs{$guard};
    }

    return 0;
}

sub _validate_activation_domain_names($self, $actor) {
    my %declared_domains = _actor_declared_domain_names($actor);

    for my $tx (@{$actor->{transactions} || []}) {
        for my $child_ref (_live_child_action_refs_from_transaction_clauses($tx->{clauses}, $tx->{name}, $actor)) {
            my $domain = _activation_domain_from_clause(
                $child_ref->{clause},
                $tx->{name},
                $child_ref->{label},
            );
            next unless defined $domain;
            next if $declared_domains{$domain};

            my $keyword = $child_ref->{keyword};
            my $target = $child_ref->{clause}[1];
            confess "Transaction '$tx->{name}': $keyword target '$target' uses unknown clock domain '$domain'\n";
        }
    }

    return 1;
}

sub _actor_declared_domain_names {
    my ($actor) = @_;

    if (_actor_has_clock_domains($actor)) {
        return map { $_->{name} => 1 } @{$actor->{clock_domains}{domains} || []};
    }

    my %domains = (default => 1);
    for my $entry (
        @{$actor->{interface}{inputs} || []},
        @{$actor->{interface}{outputs} || []},
        @{$actor->{storage} || []},
        @{$actor->{transactions} || []},
        @{$actor->{rules} || []},
        @{$actor->{library_uses} || []},
    ) {
        next unless ref($entry) eq 'HASH';
        my $domain = $entry->{domain};
        $domains{$domain} = 1
            if defined($domain) && !ref($domain) && length($domain);
    }

    return %domains;
}

sub _rule_trigger_generated_refs {
    my ($actor, $generated_children) = @_;
    my @refs;
    my %ordinals;
    my $constant_values = _actor_constant_value_map($actor);

    for my $rule (@{$actor->{rules} || []}) {
        my $rule_name = $rule->{name};
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY' && @$action;
            next unless defined($action->[0]) && !ref($action->[0]) && $action->[0] eq 'trigger';
            my $target = $action->[1];
            next unless defined($target) && !ref($target) && $generated_children->{$target};

            my $key = "$rule_name\0$target";
            my $ordinal = $ordinals{$key}++;
            my $instance = _generated_rule_trigger_instance_name($rule_name, $target, $ordinal);
            push @refs, {
                child               => $target,
                instance            => $instance,
                activation_kind     => 'trigger',
                owner               => $rule_name,
                owner_kind          => 'rule',
                trigger_ordinal     => $ordinal,
                trigger_source      => _rule_trigger_source_name($rule_name, $target, $ordinal),
                parameter_overrides => _trigger_parameter_overrides($action, $rule_name, 'rule action', $constant_values, $actor),
                port_bindings       => _activation_bindings_from_clause($action, $rule_name, 'rule trigger'),
            };
        }
    }

    return @refs;
}

# Determine how a `(do <child>)` is used within a transaction's clause tree, for
# accurate activation-crossing diagnostics. Returns a hash:
#   top_level    => 1 if a `(do child)` appears as a direct transaction clause;
#   nested_label => the nesting context ('when body' / 'switch branch' /
#                   'repeat body' / 'while body' / 'until body') of the
#                   innermost-found nested `(do child)`, or undef.
sub _activation_do_use_context {
    my ($clauses, $child) = @_;
    # top_level              : a `(do child)` directly in the transaction body.
    # top_level_repeat       : a `(do child)` directly inside a TOP-LEVEL `repeat`
    #                          body (ISF-NESTED-CROSS-DOMAIN-ACTIVATION.3).
    # top_level_branch_body  : a `(do child)` directly inside a TOP-LEVEL `when` /
    #                          `switch` / `while` / `until` body (`.4`; relies on the
    #                          same-domain branch-body `(do)` feature shipped by
    #                          ISF-CONDITIONAL-CHILD-ACTIVATION). Deeper nestings of
    #                          either kind stay deferred.
    # top_level_branch_repeat: a `(do child)` directly inside a `repeat` nested
    #                          directly in a TOP-LEVEL `when` body or `switch`
    #                          branch (ISF-NESTED-CROSS-DOMAIN-ACTIVATION.6).
    # top_level_branch_when  : a `(do child)` directly inside a `when` body nested
    #                          under a TOP-LEVEL `when` body or `switch` branch,
    #                          with longer `when` chains allowed (`.7`).
    # top_level_branch_when_repeat:
    #                          a `(do child)` directly inside a `repeat` nested
    #                          under that supported branch-contained `when` chain
    #                          (`.9`).
    # nested_label           : the innermost container of a deferred nested `(do)`.
    my %out = (
        top_level                    => 0,
        top_level_repeat             => 0,
        top_level_branch_body        => 0,
        top_level_branch_repeat      => 0,
        top_level_branch_when        => 0,
        top_level_branch_when_repeat => 0,
        nested_label                 => undef,
    );
    _scan_activation_do_use($clauses, $child, undef, \%out, 0, 0, 0, 0);
    return %out;
}

sub _scan_activation_do_use {
    my (
        $clauses,
        $child,
        $container_label,
        $out,
        $top_level_container,
        $branch_contained_repeat,
        $branch_contained_when,
        $branch_contained_when_repeat,
    ) = @_;
    return unless ref($clauses) eq 'ARRAY';
    for my $clause (@$clauses) {
        next unless ref($clause) eq 'ARRAY' && @$clause;
        my $kw = $clause->[0];
        next unless defined($kw) && !ref($kw);
        if ($kw eq 'do' && defined($clause->[1]) && !ref($clause->[1]) && $clause->[1] eq $child) {
            if (defined $container_label) {
                $out->{nested_label} //= $container_label;
                # A `(do child)` directly inside a container that is itself a direct
                # transaction-body clause is a supported nested context: a top-level
                # `repeat` body (`.3`) or a top-level branch body (`.4`). Anything
                # deeper loses top-level status and stays deferred.
                if ($top_level_container) {
                    if ($container_label eq 'repeat body') { $out->{top_level_repeat} = 1; }
                    else                                   { $out->{top_level_branch_body} = 1; }
                }
                elsif ($branch_contained_repeat && $container_label eq 'repeat body') {
                    $out->{top_level_branch_repeat} = 1;
                }
                elsif ($branch_contained_when && $container_label eq 'when body') {
                    $out->{top_level_branch_when} = 1;
                }
                elsif ($branch_contained_when_repeat && $container_label eq 'repeat body') {
                    $out->{top_level_branch_when_repeat} = 1;
                }
            }
            else {
                $out->{top_level} = 1;
            }
            next;
        }
        if ($kw eq 'when' || $kw eq 'repeat' || $kw eq 'while' || $kw eq 'until') {
            # The container is a direct transaction-body clause iff we are still at
            # the top level (container_label undef); its direct `(do child)` body
            # clauses are then top-level-repeat / top-level-branch.
            my $child_top_level = (!defined($container_label)) ? 1 : 0;
            my $child_branch_contained_repeat = (
                $kw eq 'repeat'
                    && $top_level_container
                    && defined($container_label)
                    && ($container_label eq 'when body' || $container_label eq 'switch branch')
            ) ? 1 : 0;
            my $child_branch_contained_when = (
                $kw eq 'when'
                    && (
                        (
                            $top_level_container
                            && defined($container_label)
                            && ($container_label eq 'when body' || $container_label eq 'switch branch')
                        )
                        || $branch_contained_when
                    )
            ) ? 1 : 0;
            my $child_branch_contained_when_repeat = (
                $kw eq 'repeat' && $branch_contained_when
            ) ? 1 : 0;
            _scan_activation_do_use(
                [@{$clause}[2 .. $#$clause]],
                $child,
                "$kw body",
                $out,
                $child_top_level,
                $child_branch_contained_repeat,
                $child_branch_contained_when,
                $child_branch_contained_when_repeat,
            );
        }
        elsif ($kw eq 'switch') {
            my $child_top_level = (!defined($container_label)) ? 1 : 0;
            for my $branch (@{$clause}[2 .. $#$clause]) {
                next unless ref($branch) eq 'ARRAY';
                _scan_activation_do_use(
                    [@{$branch}[1 .. $#$branch]],
                    $child,
                    'switch branch',
                    $out,
                    $child_top_level,
                    0,
                    0,
                    0,
                );
            }
        }
    }
    return;
}

sub _build_domain_partition($self, $actor, $pruned_transactions = undef) {
    return undef unless _actor_has_clock_domains($actor);
    $pruned_transactions ||= {};

    my $clock_domains = $actor->{clock_domains};
    my $default_domain = $clock_domains->{default};
    my @domain_order = map { $_->{name} } @{$clock_domains->{domains} || []};
    my %groups;

    for my $domain (@{$clock_domains->{domains} || []}) {
        my $name = $domain->{name};
        $groups{$name} = {
            name          => $name,
            clock         => $domain->{clock},
            reset         => _clone_isf_value($domain->{reset}),
            scheduled_fsm => "$actor->{actor_name}__domain_${name}.fsm",
            ports         => { inputs => [], outputs => [] },
            storage       => [],
            transactions  => [],
            rules         => [],
            child_instances => [],
            library_uses  => [],
            crossings     => [],
            drive_names   => [],
        };
    }

    my %signal_domains = _actor_domain_signal_map($actor, $default_domain);
    my %transaction_domains = map {
        $_->{name} => _domain_for_entry($_, $default_domain)
    } @{$actor->{transactions} || []};
    my %constants = map { $_->{name} => 1 } @{$actor->{constants} || []};
    my %drive_use_domains;

    for my $input (@{$actor->{interface}{inputs} || []}) {
        push @{$groups{_domain_for_entry($input, $default_domain)}{ports}{inputs}}, $input->{name};
    }
    for my $output (@{$actor->{interface}{outputs} || []}) {
        push @{$groups{_domain_for_entry($output, $default_domain)}{ports}{outputs}}, $output->{name};
    }
    for my $storage (@{$actor->{storage} || []}) {
        push @{$groups{_domain_for_entry($storage, $default_domain)}{storage}}, $storage->{name};
    }
    for my $tx (grep { !$pruned_transactions->{$_->{name}} } @{$actor->{transactions} || []}) {
        push @{$groups{_domain_for_entry($tx, $default_domain)}{transactions}}, $tx->{name};
    }
    for my $rule (@{$actor->{rules} || []}) {
        push @{$groups{_domain_for_entry($rule, $default_domain)}{rules}}, $rule->{name};
    }
    for my $use (@{$actor->{library_uses} || []}) {
        push @{$groups{_domain_for_entry($use, $default_domain)}{library_uses}}, $use->{instance};
    }
    my @crossing_summaries;
    for my $crossing (@{$actor->{crossings} || []}) {
        next unless ($crossing->{kind} // '') eq 'event';
        push @crossing_summaries, {
            name               => $crossing->{name},
            kind               => 'event',
            source_domain      => $crossing->{from}{domain},
            source_signal      => $crossing->{from}{signal},
            destination_domain => $crossing->{to}{domain},
            destination_signal => $crossing->{to}{signal},
            ready_signal       => $crossing->{ready}{signal},
            instance           => "$crossing->{name}_cdc",
            module             => "$actor->{actor_name}__cdc_event_$crossing->{name}",
            outstanding_policy => 'single_outstanding_acknowledged',
            payload            => 'none',
        };
        push @{$groups{$crossing->{from}{domain}}{crossings}}, {
            event  => $crossing->{name},
            role   => 'source',
            signal => $crossing->{from}{signal},
            ready  => $crossing->{ready}{signal},
        } if exists $groups{$crossing->{from}{domain}};
        push @{$groups{$crossing->{to}{domain}}{crossings}}, {
            event  => $crossing->{name},
            role   => 'destination',
            signal => $crossing->{to}{signal},
        } if exists $groups{$crossing->{to}{domain}};
    }
    # Activation summaries carry the same validated routing identities used by
    # the generated top and schedule report, distinct from event endpoints.
    #
    # An activation crossing must own a REAL cross-domain activation: the child
    # must live in the destination domain, and some transaction in the source
    # domain must perform a top-level `(do child)`. A declared-but-unused crossing
    # (or one whose child is misplaced) would emit dead/unsynchronized CDC logic,
    # so it fails closed here.
    for my $crossing (@{$actor->{crossings} || []}) {
        next unless ($crossing->{kind} // '') eq 'activation';
        my $child = $crossing->{child};
        my $src   = $crossing->{from}{domain};
        my $dst   = $crossing->{to}{domain};
        my $child_domain = $transaction_domains{$child};
        confess "ISF activation crossing for child '$child' declares destination domain '$dst', but transaction '$child' is in domain '" . ($child_domain // '?') . "'\n"
            if defined($child_domain) && $child_domain ne $dst;

        my $covered = 0;
        my $nested_label;
        for my $tx (@{$actor->{transactions} || []}) {
            next unless _domain_for_entry($tx, $default_domain) eq $src;
            my %use = _activation_do_use_context($tx->{clauses}, $child);
            # A top-level `(do child)`, a `(do child)` directly inside a top-level
            # `repeat` body (`.3`), OR a `(do child)` directly inside a top-level
            # branch body (`.4`: when/switch/while/until), a repeat nested directly
            # inside a top-level when/switch branch (`.6`), a when body nested
            # under a top-level when/switch branch (`.7`), OR a repeat under that
            # supported nested when chain (`.9`) is a supported, covered cross-domain
            # activation. Other deeper nestings stay deferred.
            $covered = 1
                if $use{top_level}
                || $use{top_level_repeat}
                || $use{top_level_branch_body}
                || $use{top_level_branch_repeat}
                || $use{top_level_branch_when}
                || $use{top_level_branch_when_repeat};
            $nested_label //= $use{nested_label};
        }
        # Accurate fail-closed diagnostics: distinguish a top-level covered
        # activation (proceeds) from a NESTED use (deferred) from a genuinely
        # unused crossing.
        if (!$covered && defined($nested_label)) {
            confess "ISF activation crossing for child '$child' (domain '$src' -> '$dst') is used by a nested '(do $child)' (inside a $nested_label), but cross-domain activation is currently supported only for a top-level '(do $child)', a '(do $child)' directly inside a top-level '(repeat ...)' body, a top-level branch body ('when'/'switch'/'while'/'until'), a '(do $child)' directly inside a repeat nested in a top-level 'when' body or 'switch' branch, a '(do $child)' directly inside a nested 'when' chain under a top-level 'when' body or 'switch' branch, or a '(do $child)' directly inside a repeat under that nested 'when' chain; deeper nested cross-domain activation remains deferred\n";
        }
        confess "ISF activation crossing for child '$child' (domain '$src' -> '$dst') is declared but no transaction in domain '$src' performs a top-level '(do $child)'; an activation crossing must own a real cross-domain activation\n"
            unless $covered;

        my $start_signal = "${child}_start";
        my $done_signal  = "${child}_done";
        push @crossing_summaries, {
            name               => $child,
            kind               => 'activation',
            child              => $child,
            source_domain      => $src,
            destination_domain => $dst,
            start_signal       => $start_signal,
            done_signal        => $done_signal,
            start_instance     => "${child}_activation_start_cdc",
            start_module       => "$actor->{actor_name}__cdc_activation_${child}_start",
            done_instance      => "${child}_activation_done_cdc",
            done_module        => "$actor->{actor_name}__cdc_activation_${child}_done",
            outstanding_policy => 'single_outstanding_acknowledged',
            payload            => 'none',
        };
        push @{$groups{$src}{crossings}}, {
            activation => $child,
            role       => 'source',
            start      => $start_signal,
            done       => $done_signal,
        } if exists $groups{$src};
        push @{$groups{$dst}{crossings}}, {
            activation => $child,
            role       => 'destination',
            start      => $start_signal,
            done       => $done_signal,
        } if exists $groups{$dst};
    }

    my %generated_children = _generated_child_transaction_refs($actor);
    my %do_ordinals;
    for my $tx (grep { !$pruned_transactions->{$_->{name}} } @{$actor->{transactions} || []}) {
        my $owner_domain = _domain_for_entry($tx, $default_domain);
        for my $child_ref (_live_child_action_refs_from_transaction_clauses($tx->{clauses}, $tx->{name}, $actor)) {
            my $clause = $child_ref->{clause};
            my $keyword = $child_ref->{keyword};
            next unless $keyword eq 'spawn' || $keyword eq 'do';

            my $target = $clause->[1];
            my $activation_domain = _activation_domain_from_clause($clause, $tx->{name}, $child_ref->{label}) // $owner_domain;
            confess "Transaction '$tx->{name}': $keyword target '$target' uses unknown clock domain '$activation_domain'\n"
                unless exists $groups{$activation_domain};
            my $top_level_do = $keyword eq 'do' && ($child_ref->{label} // '') eq 'transaction body';
            my $repeat_body_generated_do = $keyword eq 'do'
                && ($child_ref->{label} // '') eq 'repeat body'
                && _repeat_body_do_is_generated_activation($clause, $target, \%generated_children);
            my $include_instance = $keyword eq 'spawn'
                || ($top_level_do && $generated_children{$target})
                || $repeat_body_generated_do;
            if ($include_instance) {
                my $ordinal = $do_ordinals{$tx->{name}} // 0;
                $do_ordinals{$tx->{name}} = $ordinal + 1 if $top_level_do;
                my $instance = $keyword eq 'spawn'
                    ? $clause->[3]
                    : $repeat_body_generated_do
                        ? _generated_repeat_do_instance_name($tx->{name}, $target, $child_ref->{repeat_do_ordinal} // 0)
                        : _generated_do_instance_name($tx->{name}, $target, $ordinal);
                push @{$groups{$activation_domain}{child_instances}}, {
                    kind   => $keyword,
                    owner  => $tx->{name},
                    child  => $target,
                    instance => $instance,
                };
            } elsif ($top_level_do) {
                $do_ordinals{$tx->{name}}++;
            }
        }
    }
    for my $ref (_rule_trigger_generated_refs($actor, \%generated_children)) {
        my ($rule) = grep { $_->{name} eq $ref->{owner} } @{$actor->{rules} || []};
        my $activation_domain = _domain_for_entry($rule, $default_domain);
        push @{$groups{$activation_domain}{child_instances}}, {
            kind     => 'trigger',
            owner    => $ref->{owner},
            child    => $ref->{child},
            instance => $ref->{instance},
        };
    }

    $self->_validate_transaction_domain_refs(
        $actor,
        \%signal_domains,
        \%transaction_domains,
        \%constants,
        \%drive_use_domains,
        $default_domain,
        $pruned_transactions,
    );
    $self->_validate_rule_domain_refs(
        $actor,
        \%signal_domains,
        \%transaction_domains,
        \%constants,
        $default_domain,
    );
    $self->_validate_library_use_domain_refs($actor, \%signal_domains, $default_domain);
    _validate_drive_reuse_domains(\%drive_use_domains);
    _validate_drive_body_domain_refs($actor, \%drive_use_domains, \%signal_domains, \%constants);
    for my $name (sort keys %drive_use_domains) {
        push @{$groups{$_}{drive_names}}, $name
            for sort keys %{$drive_use_domains{$name}};
    }

    my @domains = map { $groups{$_} } @domain_order;
    _allocate_domain_artifact_names($actor, \@domains, \@crossing_summaries)
        if @domains > 1;

    return {
        kind => @domain_order > 1 ? 'multi_domain' : 'single_domain',
        default_domain => $default_domain,
        domains => \@domains,
        top_fsm => "$actor->{actor_name}_top.fsm",
        crossings => \@crossing_summaries,
    };
}

sub _allocate_domain_artifact_names($actor, $domains, $crossings) {
    # Child labels share a namespace with top ports. Module names have a
    # separate namespace, also case-folded because their filenames must survive
    # a case-insensitive filesystem. Keep logical domain/signal names intact.
    my %instances = map { $_->{name} => 1 } (
        @{$actor->{interface}{inputs} || []},
        @{$actor->{interface}{outputs} || []},
    );
    for my $domain (@$domains) {
        $instances{$domain->{clock}} = 1;
        $instances{$domain->{reset}{name}} = 1
            if ref($domain->{reset}) eq 'HASH';
    }
    my %modules = ("$actor->{actor_name}_top" => 1);
    my $allocate = sub ($desired, $role, $reserved) {
        return FSM::Support::HDLInstanceIdentifierPolicy->allocate_generated_instance_identifier(
            desired => $desired, role => $role, reserved => $reserved,
        );
    };
    for my $domain (@$domains) {
        $domain->{instance} = $allocate->($domain->{name}, 'domain', \%instances);
        my $module = $domain->{scheduled_fsm};
        $module =~ s/\.fsm\z//;
        $domain->{scheduled_fsm} = $allocate->($module, 'domain', \%modules) . '.fsm';
    }
    for my $crossing (@$crossings) {
        my @prefixes = $crossing->{kind} eq 'event' ? ('') : ('start_', 'done_');
        for my $prefix (@prefixes) {
            my $instance = "${prefix}instance";
            my $module = "${prefix}module";
            $crossing->{$instance} = $allocate->($crossing->{$instance}, 'cdc', \%instances);
            $crossing->{$module} = $allocate->($crossing->{$module}, 'cdc', \%modules);
        }
    }
}

sub _actor_has_clock_domains {
    my ($actor) = @_;
    return ref($actor->{clock_domains}) eq 'HASH'
        && ref($actor->{clock_domains}{domains}) eq 'ARRAY'
        && @{$actor->{clock_domains}{domains}};
}

sub _domain_for_entry {
    my ($entry, $default_domain) = @_;
    return ref($entry) eq 'HASH' && defined($entry->{domain})
        ? $entry->{domain}
        : $default_domain;
}

sub _actor_domain_signal_map {
    my ($actor, $default_domain) = @_;
    my %signals;

    for my $input (@{$actor->{interface}{inputs} || []}) {
        $signals{$input->{name}} = {
            domain => _domain_for_entry($input, $default_domain),
            kind   => 'actor_input',
        };
        # Resolved record inputs own their member paths. Scalar pins may share
        # enum/package namespace names, so a pin name alone is insufficient.
        $signals{$input->{name}}{record_root} = 1
            if ref($input->{type_spec}) eq 'HASH'
                && ($input->{type_spec}{kind} // '') eq 'record';
    }
    for my $output (@{$actor->{interface}{outputs} || []}) {
        $signals{$output->{name}} = {
            domain => _domain_for_entry($output, $default_domain),
            kind   => 'actor_output',
        };
        $signals{$output->{name}}{record_root} = 1
            if ref($output->{type_spec}) eq 'HASH'
                && ($output->{type_spec}{kind} // '') eq 'record';
    }
    for my $storage (@{$actor->{storage} || []}) {
        my $domain = _domain_for_entry($storage, $default_domain);
        $signals{$storage->{name}} = {
            domain => $domain,
            kind   => 'actor_storage',
        };
        for my $signal (@{$storage->{signals} || []}) {
            $signals{$signal->{name}} = {
                domain => $domain,
                kind   => 'actor_storage',
            };
        }
    }
    for my $crossing (@{$actor->{crossings} || []}) {
        next unless ($crossing->{kind} // '') eq 'event';
        _register_domain_signal(
            \%signals,
            $crossing->{from}{signal},
            $crossing->{from}{domain},
            'crossing_request',
        );
        _register_domain_signal(
            \%signals,
            $crossing->{ready}{signal},
            $crossing->{from}{domain},
            'crossing_ready',
        );
        _register_domain_signal(
            \%signals,
            $crossing->{to}{signal},
            $crossing->{to}{domain},
            'crossing_pulse',
        );
    }

    return %signals;
}

sub _register_domain_signal {
    my ($signals, $name, $domain, $kind) = @_;
    return unless defined($name) && !ref($name) && length($name);
    if (exists $signals->{$name}) {
        my $existing = $signals->{$name};
        confess "ISF clock-domain violation: signal '$name' is owned by both domain '$existing->{domain}' and domain '$domain'\n"
            if defined($existing->{domain}) && defined($domain) && $existing->{domain} ne $domain;
        return 1;
    }
    $signals->{$name} = {
        domain => $domain,
        kind   => $kind,
    };
    return 1;
}

sub _validate_transaction_domain_refs($self, $actor, $signal_domains, $transaction_domains, $constants, $drive_use_domains, $default_domain, $pruned_transactions = undef) {
    $pruned_transactions ||= {};
    for my $tx (grep { !$pruned_transactions->{$_->{name}} } @{$actor->{transactions} || []}) {
        my $domain = _domain_for_entry($tx, $default_domain);
        my %local_signals = _transaction_local_signal_domains($tx, $domain, $signal_domains);
        for my $clause (@{$tx->{clauses} || []}) {
            _validate_transaction_clause_domain_refs(
                $clause,
                $actor,
                $tx,
                $domain,
                $signal_domains,
                \%local_signals,
                $transaction_domains,
                $constants,
                $drive_use_domains,
                'transaction body',
            );
        }
    }
    return 1;
}

sub _validate_rule_domain_refs($self, $actor, $signal_domains, $transaction_domains, $constants, $default_domain) {
    for my $rule (@{$actor->{rules} || []}) {
        my $domain = _domain_for_entry($rule, $default_domain);
        my %local_signals;
        if (my $when = $rule->{when}) {
            _validate_domain_expr_reads(
                $when->[1],
                $domain,
                $signal_domains,
                \%local_signals,
                $constants,
                "rule '$rule->{name}' guard",
            );
        }

        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY' && @$action;
            my $keyword = $action->[0];
            next unless defined($keyword) && !ref($keyword);

            next if $keyword eq 'atl_trigger';
            if ($keyword eq 'trigger') {
                my $target = $action->[1];
                _validate_same_domain_target(
                    "rule '$rule->{name}' trigger target '$target'",
                    $domain,
                    $transaction_domains->{$target},
                    'transaction',
                ) unless _control_flow_effects_prove_rule_trigger_target($actor, $rule->{name}, $target);
                for my $binding (_activation_bindings_from_clause($action, $rule->{name}, 'rule trigger')->@*) {
                    if ($binding->{role} eq 'input') {
                        _validate_domain_expr_reads(
                            $binding->{actor_expr},
                            $domain,
                            $signal_domains,
                            \%local_signals,
                            $constants,
                            "rule '$rule->{name}' trigger input binding '$binding->{port}'",
                        ) unless _control_flow_effects_prove_rule_trigger_binding_endpoint_domain(
                            $actor,
                            $rule->{name},
                            $target,
                            'input',
                            $binding->{port},
                            $binding->{actor_expr},
                        );
                    } else {
                        _validate_domain_signal_access(
                            $binding->{actor_signal},
                            'write',
                            $domain,
                            $signal_domains,
                            \%local_signals,
                            $constants,
                            "rule '$rule->{name}' trigger output binding '$binding->{port}'",
                        ) unless _control_flow_effects_prove_rule_trigger_binding_endpoint_domain(
                            $actor,
                            $rule->{name},
                            $target,
                            'output',
                            $binding->{port},
                            $binding->{actor_signal},
                        );
                    }
                }
                next;
            }
            next if $keyword eq 'priority';
            if ($keyword eq 'pulse') {
                _validate_domain_signal_access($action->[1], 'write', $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' pulse action");
                next;
            }

            if ($keyword eq 'set') {
                _validate_domain_signal_access($action->[1], 'write', $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' set action");
                _validate_domain_expr_reads($action->[2], $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' set action");
                next;
            }
            if ($keyword eq 'store') {
                _validate_domain_signal_access($action->[1], 'write', $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' store action");
                _validate_domain_expr_reads($action->[2], $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' store index");
                _validate_domain_expr_reads($action->[3], $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' store value");
                next;
            }
            if ($keyword eq 'load') {
                _validate_domain_signal_access($action->[1], 'read', $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' load action");
                _validate_domain_expr_reads($action->[2], $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' load index");
                _validate_domain_signal_access($action->[4], 'write', $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' load target");
                next;
            }

            _validate_domain_signal_access($keyword, 'write', $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' assignment");
            _validate_domain_expr_reads($action->[1], $domain, $signal_domains, \%local_signals, $constants, "rule '$rule->{name}' assignment");
        }
    }
    return 1;
}

sub _validate_library_use_domain_refs($self, $actor, $signal_domains, $default_domain) {
    my %local_signals;
    my %constants;
    for my $use (@{$actor->{library_uses} || []}) {
        my $domain = _domain_for_entry($use, $default_domain);
        for my $binding (@{$use->{bindings} || []}) {
            next unless ($binding->{role} // '') eq 'input' || ($binding->{role} // '') eq 'output';
            _validate_domain_signal_access(
                $binding->{parent_name},
                $binding->{role} eq 'input' ? 'read' : 'write',
                $domain,
                $signal_domains,
                \%local_signals,
                \%constants,
                "library use '$use->{instance}' $binding->{role} binding '$binding->{library_name}'",
            );
        }
    }
    return 1;
}

sub _transaction_local_signal_domains {
    my ($tx, $domain, $signal_domains) = @_;
    my %signals;
    _collect_transaction_local_signals($tx->{clauses}, $domain, \%signals);
    # Inferred assignment targets cannot redefine declared actor ownership.
    # Explicit transaction ports below retain their authored shadowing contract.
    delete @signals{keys %$signal_domains};

    for my $direction (qw(inputs outputs)) {
        for my $port (@{($tx->{ports} || {})->{$direction} || []}) {
            $signals{$port->{name}} = $domain;
        }
    }
    return %signals;
}

sub _collect_transaction_local_signals {
    my ($clauses, $domain, $signals) = @_;
    return unless ref($clauses) eq 'ARRAY';

    for my $clause (@$clauses) {
        next unless ref($clause) eq 'ARRAY' && @$clause;
        my $keyword = $clause->[0];
        next unless defined($keyword) && !ref($keyword);

        if (($keyword eq 'sample' || $keyword eq 'load') && @$clause >= 4) {
            $signals->{$clause->[-1]} = $domain
                if defined($clause->[-1]) && !ref($clause->[-1]);
            next;
        }
        if (($keyword eq 'update' || $keyword eq 'set' || $keyword eq 'shift_left' || $keyword eq 'shift_right')
            && defined($clause->[1])
            && !ref($clause->[1]))
        {
            $signals->{$clause->[1]} = $domain;
        }
        if ($keyword eq 'assemble') {
            my $as_idx = _as_index($clause, 2);
            if (defined($as_idx) && defined($clause->[$as_idx + 1]) && !ref($clause->[$as_idx + 1])) {
                $signals->{$clause->[$as_idx + 1]} = $domain;
            }
        }
        if ($keyword eq 'extract') {
            for my $item (@{$clause}[3 .. $#$clause]) {
                next if ref($item);
                $signals->{$item} = $domain if defined($item);
            }
        }

        if ($keyword eq 'when' || $keyword eq 'repeat' || $keyword eq 'while' || $keyword eq 'until') {
            _collect_transaction_local_signals([@{$clause}[2 .. $#$clause]], $domain, $signals);
        } elsif ($keyword eq 'switch') {
            for my $branch (@{$clause}[2 .. $#$clause]) {
                next unless ref($branch) eq 'ARRAY';
                _collect_transaction_local_signals([@{$branch}[1 .. $#$branch]], $domain, $signals);
            }
        }
    }
}

sub _validate_transaction_clause_domain_refs {
    my ($clause, $actor, $tx, $domain, $signal_domains, $local_signals, $transaction_domains, $constants, $drive_use_domains, $label) = @_;
    return unless ref($clause) eq 'ARRAY' && @$clause;

    my $keyword = $clause->[0];
    return unless defined($keyword) && !ref($keyword);
    my $context = "transaction '$tx->{name}'";

    if ($keyword eq 'domain' || $keyword eq 'ports' || $keyword eq 'params' || $keyword eq 'phase' || $keyword eq 'latency') {
        return 1;
    }
    if ($keyword eq 'stage') {
        for my $subclause (@{$clause}[2 .. $#$clause]) {
            next unless ref($subclause) eq 'ARRAY' && @$subclause == 2;
            my ($role, $signal) = @$subclause;
            next unless defined($role) && !ref($role);
            if ($role eq 'input') {
                _validate_domain_signal_access($signal, 'read', $domain, $signal_domains, $local_signals, $constants, "$context stage '$clause->[1]'");
            } elsif ($role eq 'output') {
                _validate_domain_signal_access($signal, 'write', $domain, $signal_domains, $local_signals, $constants, "$context stage '$clause->[1]'");
            }
        }
        return 1;
    }
    if ($keyword eq 'on' || $keyword eq 'await') {
        _validate_domain_signal_access($clause->[1], 'read', $domain, $signal_domains, $local_signals, $constants, "$context $keyword clause");
        if ($keyword eq 'on') {
            for my $subclause (@{$clause}[2 .. $#$clause]) {
                _validate_transaction_clause_domain_refs($subclause, $actor, $tx, $domain, $signal_domains, $local_signals, $transaction_domains, $constants, $drive_use_domains, 'on body');
            }
        }
        return 1;
    }
    if ($keyword eq 'await_all' || $keyword eq 'await_any') {
        _validate_domain_signal_access($clause->[1], 'read', $domain, $signal_domains, $local_signals, $constants, "$context $keyword clause");
        return 1;
    }
    if ($keyword eq 'sample') {
        _validate_domain_signal_access($clause->[1], 'read', $domain, $signal_domains, $local_signals, $constants, "$context sample clause");
        return 1;
    }
    if ($keyword eq 'complete') {
        _validate_domain_signal_access($clause->[1], 'write', $domain, $signal_domains, $local_signals, $constants, "$context complete clause");
        return 1;
    }
    if ($keyword eq 'wait') {
        _validate_domain_expr_reads($clause->[1], $domain, $signal_domains, $local_signals, $constants, "$context wait clause");
        return 1;
    }
    if ($keyword eq 'update' || $keyword eq 'set') {
        _validate_domain_signal_access($clause->[1], 'write', $domain, $signal_domains, $local_signals, $constants, "$context $keyword clause");
        _validate_domain_expr_reads($clause->[2], $domain, $signal_domains, $local_signals, $constants, "$context $keyword clause");
        return 1;
    }
    if ($keyword eq 'shift_left' || $keyword eq 'shift_right') {
        _validate_domain_signal_access($clause->[1], 'write', $domain, $signal_domains, $local_signals, $constants, "$context $keyword clause");
        _validate_domain_signal_access($clause->[1], 'read', $domain, $signal_domains, $local_signals, $constants, "$context $keyword clause");
        _validate_domain_expr_reads($clause->[2], $domain, $signal_domains, $local_signals, $constants, "$context $keyword clause");
        return 1;
    }
    if ($keyword eq 'assemble') {
        my $as_idx = _as_index($clause, 2);
        if (defined $as_idx) {
            for my $part (@{$clause}[1 .. $as_idx - 1]) {
                _validate_domain_expr_reads($part, $domain, $signal_domains, $local_signals, $constants, "$context assemble clause");
            }
            _validate_domain_signal_access($clause->[$as_idx + 1], 'write', $domain, $signal_domains, $local_signals, $constants, "$context assemble clause");
        }
        return 1;
    }
    if ($keyword eq 'extract') {
        _validate_domain_signal_access($clause->[1], 'read', $domain, $signal_domains, $local_signals, $constants, "$context extract clause");
        for my $item (@{$clause}[3 .. $#$clause]) {
            next if ref($item);
            _validate_domain_signal_access($item, 'write', $domain, $signal_domains, $local_signals, $constants, "$context extract clause");
        }
        return 1;
    }
    if ($keyword eq 'store') {
        _validate_domain_signal_access($clause->[1], 'write', $domain, $signal_domains, $local_signals, $constants, "$context store clause");
        _validate_domain_expr_reads($clause->[2], $domain, $signal_domains, $local_signals, $constants, "$context store index");
        _validate_domain_expr_reads($clause->[3], $domain, $signal_domains, $local_signals, $constants, "$context store value");
        return 1;
    }
    if ($keyword eq 'load') {
        _validate_domain_signal_access($clause->[1], 'read', $domain, $signal_domains, $local_signals, $constants, "$context load clause");
        _validate_domain_expr_reads($clause->[2], $domain, $signal_domains, $local_signals, $constants, "$context load index");
        _validate_domain_signal_access($clause->[4], 'write', $domain, $signal_domains, $local_signals, $constants, "$context load target");
        return 1;
    }
    if ($keyword eq 'drive') {
        if (defined($clause->[1]) && !ref($clause->[1]) && exists(($actor->{drives} || {})->{$clause->[1]})) {
            $drive_use_domains->{$clause->[1]}{$domain} = 1;
            for my $arg (@{$clause}[2 .. $#$clause]) {
                _validate_domain_expr_reads($arg, $domain, $signal_domains, $local_signals, $constants, "$context drive '$clause->[1]' call");
            }
        } else {
            my $first = ref($clause->[1]) eq 'ARRAY' ? 1 : 2;
            for my $assignment (@{$clause}[$first .. $#$clause]) {
                next unless ref($assignment) eq 'ARRAY' && @$assignment >= 2;
                _validate_domain_signal_access($assignment->[0], 'write', $domain, $signal_domains, $local_signals, $constants, "$context inline drive");
                _validate_domain_expr_reads($assignment->[1], $domain, $signal_domains, $local_signals, $constants, "$context inline drive");
            }
        }
        return 1;
    }
    if ($keyword eq 'do' || $keyword eq 'spawn') {
        my $target = $clause->[1];
        # A cross-domain `(do child)` covered by an `(activation ...)` crossing is
        # routed through CDC synchronizers, so the same-domain target checks are
        # intentionally skipped for it (the CDC routing is emitted in the
        # multi-domain top). Every other cross-domain reference still fails closed.
        # Supported at the transaction top level, directly inside a `repeat` body
        # (`.3`), and directly inside a branch body (`.4`: when/switch/while/until);
        # the partition gate further restricts each nested case to a TOP-LEVEL
        # container (deeper nestings defer there). Cross-domain `spawn` and
        # deeper-nested cross-domain `do` remain fail-closed.
        my $covered_activation_label =
            ($label // '') eq 'transaction body'
            || ($label // '') eq 'repeat body'
            || ($label // '') eq 'when body'
            || ($label // '') eq 'switch branch'
            || ($label // '') eq 'while body'
            || ($label // '') eq 'until body';
        my $covered_activation = $keyword eq 'do'
            && $covered_activation_label
            && _control_flow_effects_prove_activation_crossing($actor, $tx->{name}, $target);
        if (!$covered_activation) {
            _validate_same_domain_target(
                "$context $keyword target '$target'",
                $domain,
                $transaction_domains->{$target},
                'transaction',
            ) unless _control_flow_effects_prove_same_domain_activation($actor, $tx->{name}, $target);
            if (my $activation_domain = _activation_domain_from_clause($clause, $tx->{name}, $label)) {
                _validate_same_domain_target(
                    "$context $keyword instance domain '$activation_domain'",
                    $domain,
                    $activation_domain,
                    'activation',
                ) unless _control_flow_effects_prove_activation_domain_metadata($actor, $tx->{name}, $target, $activation_domain);
            }
        }
        for my $binding (_activation_bindings_from_clause($clause, $tx->{name}, $label)->@*) {
            if ($binding->{role} eq 'input') {
                _validate_domain_expr_reads($binding->{actor_expr}, $domain, $signal_domains, $local_signals, $constants, "$context $keyword input binding '$binding->{port}'")
                    unless _control_flow_effects_prove_binding_endpoint_domain($actor, $tx->{name}, $target, 'input', $binding->{port}, $binding->{actor_expr});
            } else {
                _validate_domain_signal_access($binding->{actor_signal}, 'write', $domain, $signal_domains, $local_signals, $constants, "$context $keyword output binding '$binding->{port}'")
                    unless _control_flow_effects_prove_binding_endpoint_domain($actor, $tx->{name}, $target, 'output', $binding->{port}, $binding->{actor_signal});
            }
        }
        return 1;
    }
    if ($keyword eq 'when' || $keyword eq 'while' || $keyword eq 'until') {
        _validate_domain_expr_reads($clause->[1], $domain, $signal_domains, $local_signals, $constants, "$context $keyword condition");
        for my $subclause (@{$clause}[2 .. $#$clause]) {
            _validate_transaction_clause_domain_refs($subclause, $actor, $tx, $domain, $signal_domains, $local_signals, $transaction_domains, $constants, $drive_use_domains, "$keyword body");
        }
        return 1;
    }
    if ($keyword eq 'repeat') {
        _validate_domain_expr_reads($clause->[1], $domain, $signal_domains, $local_signals, $constants, "$context repeat count");
        for my $subclause (@{$clause}[2 .. $#$clause]) {
            _validate_transaction_clause_domain_refs($subclause, $actor, $tx, $domain, $signal_domains, $local_signals, $transaction_domains, $constants, $drive_use_domains, 'repeat body');
        }
        return 1;
    }
    if ($keyword eq 'switch') {
        _validate_domain_expr_reads($clause->[1], $domain, $signal_domains, $local_signals, $constants, "$context switch selector");
        for my $branch (@{$clause}[2 .. $#$clause]) {
            next unless ref($branch) eq 'ARRAY';
            for my $subclause (@{$branch}[1 .. $#$branch]) {
                _validate_transaction_clause_domain_refs($subclause, $actor, $tx, $domain, $signal_domains, $local_signals, $transaction_domains, $constants, $drive_use_domains, 'switch branch');
            }
        }
        return 1;
    }

    return 1;
}

sub _validate_domain_expr_reads {
    my ($expr, $domain, $signal_domains, $local_signals, $constants, $context) = @_;
    return unless defined $expr;

    if (!ref($expr)) {
        _validate_domain_signal_access($expr, 'read', $domain, $signal_domains, $local_signals, $constants, $context);
        return 1;
    }
    return 1 unless ref($expr) eq 'ARRAY';

    for my $index (0 .. $#$expr) {
        next if $index == 0 && defined($expr->[$index]) && !ref($expr->[$index]);
        _validate_domain_expr_reads($expr->[$index], $domain, $signal_domains, $local_signals, $constants, $context);
    }
    return 1;
}

sub _validate_domain_signal_access {
    my ($name, $access, $domain, $signal_domains, $local_signals, $constants, $context) = @_;
    return 1 unless defined($name) && !ref($name);
    my $root = $name;
    if (!_is_hdl_identifier($root)) {
        # Indexed scalar references inherit any declared root's domain, with
        # local/formal ownership selected below. Dotted paths require storage
        # or a resolved record port, preserving scalar enum/package names.
        return 1 unless $name =~ /\A([A-Za-z_]\w*)((?:\.[A-Za-z_]\w*|\[\d+(?::\d+)?\])+)\z/;
        $root = $1;
        my $path = $2;
        if ($path !~ /\A(?:\[\d+(?::\d+)?\])+\z/) {
            return 1 unless exists($signal_domains->{$root})
                && (($signal_domains->{$root}{kind} // '') eq 'actor_storage'
                    || $signal_domains->{$root}{record_root});
        }
    }

    my $owner_domain;
    if (exists $local_signals->{$root}) {
        $owner_domain = $local_signals->{$root};
    } elsif (exists $signal_domains->{$root}) {
        $owner_domain = $signal_domains->{$root}{domain};
    } else {
        return 1;
    }

    confess "ISF clock-domain violation: $context $access signal '$name' owned by domain '$owner_domain' from domain '$domain' without a crossing primitive\n"
        if defined($owner_domain) && defined($domain) && $owner_domain ne $domain;

    return 1;
}

sub _validate_same_domain_target {
    my ($context, $owner_domain, $target_domain, $target_kind) = @_;
    return 1 unless defined($target_domain) && defined($owner_domain);

    confess "ISF clock-domain violation: $context references $target_kind in domain '$target_domain' from domain '$owner_domain' without a crossing primitive\n"
        if $target_domain ne $owner_domain;

    return 1;
}

sub _control_flow_effect_check($actor) {
    my $key = refaddr($actor);
    confess "ISF control-flow effect check cache expects an actor hash reference\n"
        unless defined($key);
    if (my $cached = $CONTROL_FLOW_EFFECT_CHECK_CACHE{$key}) {
        return $cached->{check}
            if defined($cached->{actor}) && $cached->{actor} == $actor;
    }

    my $entry = {
        actor => $actor,
        check => FSM::Scheduler::ISF::ControlFlowEffects->new()->check_actor($actor),
    };
    weaken($entry->{actor});
    $CONTROL_FLOW_EFFECT_CHECK_CACHE{$key} = $entry;
    return $entry->{check};
}

sub _control_flow_effects_prove_activation_crossing($actor, $transaction_name, $target) {
    return 0 unless defined($transaction_name) && !ref($transaction_name);
    return 0 unless defined($target) && !ref($target);

    my $check = _control_flow_effect_check($actor);
    for my $tx (@{$check->{transactions} || []}) {
        next unless ($tx->{name} // '') eq $transaction_name;
        for my $proof (@{$tx->{proofs} || []}) {
            next unless ($proof->{code} // '') eq 'activation_crossing_covers_child_start';
            next unless ($proof->{child} // '') eq $target;
            return 1;
        }
    }
    return 0;
}

sub _control_flow_effects_prove_same_domain_activation($actor, $transaction_name, $target) {
    return 0 unless defined($transaction_name) && !ref($transaction_name);
    return 0 unless defined($target) && !ref($target);

    my $check = _control_flow_effect_check($actor);
    for my $tx (@{$check->{transactions} || []}) {
        next unless ($tx->{name} // '') eq $transaction_name;
        for my $proof (@{$tx->{proofs} || []}) {
            next unless ($proof->{code} // '') eq 'activation_target_is_same_domain';
            next unless ($proof->{child} // '') eq $target;
            return 1;
        }
    }
    return 0;
}

sub _control_flow_effects_prove_activation_domain_metadata($actor, $transaction_name, $target, $activation_domain) {
    return 0 unless defined($transaction_name) && !ref($transaction_name);
    return 0 unless defined($target) && !ref($target);
    return 0 unless defined($activation_domain) && !ref($activation_domain);

    my $check = _control_flow_effect_check($actor);
    for my $tx (@{$check->{transactions} || []}) {
        next unless ($tx->{name} // '') eq $transaction_name;
        for my $proof (@{$tx->{proofs} || []}) {
            next unless ($proof->{code} // '') eq 'activation_domain_is_explicit';
            next unless ($proof->{child} // '') eq $target;
            next unless ($proof->{domain} // '') eq $activation_domain;
            return 1;
        }
    }
    return 0;
}

sub _control_flow_effects_prove_binding_endpoint_domain($actor, $transaction_name, $target, $role, $child_port, $actor_endpoint) {
    return 0 unless defined($transaction_name) && !ref($transaction_name);
    return 0 unless defined($target) && !ref($target);
    return 0 unless defined($role) && !ref($role);
    return 0 unless defined($child_port) && !ref($child_port);
    return 0 unless defined($actor_endpoint);
    my $actor_expr = ref($actor_endpoint) ? _format_isf_expr($actor_endpoint) : $actor_endpoint;
    return 0 if ref($actor_expr) || !defined($actor_expr);

    my $check = _control_flow_effect_check($actor);
    for my $tx (@{$check->{transactions} || []}) {
        next unless ($tx->{name} // '') eq $transaction_name;
        for my $proof (@{$tx->{proofs} || []}) {
            my $code = $proof->{code} // '';
            next unless $code eq 'binding_endpoint_is_same_domain'
                || ($role eq 'input' && $code eq 'binding_expression_endpoints_are_same_domain');
            next unless ($proof->{child} // '') eq $target;
            next unless ($proof->{role} // '') eq $role;
            next unless ($proof->{child_port} // '') eq $child_port;
            next unless ($proof->{actor_expr} // '') eq $actor_expr;
            return 1;
        }
    }
    return 0;
}

sub _control_flow_effects_prove_rule_trigger_target($actor, $rule_name, $target) {
    return 0 unless defined($rule_name) && !ref($rule_name);
    return 0 unless defined($target) && !ref($target);

    my $check = _control_flow_effect_check($actor);
    for my $rule (@{$check->{rules} || []}) {
        next unless ($rule->{name} // '') eq $rule_name;
        for my $proof (@{$rule->{proofs} || []}) {
            next unless ($proof->{code} // '') eq 'rule_trigger_target_is_same_domain';
            next unless ($proof->{target} // '') eq $target;
            return 1;
        }
    }
    return 0;
}

