sub _activation_override_preserves_static_integer_param {
    my ($declared_param, $override) = @_;
    return 0 unless ref($declared_param) eq 'HASH' && ref($override) eq 'HASH';

    my $declared_value = _non_negative_integer_from_literal(_param_resolved_value($declared_param));
    my $override_value = _non_negative_integer_from_literal($override->{value});
    return 0 unless defined($declared_value) && defined($override_value);

    return $declared_value == $override_value ? 1 : 0;
}

sub _collect_isf_value_declared_name_refs {
    my ($value, $declared, $used) = @_;
    return unless ref($declared) eq 'HASH' && ref($used) eq 'HASH';
    if (defined($value) && !ref($value)) {
        $used->{$value} = 1 if exists $declared->{$value};
        return;
    }
    return unless ref($value) eq 'ARRAY';
    for my $part (@$value) {
        _collect_isf_value_declared_name_refs($part, $declared, $used);
    }
}

sub _validate_transaction_port_bindings($self, $actor) {
    my %transaction_by_name = map { $_->{name} => $_ } @{$actor->{transactions} || []};
    my %generated_children = _generated_child_transaction_refs($actor);

    for my $tx (@{$actor->{transactions} || []}) {
        my $tx_name = $tx->{name};
        for my $ref (_live_child_action_refs_from_transaction_clauses($tx->{clauses}, $tx_name, $actor)) {
            my $clause = $ref->{clause};
            my $keyword = $ref->{keyword};
            my $label = $ref->{label};
            my $target = $clause->[1];
            next unless defined($target) && !ref($target) && exists $transaction_by_name{$target};
            my $context = $label eq 'repeat body'
                ? "Transaction '$tx_name': repeat-body $keyword target '$target'"
                : "Transaction '$tx_name': $keyword target '$target'";
            my $generated_instance = $keyword eq 'spawn'
                || ($keyword eq 'do' && $label eq 'transaction body' && $generated_children{$target})
                || ($keyword eq 'do' && $label eq 'repeat body' && _repeat_body_do_is_generated_activation($clause, $target, \%generated_children));
            _validate_activation_bindings(
                $actor,
                $tx,
                $transaction_by_name{$target},
                _activation_bindings_from_clause($clause, $tx_name, $label),
                $context,
                {
                    site_kind          => $keyword,
                    generated_instance => $generated_instance ? 1 : 0,
                },
            );
        }
    }

    for my $rule (@{$actor->{rules} || []}) {
        my $rule_name = $rule->{name};
        my %seen_rule_output_actor_target;
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY' && @$action;
            next unless defined($action->[0]) && !ref($action->[0]) && $action->[0] eq 'trigger';
            my $target = $action->[1];
            next unless defined($target) && !ref($target) && exists $transaction_by_name{$target};
            my $bindings = _activation_bindings_from_clause($action, $rule_name, 'rule trigger');
            _validate_activation_bindings(
                $actor,
                undef,
                $transaction_by_name{$target},
                $bindings,
                "Rule '$rule_name': trigger target '$target'",
                {
                    allow_outputs      => $generated_children{$target} ? 1 : 0,
                    site_kind          => 'rule_trigger',
                    generated_instance => $generated_children{$target} ? 1 : 0,
                },
            );
            next unless $generated_children{$target};
            for my $binding (@$bindings) {
                next unless $binding->{role} eq 'output';
                my $actor_signal = $binding->{actor_signal};
                confess "Rule '$rule_name': generated trigger output bindings target actor signal '$actor_signal' more than once\n"
                    if $seen_rule_output_actor_target{$actor_signal}++;
            }
        }
    }

    return 1;
}

sub _transaction_port_binding_metadata {
    my ($actor) = @_;
    my %transaction_by_name = map { $_->{name} => $_ } @{$actor->{transactions} || []};
    my %generated_children = _generated_child_transaction_refs($actor);
    my @metadata;

    for my $tx (@{$actor->{transactions} || []}) {
        my $owner = $tx->{name};
        my $do_ordinal = 0;
        for my $ref (_live_child_action_refs_from_transaction_clauses($tx->{clauses}, $owner, $actor)) {
            my $clause = $ref->{clause};
            my $keyword = $ref->{keyword};
            my $label = $ref->{label};
            my $target = $clause->[1];
            next unless defined($target) && !ref($target) && exists $transaction_by_name{$target};
            my $current_do_ordinal;
            if ($keyword eq 'do' && $label eq 'transaction body') {
                $current_do_ordinal = $do_ordinal++;
            }
            my $repeat_body_generated_do = $keyword eq 'do'
                && $label eq 'repeat body'
                && _repeat_body_do_is_generated_activation($clause, $target, \%generated_children);

            my $bindings = _activation_bindings_from_clause($clause, $owner, $label);
            next unless @$bindings;
            my %target_ports = _transaction_port_map($transaction_by_name{$target});
            my $instance = $keyword eq 'spawn'
                ? ($clause->[3] // "${owner}_spawn")
                : $repeat_body_generated_do
                    ? _generated_repeat_do_instance_name($owner, $target, $ref->{repeat_do_ordinal} // 0)
                    : ($generated_children{$target} && defined($current_do_ordinal) ? _generated_do_instance_name($owner, $target, $current_do_ordinal) : undef);
            for my $binding (@$bindings) {
                push @metadata, _transaction_port_binding_entry(
                    binding            => $binding,
                    port               => $target_ports{$binding->{port}},
                    site_kind          => $keyword,
                    owner              => $owner,
                    owner_kind         => 'transaction',
                    target_transaction => $target,
                    instance           => $instance,
                );
            }
        }
    }

    for my $rule (@{$actor->{rules} || []}) {
        my $owner = $rule->{name};
        my %trigger_ordinals;
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY' && @$action;
            next unless defined($action->[0]) && !ref($action->[0]) && $action->[0] eq 'trigger';
            my $target = $action->[1];
            next unless defined($target) && !ref($target) && exists $transaction_by_name{$target};

            my $generated_trigger = $generated_children{$target} ? 1 : 0;
            my $trigger_ordinal;
            my $instance;
            if ($generated_trigger) {
                my $key = "$owner\0$target";
                $trigger_ordinal = $trigger_ordinals{$key}++;
                $instance = _generated_rule_trigger_instance_name($owner, $target, $trigger_ordinal);
            }

            my $bindings = _activation_bindings_from_clause($action, $owner, 'rule trigger');
            next unless @$bindings;
            my %target_ports = _transaction_port_map($transaction_by_name{$target});
            for my $binding (@$bindings) {
                push @metadata, _transaction_port_binding_entry(
                    binding            => $binding,
                    port               => $target_ports{$binding->{port}},
                    site_kind          => 'rule_trigger',
                    owner              => $owner,
                    owner_kind         => 'rule',
                    target_transaction => $target,
                    instance           => $instance,
                    trigger_source     => _rule_trigger_source_name($owner, $target, $trigger_ordinal),
                    payload_source     => $binding->{role} eq 'input'
                        ? _rule_trigger_payload_source_name($owner, $target, $target_ports{$binding->{port}}{source_name}, $trigger_ordinal)
                        : undef,
                );
            }
        }
    }

    return \@metadata;
}

sub _transaction_port_binding_entry {
    my (%args) = @_;
    my $binding = $args{binding};
    my $role = $binding->{role};
    my $port = $binding->{port};
    my $site_kind = $args{site_kind};
    my $target = $args{target_transaction};
    my $instance = $args{instance};

    return {
        site_kind          => $site_kind,
        owner              => $args{owner},
        owner_kind         => $args{owner_kind},
        target_transaction => $target,
        role               => $role,
        port               => $port,
        actor_signal        => $binding->{actor_signal},
        actor_expression    => _activation_binding_actor_expr_text($binding),
        actor_endpoint_kind => _activation_binding_actor_endpoint_kind($binding),
        binding_timing      => _transaction_port_binding_timing($site_kind, $role, $instance),
        authored_timing_mode => $binding->{timing_mode},
        width               => ($args{port} || {})->{width} // 1,
        instance            => $instance,
        parent_port         => defined($instance) ? "${instance}_$port" : undef,
        child_port          => defined($instance) ? $port : undef,
        start_signal        => defined($instance) ? "${instance}_start" : "${target}_start",
        done_signal         => $site_kind eq 'rule_trigger'
            ? ($role eq 'output' && defined($instance) ? "${instance}_done_seen" : undef)
            : (defined($instance) ? "${instance}_done" : "${target}_done"),
        trigger_source      => $site_kind eq 'rule_trigger'
            ? ($args{trigger_source} // _rule_trigger_source_name($args{owner}, $target))
            : undef,
        payload_source      => $site_kind eq 'rule_trigger' && $role eq 'input'
            ? ($args{payload_source} // _rule_trigger_payload_source_name($args{owner}, $target, $args{port}{source_name} // $port))
            : undef,
    };
}

sub _transaction_port_binding_timing {
    my ($site_kind, $role, $instance) = @_;

    return 'trigger_payload'
        if $site_kind eq 'rule_trigger' && $role eq 'input';
    return 'done_guarded'
        if $role eq 'output' && ($site_kind eq 'do' || $site_kind eq 'rule_trigger');
    return 'generated_live_handoff'
        if defined($instance) && length($instance);
    return 'activation_region';
}

sub _actor_param_declarations {
    my ($actor) = @_;
    return [] unless ref($actor) eq 'HASH';

    my $actor_name = $actor->{actor_name} // 'unknown';
    my @params;
    my %seen;
    my %earlier_scalar_param_values;
    for my $param (@{$actor->{params} || []}) {
        confess "Actor '$actor_name': params entries must be hash references\n"
            unless ref($param) eq 'HASH';
        my $name = $param->{name};
        confess "Actor '$actor_name': parameter names must be scalar HDL identifiers\n"
            unless _is_hdl_identifier($name);
        confess "Actor '$actor_name': duplicate parameter '$name'\n"
            if $seen{$name}++;
        my $value = $param->{value};
        my %resolved_value;
        if (ref($value)
            || (!ref($value) && defined($value) && (_is_hdl_identifier($value) || _is_enum_member_reference($value) || _is_package_constant_path_reference_shape($value))))
        {
            my ($resolved, $has_static_leaf) = _resolve_actor_param_default_value(
                $value,
                "Actor '$actor_name': parameter '$name'",
                $actor,
                \%earlier_scalar_param_values,
            );
            %resolved_value = (resolved_value => _clone_isf_value($resolved))
                if $has_static_leaf;
        } else {
            _validate_isf_param_value(
                $value,
                "Actor '$actor_name': parameter '$name'",
            );
        }
        my $entry = {
            name  => $name,
            value => _clone_isf_value($value),
            (exists($param->{resolved_value}) ? (resolved_value => _clone_isf_value($param->{resolved_value})) : %resolved_value),
        };
        push @params, $entry;
        _record_earlier_scalar_actor_param_value(\%earlier_scalar_param_values, $entry);
    }

    return \@params;
}

sub _resolve_actor_param_default_value {
    my ($value, $context, $actor, $earlier_scalar_param_values) = @_;
    $earlier_scalar_param_values ||= {};

    if (!ref($value)) {
        return (_clone_isf_value($value), 0)
            if defined($value) && _is_numeric_or_exact_width_literal($value);

        if (my $package_constant = _actor_package_constant_reference($actor, $value)) {
            my ($package_name, $constant_name, $suffix) = @$package_constant;
            my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
            if (defined $constant_payload) {
                confess "$context token '$value' is ambiguous: it matches local enum member '$value' and imported package constant '$value'\n"
                    if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
                confess "$context package constant '$package_name.$constant_name' aggregate/member path '$value' remains deferred; actor parameter defaults accept only qualified package scalar constants in this slice\n"
                    if $suffix ne '';
                my $resolved_value = _package_constant_scalar_value($constant_payload);
                confess "$context package constant '$package_name.$constant_name' must resolve to a scalar numeric or exact-width literal value\n"
                    unless defined($resolved_value)
                        && !ref($resolved_value)
                        && _is_numeric_or_exact_width_literal($resolved_value);
                return (_clone_isf_value($resolved_value), 1);
            }

            confess "$context references unknown package constant '$value'\n"
                if $suffix eq '' && !_actor_local_enum_member_exists($actor, $package_name, $constant_name);
        }

        if (_is_enum_member_reference($value)) {
            my $resolved_value = _resolve_actor_enum_member_value($actor, $value);
            confess "$context references unknown enum member '$value'\n"
                unless defined($resolved_value) && !ref($resolved_value);
            confess "$context enum member '$value' must resolve to a non-negative integer literal value\n"
                unless defined _non_negative_integer_from_literal($resolved_value);
            return (_clone_isf_value($resolved_value), 1);
        }
        if (_is_hdl_identifier($value)) {
            if (my $constant = _actor_constant_by_name($actor, $value)) {
                my $resolved_value = _constant_resolved_value($constant);
                confess "$context actor constant '$value' must resolve to a scalar numeric or exact-width literal value\n"
                    unless defined($resolved_value)
                        && !ref($resolved_value)
                        && _is_numeric_or_exact_width_literal($resolved_value);
                return (_clone_isf_value($resolved_value), 1);
            }

            if (_actor_param_by_name($actor, $value)) {
                if (exists $earlier_scalar_param_values->{$value}) {
                    return (_clone_isf_value($earlier_scalar_param_values->{$value}), 1);
                }
                confess "$context actor parameter '$value' must reference an earlier scalar actor parameter default; forward, self, cyclic, and non-scalar actor-parameter defaults remain deferred\n";
            }

            if (my $tx = _actor_transaction_param_by_name($actor, $value)) {
                my $tx_name = $tx->{name} // 'unknown';
                confess "$context transaction parameter '$value' from transaction '$tx_name' cannot be used as an actor parameter default; transaction parameters are scoped to generated child transactions\n";
            }

            confess "$context token '$value' is a runtime interface signal; actor parameter defaults accept literals, declared actor constants, earlier scalar actor parameters, enum members, and qualified package scalar constants only\n"
                if _actor_interface_signal_by_name($actor, $value);

            confess "$context token '$value' is not a declared actor constant, earlier scalar actor parameter, enum member, or qualified package scalar constant\n";
        }
        confess "$context uses unsupported parameter value '$value'; actor parameter aggregate/list defaults accept numeric, exact-width, actor constant, earlier scalar actor parameter, enum member, and qualified package scalar constant literal leaves only\n";
    }

    confess "$context uses unsupported parameter value shape; actor parameter defaults accept non-empty aggregate/list literals\n"
        unless ref($value) eq 'ARRAY' && @$value;

    my @resolved;
    my $has_static_leaf = 0;
    for my $item (@$value) {
        my ($resolved_item, $item_has_static_leaf) = _resolve_actor_param_default_value(
            $item,
            $context,
            $actor,
            $earlier_scalar_param_values,
        );
        push @resolved, $resolved_item;
        $has_static_leaf ||= $item_has_static_leaf;
    }

    return (\@resolved, $has_static_leaf);
}

sub _record_earlier_scalar_actor_param_value {
    my ($earlier_scalar_param_values, $param) = @_;
    return unless ref($earlier_scalar_param_values) eq 'HASH' && ref($param) eq 'HASH';

    my $name = $param->{name};
    return unless defined($name) && !ref($name);

    my $resolved_value = _param_resolved_value($param);
    if (defined($resolved_value)
        && !ref($resolved_value)
        && _is_numeric_or_exact_width_literal($resolved_value))
    {
        $earlier_scalar_param_values->{$name} = _clone_isf_value($resolved_value);
        return;
    }

    delete $earlier_scalar_param_values->{$name};
    return;
}

