            elsif($bk2 eq'update'||$bk2 eq'set'||$bk2 eq'shift_left'||$bk2 eq'shift_right'||$bk2 eq'assemble'||$bk2 eq'extract'){_push_sample_state(\@body_states,$tn,\@lp,$ir);push @body_states,_ir_data_op($bk2,$bc2,$tn,$$ir++,$widths,$actor)}
            elsif($bk2 eq'store'||$bk2 eq'load'){_push_sample_state(\@body_states,$tn,\@lp,$ir);my($state,$accesses)=_ir_bank_access($bc2,$tn,$$ir++,$actor,$widths,'transaction');push @body_states,$state;push @$bank_accesses,@$accesses if ref($bank_accesses)eq'ARRAY'}
            elsif($bk2 eq'do'){_push_sample_state(\@body_states,$tn,\@lp,$ir);my $cond_ord=scalar(grep { ref($_)eq'HASH'&&$_->{branch_do} } @{$spawn_refs||[]});my $do_ref=_conditional_do_ref_from_clause($bc2,$tn,$cond_ord,$constant_values||{},$actor,$generated_children,'switch branch');if($do_ref->{generated_child}){push @$spawn_refs,_clone_isf_value($do_ref) if ref($spawn_refs)eq'ARRAY';push @body_states,_ir_do($bc2,$tn,$$ir++,$do_ref,'switch branch')}else{push @body_states,_ir_do($bc2,$tn,$$ir++,undef,'switch branch')}}
            elsif($bk2 eq'spawn'){_push_sample_state(\@body_states,$tn,\@lp,$ir);my $sref=_spawn_ref_from_clause($bc2,$tn,$constant_values,$actor,'switch branch');push @$spawn_refs,$sref if ref($spawn_refs)eq'ARRAY';push @dps,"$sref->{instance}_done";push @body_states,_ir_spawn($bc2,$tn,$$ir++)}
            elsif($bk2 eq'await_all'){_push_sample_state(\@body_states,$tn,\@lp,$ir);push @body_states,_ir_sync_all($tn,$$ir++,\@dps);@dps=()}
            elsif($bk2 eq'await_any'){_push_sample_state(\@body_states,$tn,\@lp,$ir);push @body_states,_ir_sync_any($tn,$$ir++,\@dps);@dps=() if @dps <= 1}
            elsif($bk2 eq'when'){my($ws)=_expand_when($bc2,$tn,$ir,\@lp,$drives,$wd,$widths,$counters,$storage_roles,$actor,$bank_accesses,$spawn_refs,$constant_values,$generated_children,$repeat_do_ordinal_ref);push @body_states,@$ws}}
        if(@lp||!@body_states){push @body_states,_ir_sample_state($tn,\@lp,$$ir++)if@lp;push @body_states,{name=>"${tn}_switch_${val}_" . $$ir++,kind=>'sequential',assignments=>[],transitions=>[]}unless@body_states}
        push @branches,{value=>$val,body_start=>$body_states[0]{name}};
        push @branch_state_names, map { $_->{name} } @body_states;
        push @branch_end_names, $body_states[-1]{name};
        push @s,@body_states}
    my $sw_name="${tn}_switch_" . $$ir++;
    my $bstate={name=>$sw_name,kind=>'switch',signal=>$signal,branches=>\@branches,has_default_branch=>scalar(grep { _is_default_switch_value($_->{value}) } @branches) ? 1 : 0,branch_state_names=>\@branch_state_names,branch_end_names=>\@branch_end_names,assignments=>[],transitions=>[]};
    unshift @s,$bstate; return (\@s);
}
sub _ir_sync_all { my ($tn,$i,$dps)=@_; {name=>"${tn}_await_all_$i",kind=>'sync_all',assignments=>[],transitions=>[],done_ports=>[@$dps]} }
sub _ir_sync_any { my ($tn,$i,$dps)=@_; {name=>"${tn}_await_any_$i",kind=>'sync_any',assignments=>[],transitions=>[],done_ports=>[@$dps]} }

sub _expand_loop_body {
    my ($body_clauses, $tn, $ir, $pending_samples, $wd, $drives, $widths, $counters, $storage_roles, $actor, $bank_accesses, $body_label, $spawn_refs, $constant_values, $generated_children, $repeat_do_ordinal_ref) = @_;
    my @states;
    my @lp = @{$pending_samples || []};
    my @dps;
    $body_label //= 'loop body';

    for my $bc (@$body_clauses) {
        next unless ref($bc) eq 'ARRAY';
        my $bk = $bc->[0];

        if ($bk eq 'drive') {
            push @states, _ir_transaction_drive_clause($bc, $tn, $$ir++, $drives, [splice @lp]);
        } elsif ($bk eq 'await') {
            push @states, _ir_await($bc, $tn, $$ir++, $wd, [splice @lp]);
        } elsif ($bk eq 'sample') {
            push @lp, $bc;
        } elsif ($bk eq 'wait') {
            my $wait = _wait_count_spec($bc, $tn, $body_label, $actor, $widths, 1);
            if ($wait->{kind} eq 'static') {
                if ($wait->{cycles} > 0) {
                    push @states, @{_ir_wait($bc, $tn, $ir, [splice @lp], $actor, $body_label, $wait)};
                }
            } else {
                my ($dynamic_states, $counter, $counter_width) = _ir_dynamic_wait($bc, $tn, $ir, $wait, [splice @lp]);
                push @states, @$dynamic_states;
                _register_counter_width($counters, $counter, $counter_width) if $counters;
                $storage_roles->{$counter} = 'dynamic_wait_counter'
                    if ref($storage_roles) eq 'HASH';
            }
        } elsif ($bk eq 'complete') {
            push @states, _ir_complete($bc, $tn, $$ir++);
        } elsif ($bk eq 'exit-when') {
            # ISF-LOOP-EARLY-EXIT: a `(exit-when cond)` mid-loop early exit. Emit a
            # decision state whose TRUE edge leaves the loop (resolved to the loop's
            # `loop_exit_target` in `_link_states`) and whose FALSE edge falls through
            # to the next body clause. Only valid directly in a `while`/`until` body.
            confess "Transaction '$tn': $body_label '(exit-when ...)' requires exactly one condition expression\n"
                unless @$bc == 2 && defined($bc->[1]);
            _push_sample_state(\@states, $tn, \@lp, $ir);
            push @states, {
                name           => "${tn}_exit_when_" . $$ir++,
                kind           => 'loop_exit_when',
                condition      => $bc->[1],
                exit_when_condition => _format_isf_expr($bc->[1]),  # ISF-LOOP-EARLY-EXIT.4: report metadata
                loop_exit_when => 1,
                assignments    => [],
                transitions    => [],
            };
        } elsif ($bk eq 'continue-when') {
            # ISF-LOOP-CONTINUE: a `(continue-when cond)` skip-to-next-iteration. Same
            # decision-state machinery as `(exit-when)` (kind `loop_exit_when`), but
            # marked `loop_continue_when` so `_link_states` stamps the loop's TAIL
            # CHECK (re-evaluate the condition) as the TRUE target instead of the loop
            # exit; the FALSE edge falls through to the next body clause.
            confess "Transaction '$tn': $body_label '(continue-when ...)' requires exactly one condition expression\n"
                unless @$bc == 2 && defined($bc->[1]);
            _push_sample_state(\@states, $tn, \@lp, $ir);
            push @states, {
                name               => "${tn}_continue_when_" . $$ir++,
                kind               => 'loop_exit_when',
                condition          => $bc->[1],
                exit_when_condition => _format_isf_expr($bc->[1]),  # ISF-LOOP-EARLY-EXIT.4: report metadata
                loop_exit_when     => 1,
                loop_continue_when => 1,
                assignments        => [],
                transitions        => [],
            };
        } elsif ($bk eq 'do') {
            _push_sample_state(\@states, $tn, \@lp, $ir);
            my $cond_ord = scalar(grep { ref($_) eq 'HASH' && $_->{branch_do} } @{$spawn_refs || []});
            my $do_ref = _conditional_do_ref_from_clause($bc, $tn, $cond_ord, $constant_values || {}, $actor, $generated_children, $body_label);
            if ($do_ref->{generated_child}) {
                push @$spawn_refs, _clone_isf_value($do_ref) if ref($spawn_refs) eq 'ARRAY';
                push @states, _ir_do($bc, $tn, $$ir++, $do_ref, $body_label);
            } else {
                push @states, _ir_do($bc, $tn, $$ir++, undef, $body_label);
            }
        } elsif ($bk eq 'spawn') {
            _push_sample_state(\@states, $tn, \@lp, $ir);
            my $sref = _spawn_ref_from_clause($bc, $tn, $constant_values, $actor, $body_label);
            push @$spawn_refs, $sref if ref($spawn_refs) eq 'ARRAY';
            push @dps, "$sref->{instance}_done";
            push @states, _ir_spawn($bc, $tn, $$ir++);
        } elsif ($bk eq 'await_all') {
            _push_sample_state(\@states, $tn, \@lp, $ir);
            push @states, _ir_sync_all($tn, $$ir++, \@dps);
            @dps = ();
        } elsif ($bk eq 'await_any') {
            _push_sample_state(\@states, $tn, \@lp, $ir);
            push @states, _ir_sync_any($tn, $$ir++, \@dps);
            @dps = () if @dps <= 1;
        } elsif ($bk eq 'repeat') {
            my ($rs, $rc, $rw, $rdw) = _ir_repeat($bc, $tn, $ir, \@lp, $wd, $drives, $widths, $actor, $bank_accesses, $spawn_refs, $constant_values, $generated_children, $repeat_do_ordinal_ref);
            push @states, @$rs;
            _register_repeat_counters($counters, $storage_roles, $rc, $rw, $rdw);
        } elsif ($bk eq 'update' || $bk eq 'set' || $bk eq 'shift_left' || $bk eq 'shift_right' || $bk eq 'assemble' || $bk eq 'extract') {
            _push_sample_state(\@states, $tn, \@lp, $ir);
            push @states, _ir_data_op($bk, $bc, $tn, $$ir++, $widths, $actor);
        } elsif ($bk eq 'store' || $bk eq 'load') {
            _push_sample_state(\@states, $tn, \@lp, $ir);
            my ($state, $accesses) = _ir_bank_access($bc, $tn, $$ir++, $actor, $widths, 'transaction');
            push @states, $state;
            push @$bank_accesses, @$accesses if ref($bank_accesses) eq 'ARRAY';
        } elsif ($bk eq 'when') {
            my ($ws) = _expand_when($bc, $tn, $ir, \@lp, $drives, $wd, $widths, $counters, $storage_roles, $actor, $bank_accesses, $spawn_refs, $constant_values, $generated_children, $repeat_do_ordinal_ref);
            push @states, @$ws;
        }
    }

    if (@lp) {
        push @states, _ir_sample_state($tn, \@lp, $$ir++);
    }

    return \@states;
}

sub _ir_repeat {
    my ($cl,$tn,$ir,$ps,$wd,$drives,$widths,$actor,$bank_accesses,$spawn_refs,$constant_values,$generated_children,$repeat_do_ordinal_ref,$counter_name)=@_;
    # ISF-NESTED-COUNTED-REPEAT: each repeat instance owns its counter. The outermost (and
    # sequential/while/until/switch-contained) repeats keep the bare `${tn}_cnt`; a nested
    # repeat is lowered with a unique `${tn}_cnt_<ir>` so an inner and outer counter never
    # collide.
    my $ctr = (defined($counter_name) && length($counter_name)) ? $counter_name : "${tn}_cnt";
    my @s; my @lp; my @dynamic_wait_counters; my @nested_repeat_counters; my @spawn_done_ports;
    _validate_repeat_count_source($cl->[1], $widths, $actor, $tn);
    if (_is_static_zero_repeat_count($cl->[1], $actor, $tn)) {
        return ([], undef, undef, []);
    }
    my $width = _repeat_count_width($cl->[1], $widths, $actor, $tn);
    my $runtime_count_source = _runtime_repeat_count_source($cl->[1], $widths, $actor, $tn);
    my $repeat_count_load_value = _repeat_count_load_value($cl->[1], $actor, $tn);
    push @s, {
        name => "${tn}_repeat_init_".$$ir++,
        kind => 'repeat_init',
        assignments => [{lhs=>$ctr,rhs=>$repeat_count_load_value,op=>'<='}],
        transitions => [],
        repeat_counter => $ctr,
        repeat_count_source => $cl->[1],
        repeat_count_kind => defined($runtime_count_source) ? 'runtime_scalar' : 'static_or_unclassified',
        repeat_runtime_count_source => $runtime_count_source,
    };
    for my $bc(@{$cl}[2..$#$cl]){next unless ref($bc)eq'ARRAY';my $bk=$bc->[0];
        if($bk eq'drive'){push @s,_ir_transaction_drive_clause($bc,$tn,$$ir++,$drives,[splice @lp])}
        elsif($bk eq'await'){push @s,_ir_await($bc,$tn,$$ir++,$wd,[splice @lp])}
        elsif($bk eq'sample'){push @lp,$bc}
        elsif($bk eq'wait'){
            my $wait = _wait_count_spec($bc,$tn,'repeat body',$actor,$widths,1);
            if ($wait->{kind} eq 'static') {
                if ($wait->{cycles} > 0) {
                    push @s,@{_ir_wait($bc,$tn,$ir,[splice @lp],$actor,'repeat body',$wait)};
                }
            } else {
                my ($states,$counter,$counter_width)=_ir_dynamic_wait($bc,$tn,$ir,$wait,[splice @lp]);
                push @s,@$states;
                push @dynamic_wait_counters,{name=>$counter,width=>$counter_width};
            }
        }
        elsif($bk eq'update'||$bk eq'set'||$bk eq'shift_left'||$bk eq'shift_right'||$bk eq'assemble'||$bk eq'extract'){_push_sample_state(\@s,$tn,\@lp,$ir);push @s,_ir_data_op($bk,$bc,$tn,$$ir++,$widths,$actor)}
        elsif($bk eq'store'||$bk eq'load'){_push_sample_state(\@s,$tn,\@lp,$ir);my($state,$accesses)=_ir_bank_access($bc,$tn,$$ir++,$actor,$widths,'transaction');push @s,$state;push @$bank_accesses,@$accesses if ref($bank_accesses)eq'ARRAY'}
        elsif($bk eq'spawn'){
            _push_sample_state(\@s,$tn,\@lp,$ir);
            my $spawn_ref = _spawn_ref_from_clause($bc,$tn,$constant_values || {},$actor,'repeat body');
            push @$spawn_refs, $spawn_ref if ref($spawn_refs) eq 'ARRAY';
            push @spawn_done_ports, "$spawn_ref->{instance}_done";
            push @s,_ir_spawn($bc,$tn,$$ir++);
        }
        elsif($bk eq'do'){
            _push_sample_state(\@s,$tn,\@lp,$ir);
            my $repeat_do_ordinal = ref($repeat_do_ordinal_ref) ? $$repeat_do_ordinal_ref++ : 0;
            my $do_ref = _repeat_do_ref_from_clause($bc,$tn,$repeat_do_ordinal,$constant_values || {},$actor,$generated_children);
            push @$spawn_refs, _clone_isf_value($do_ref)
                if ref($spawn_refs) eq 'ARRAY' && $do_ref->{generated_child};
            push @s,_ir_do($bc,$tn,$$ir++,$do_ref,'repeat body');
        }
        elsif($bk eq'await_all'){
            _push_sample_state(\@s,$tn,\@lp,$ir);
            push @s,_ir_sync_all($tn,$$ir++,\@spawn_done_ports);
            @spawn_done_ports = ();
        }
        elsif($bk eq'await_any'){
            _push_sample_state(\@s,$tn,\@lp,$ir);
            push @s,_ir_sync_any($tn,$$ir++,\@spawn_done_ports);
            @spawn_done_ports = () if @spawn_done_ports <= 1;
        }
        elsif($bk eq'repeat'){
            # ISF-NESTED-COUNTED-REPEAT: a nested counted repeat. Flush pending samples,
            # then lower it recursively with a UNIQUE counter (the bare ${tn}_cnt is in use
            # by this outer repeat). Collect the nested counter (and any deeper nested or
            # dynamic-wait counters it returns) so they get registered in +size.
            _push_sample_state(\@s,$tn,\@lp,$ir);
            my $nested_ctr="${tn}_cnt_".$$ir;
            my ($rs,$rc,$rw,$rxc)=_ir_repeat($bc,$tn,$ir,$ps,$wd,$drives,$widths,$actor,$bank_accesses,$spawn_refs,$constant_values,$generated_children,$repeat_do_ordinal_ref,$nested_ctr);
            push @s,@$rs;
            push @nested_repeat_counters,{name=>$rc,width=>$rw} if defined($rc) && length($rc);
            push @nested_repeat_counters,@$rxc if ref($rxc) eq 'ARRAY';
        }}
    if(@lp){push @s,_ir_sample_state($tn,\@lp,$$ir++)}
    # ISF-COUNTED-REPEAT-TERMINATION: the loop-back targets the FIRST BODY state, not the
    # repeat_init state. Looping back to repeat_init would reload the counter every
    # iteration (cnt <= N), so the per-iteration decrement never sticks and the loop never
    # terminates. The body still re-runs from its first state each iteration (so the
    # spawn/do/await and cross-domain-handshake machinery still re-arm), but the counter is
    # loaded exactly once. For an empty body, loop back to the check itself (a pure
    # N-cycle countdown).
    my $check_name = "${tn}_repeat_check_".$$ir++;
    my $fb = (@s >= 2) ? $s[1]{name} : $check_name;
    # Decrement via the '--' operator — a clean per-iteration decrement whose dedicated
    # write-enable stays disjoint from the counter's load enable (the init loads the raw
    # count as a copy), so the generated one-hot selector assertion has no false conflict.
    push @s, {name=>$check_name,kind=>'repeat_check',assignments=>[{lhs=>$ctr,op=>'--'}],transitions=>[],loop_target=>$fb,counter=>$ctr};
    $s[0]{repeat_state_names} = [map { $_->{name} } @s];
    # The 4th value carries every "extra" counter the caller must register in +size: this
    # repeat's dynamic-wait counters plus any nested repeat counters (and their own nested
    # counters, bubbled up).
    return (\@s,$ctr,$width,[@dynamic_wait_counters,@nested_repeat_counters]);
}

sub _apply_rule_user_resource_arbitration {
    my ($ir, $actor) = @_;
    my @resources = @{$actor->{resources} || []};
    my %rule_dt = map {
        (($_->{kind} // '') eq 'rule') ? ($_->{name} => $_) : ()
    } @{$ir->{dt_blocks} || []};
    my %transactions = map { $_->{name} => 1 } @{$actor->{transactions} || []};
    my %generated_children = _generated_child_transaction_refs($actor);
    my %output_bundle_member_targets = map { $_->{name} => 1 } @{$actor->{interface}{outputs} || []};
    my %storage_port_member_targets;
    for my $entry (@{$actor->{storage} || []}) {
        for my $signal (@{$entry->{signals} || []}) {
            $output_bundle_member_targets{$signal->{name}} = 1
                if defined($signal->{name}) && !ref($signal->{name});
            $storage_port_member_targets{$signal->{name}} = 1
                if defined($signal->{name}) && !ref($signal->{name});
        }
    }
    my %original_guard = map {
        $_ => (_guard_condition_expr($rule_dt{$_}{dte_guard}) // '1')
    } keys %rule_dt;
    # Keep actual producer inputs before successive resources combine the DT
    # header. This private provenance is not itself an exclusion proof.
    my %requests = map {
        $_ => {
            container_name => $rule_dt{$_}{name},
            source_owner   => _clone_provenance_value($rule_dt{$_}{source_owner}),
            guard          => _clone_provenance_value($rule_dt{$_}{dte_guard}),
            condition      => $original_guard{$_},
        }
    } keys %rule_dt;
    my @activation_steps;
    my $model = _build_rule_priority_model($actor);
    my @grants;
    my %round_robin_user_resource;

    for my $resource (@resources) {
        my @users = @{$resource->{users} || []};
        next unless @users;

        my $resource_name = $resource->{name} // '<unnamed>';
        my $kind = $resource->{kind} // '';
        my $arbiter = $resource->{arbiter} // '';

        if ($arbiter eq 'priority') {
            _resource_arbitration_error(
                'isf_resource_unsupported_kind',
                $resource_name,
                "resource kind '$kind' is not enforced yet",
            ) unless _resource_kind_supports_priority_rule_users($kind);
        } elsif ($arbiter eq 'round_robin') {
            if (!_resource_kind_supports_round_robin_rule_users($kind)) {
                my $code = _resource_kind_supports_priority_rule_users($kind)
                    ? 'isf_resource_unsupported_arbiter'
                    : 'isf_resource_unsupported_kind';
                my $reason = $code eq 'isf_resource_unsupported_arbiter'
                    ? "arbiter '$arbiter' is not enforced yet for $kind resources"
                    : "resource kind '$kind' is not enforced yet";
                _resource_arbitration_error($code, $resource_name, $reason);
            }
        } else {
            _resource_arbitration_error(
                'isf_resource_unsupported_arbiter',
                $resource_name,
                "arbiter '$arbiter' is not enforced yet for $kind resources",
            );
        }

        for my $user (@users) {
            _resource_arbitration_error(
                'isf_resource_unknown_user',
                $resource_name,
                "user '$user' is not a lowered rule",
            ) unless $rule_dt{$user};
        }

        _validate_transaction_start_resource(
            $resource,
            \@users,
            $actor,
            \%transactions,
            \%generated_children,
        ) if $kind eq 'transaction_start';

        my @members = @{$resource->{members} || []};
        _validate_output_bundle_member_coverage(
            $resource,
            \@users,
            \%rule_dt,
            \%output_bundle_member_targets,
        ) if $kind eq 'output_bundle' && @members;
        _validate_storage_port_member_coverage(
            $resource,
            \@users,
            \%rule_dt,
            \%storage_port_member_targets,
        ) if $kind eq 'storage_port';

        if ($arbiter eq 'round_robin') {
            push @grants, _apply_round_robin_rule_user_resource_grants(
                $ir,
                $resource,
                \@users,
                \%rule_dt,
                \%original_guard,
                \%round_robin_user_resource,
                \@activation_steps,
            );
            next;
        }

        for my $left_idx (0 .. $#users) {
            my $left = $users[$left_idx];
            for my $right_idx ($left_idx + 1 .. $#users) {
                my $right = $users[$right_idx];
                my $left_over_right = _priority_dominates($model, $left, $right);
                my $right_over_left = _priority_dominates($model, $right, $left);

                if ($left_over_right && $right_over_left) {
                    _resource_arbitration_error(
                        'isf_resource_priority_cycle',
                        $resource_name,
                        "priority cycle leaves no unique winner between '$left' and '$right'",
                    );
                }

                if (!$left_over_right && !$right_over_left) {
                    _resource_arbitration_error(
                        'isf_resource_priority_incomplete',
                        $resource_name,
                        "priority arbiter needs an ordering between '$left' and '$right'",
                    );
                }
            }
        }

        for my $user (@users) {
            my @higher = sort grep {
                $_ ne $user && _priority_dominates($model, $_, $user)
            } @users;
            my $dt = $rule_dt{$user};
            my @higher_conditions = map { $original_guard{$_} // '1' } @higher;
            my $before_guard = _clone_provenance_value($dt->{dte_guard});

            push @grants, {
                resource => $resource_name,
                kind     => $kind,
                arbiter  => $arbiter,
                user     => $user,
                higher   => [@higher],
                members  => [@members],
            };
            push @{$dt->{resource_grants}}, {
                resource => $resource_name,
                higher   => [@higher],
            };

            if (@higher) {
                $dt->{dte_guard} = _combine_rule_dte_with_resource_suppressors(
                    $dt->{dte_guard},
                    \@higher_conditions,
                );
                _mark_rule_assignments_resource_suppressed($dt, \@higher);
            }
            push @activation_steps, {
                resource       => $resource_name,
                user           => $user,
                container_name => $dt->{name},
                arbiter        => $arbiter,
                before_guard   => $before_guard,
                after_guard    => _clone_provenance_value($dt->{dte_guard}),
                suppressors    => [map {
                    {user => $higher[$_], condition => $higher_conditions[$_]}
                } 0 .. $#higher],
            };
        }
    }

    $ir->{resource_activation} = { requests => \%requests, steps => \@activation_steps };
    return { grants => \@grants, issues => [] };
}

sub _resource_kind_supports_priority_rule_users {
    my ($kind) = @_;
    return defined($kind)
        && ($kind eq 'rule_slot'
            || $kind eq 'output_bundle'
            || $kind eq 'transaction_start'
            || $kind eq 'storage_port');
}

sub _resource_kind_supports_round_robin_rule_users {
    my ($kind) = @_;
    return defined($kind)
        && ($kind eq 'rule_slot'
            || $kind eq 'output_bundle'
            || $kind eq 'transaction_start'
            || $kind eq 'storage_port');
}

sub _apply_round_robin_rule_user_resource_grants {
    my ($ir, $resource, $users, $rule_dt, $original_guard, $round_robin_user_resource, $activation_steps) = @_;
    my $resource_name = $resource->{name} // '<unnamed>';
    my @users = @$users;

    my $declaration = _validate_round_robin_rule_user_resource(
        $ir, $resource_name, \@users, $round_robin_user_resource);
    my $pointer = $declaration->{name};
    _register_counter_width($ir->{counters}, $pointer, $declaration->{width});
    $ir->{storage_roles}{$pointer} = $declaration->{storage_role}
        if ref($ir->{storage_roles}) eq 'HASH';

    my @grants;
    for my $idx (0 .. $#users) {
        my $user = $users[$idx];
        my $dt = $rule_dt->{$user};
        my @peers = grep { $_ ne $user } @users;
        my $permission = _round_robin_rule_user_permission_expr(
            $pointer,
            \@users,
            $idx,
            $original_guard,
        );
        my $next_pointer = ($idx + 1) % @users;

        push @grants, {
            resource => $resource_name,
            kind     => $resource->{kind} // '',
            arbiter  => 'round_robin',
            user     => $user,
            higher   => [@peers],
            members  => [@{$resource->{members} || []}],
        };
        push @{$dt->{resource_grants}}, {
            resource => $resource_name,
            higher   => [@peers],
        };

        my $before_guard = _clone_provenance_value($dt->{dte_guard});
        $dt->{dte_guard} = _combine_rule_dte_with_required_condition(
            $dt->{dte_guard},
            $permission,
        );
        _mark_rule_assignments_resource_suppressed($dt, \@peers);
        my $assignment_index = scalar @{$dt->{assignments}};
        push @{$dt->{assignments}}, {
            lhs                    => $pointer,
            rhs                    => $next_pointer,
            op                     => '<-',
            source_kind            => 'resource_round_robin_pointer',
            resource_suppressed_by => [@peers],
        };
        push @$activation_steps, {
            resource       => $resource_name,
            user           => $user,
            container_name => $dt->{name},
            arbiter        => 'round_robin',
            before_guard   => $before_guard,
            after_guard    => _clone_provenance_value($dt->{dte_guard}),
            round_robin    => {
                permission          => $permission,
                pointer_declaration => _clone_provenance_value($declaration),
                user_index          => $idx,
                next_pointer        => $next_pointer,
                assignment_index    => $assignment_index,
            },
        };
    }

    return @grants;
}

sub _validate_round_robin_rule_user_resource {
    my ($ir, $resource_name, $users, $round_robin_user_resource) = @_;
    my $declaration = _round_robin_pointer_declaration($resource_name, $users);

    for my $user (@$users) {
        my $previous = $round_robin_user_resource->{$user};
        _resource_arbitration_error(
            'isf_resource_round_robin_user_overlap',
            $resource_name,
            "rule user '$user' is already bound to round_robin resource '$previous'",
        ) if defined($previous) && $previous ne $resource_name;
        $round_robin_user_resource->{$user} = $resource_name;
    }

    my $pointer = $declaration->{name};
    my %reserved = _ir_reserved_signal_names($ir);
    _resource_arbitration_error(
        'isf_resource_round_robin_pointer_collision',
        $resource_name,
        "generated round_robin pointer '$pointer' collides with an existing actor symbol",
    ) if $reserved{$pointer};

    return $declaration;
}

sub _round_robin_pointer_declaration {
    my ($resource_name, $users) = @_;
    _resource_arbitration_error(
        'isf_resource_round_robin_name_shape',
        $resource_name,
        "round_robin resource names must be HDL identifiers because FSMGen generates pointer storage from the resource name",
    ) unless _is_hdl_identifier($resource_name);
    return {
        name => _round_robin_pointer_name($resource_name),
        width => _repeat_count_width_for_integer($#$users),
        storage_role => 'resource_round_robin_pointer',
    };
}

sub _round_robin_pointer_name {
    my ($resource_name) = @_;
    return "isf_rr_${resource_name}_turn";
}

sub _ir_reserved_signal_names {
    my ($ir) = @_;
    my %reserved;
    $reserved{$_->{name}} = 1 for @{$ir->{ports} || []};
    for my $entry (@{$ir->{constants} || []}, @{$ir->{params} || []}) {
        $reserved{$entry->{name}} = 1
            if ref($entry) eq 'HASH' && defined($entry->{name}) && !ref($entry->{name});
    }
    $reserved{$_} = 1 for keys %{$ir->{counters} || {}};
    for my $storage (@{$ir->{declared_storage} || []}) {
        for my $signal (@{$storage->{signals} || []}) {
            $reserved{$signal->{name}} = 1
                if defined($signal->{name}) && !ref($signal->{name});
        }
    }
    return %reserved;
}

sub _round_robin_rule_user_permission_expr {
    my ($pointer, $users, $winner_idx, $original_guard) = @_;
    my @users = @$users;
    my @terms;

    for my $start_idx (0 .. $#users) {
        my @parts = ("(== $pointer $start_idx)");
        for my $blocker_idx (_round_robin_indices_before_winner($start_idx, $winner_idx, scalar(@users))) {
            my $blocker = $users[$blocker_idx];
            push @parts, _expr_not($original_guard->{$blocker} // '1');
        }
        push @terms, _expr_and(@parts);
    }

    return _expr_or(@terms);
}

sub _round_robin_indices_before_winner {
    my ($start_idx, $winner_idx, $count) = @_;
    return () if $start_idx == $winner_idx;

    my @indices;
    my $idx = $start_idx;
    while ($idx != $winner_idx) {
        push @indices, $idx;
        $idx = ($idx + 1) % $count;
    }
    return @indices;
}

sub _validate_transaction_start_resource {
    my ($resource, $users, $actor, $transactions, $generated_children) = @_;
    my $resource_name = $resource->{name} // '<unnamed>';

    _resource_arbitration_error(
        'isf_transaction_start_unknown_transaction',
        $resource_name,
        "transaction_start resource '$resource_name' is not a declared local transaction",
    ) unless $transactions->{$resource_name};

    _resource_arbitration_error(
        'isf_transaction_start_generated_child_unsupported',
        $resource_name,
        "transaction_start resource '$resource_name' targets a generated-child transaction start, which is not enforced yet",
    ) if $generated_children->{$resource_name};

    my %rules = map { $_->{name} => $_ } @{$actor->{rules} || []};
    for my $user (@$users) {
        _resource_arbitration_error(
            'isf_transaction_start_user_without_trigger',
            $resource_name,
            "rule user '$user' does not trigger transaction_start resource '$resource_name'",
        ) unless _rule_triggers_local_transaction($rules{$user}, $resource_name);
    }

    return 1;
}

sub _rule_triggers_local_transaction {
    my ($rule, $transaction) = @_;
    return 0 unless ref($rule) eq 'HASH';
    for my $action (@{$rule->{actions} || []}) {
        next unless ref($action) eq 'ARRAY'
            && @$action >= 2
            && defined($action->[0])
            && !ref($action->[0])
            && $action->[0] eq 'trigger';
        return 1 if defined($action->[1])
            && !ref($action->[1])
            && $action->[1] eq $transaction;
    }
    return 0;
}

sub _validate_output_bundle_member_coverage {
    my ($resource, $users, $rule_dt, $actor_member_targets) = @_;
    my $resource_name = $resource->{name} // '<unnamed>';
    my @members = @{$resource->{members} || []};
    my %members = map { $_ => 1 } @members;
    my %written_members;

    for my $user (@$users) {
        my $dt = $rule_dt->{$user} || next;
        for my $assignment (@{$dt->{assignments} || []}) {
            my $target = $assignment->{lhs};
            next unless defined($target) && length($target);
            next unless $actor_member_targets->{$target};
            _resource_arbitration_error(
                'isf_output_bundle_member_mismatch',
                $resource_name,
                "rule user '$user' writes declared output/storage member '$target' outside explicit output_bundle members",
            ) unless $members{$target};
            $written_members{$target} = 1;
        }
    }

    for my $member (@members) {
        _resource_arbitration_error(
            'isf_output_bundle_member_unwritten',
            $resource_name,
            "explicit output_bundle member '$member' is not written by any bound rule user",
        ) unless $written_members{$member};
    }

    return 1;
}

sub _validate_storage_port_member_coverage {
    my ($resource, $users, $rule_dt, $storage_member_targets) = @_;
    my $resource_name = $resource->{name} // '<unnamed>';
    my @members = @{$resource->{members} || []};

    _resource_arbitration_error(
        'isf_storage_port_members_required',
        $resource_name,
        "storage_port resource '$resource_name' requires explicit storage members",
    ) unless @members;

    my %members = map { $_ => 1 } @members;
    my %written_members;

    for my $user (@$users) {
        my $dt = $rule_dt->{$user} || next;
        for my $assignment (@{$dt->{assignments} || []}) {
            my $target = $assignment->{lhs};
            next unless defined($target) && length($target);
            next unless $storage_member_targets->{$target};
            _resource_arbitration_error(
                'isf_storage_port_member_mismatch',
                $resource_name,
                "rule user '$user' writes storage member '$target' outside explicit storage_port members",
            ) unless $members{$target};
            $written_members{$target} = 1;
        }
    }

    for my $member (@members) {
        _resource_arbitration_error(
            'isf_storage_port_member_unwritten',
            $resource_name,
            "explicit storage_port member '$member' is not written by any bound rule user",
        ) unless $written_members{$member};
    }

    return 1;
}

sub _combine_rule_dte_with_resource_suppressors {
    my ($guard, $suppressor_conditions) = @_;
    my @terms;
    my $existing = _guard_condition_expr($guard);
    push @terms, $existing if defined($existing) && $existing ne '1';

    my @conditions = grep { defined($_) && length($_) } @$suppressor_conditions;
    if (@conditions == 1) {
        push @terms, "(! $conditions[0])";
    } elsif (@conditions > 1) {
        push @terms, '(! (| ' . join(' ', @conditions) . '))';
    }

    return { port => '1' } unless @terms;
    return { expr => $terms[0] } if @terms == 1;
    return { expr => '(& ' . join(' ', @terms) . ')' };
}

sub _combine_rule_dte_with_required_condition {
    my ($guard, $required_condition) = @_;
    my @terms;
    my $existing = _guard_condition_expr($guard);
    push @terms, $existing if defined($existing) && $existing ne '1';
    push @terms, $required_condition
        if defined($required_condition)
            && length($required_condition)
            && $required_condition ne '1';

    return { port => '1' } unless @terms;
    return { expr => $terms[0] } if @terms == 1;
    return { expr => _expr_and(@terms) };
}

sub _expr_and {
    my @terms = grep { defined($_) && length($_) } @_;
    return '0' if grep { $_ eq '0' } @terms;
    @terms = grep { $_ ne '1' } @terms;
    return '1' unless @terms;
    return $terms[0] if @terms == 1;
    return '(& ' . join(' ', @terms) . ')';
}

sub _expr_or {
    my @terms = grep { defined($_) && length($_) } @_;
    return '1' if grep { $_ eq '1' } @terms;
    @terms = grep { $_ ne '0' } @terms;
    return '0' unless @terms;
    return $terms[0] if @terms == 1;
    return '(| ' . join(' ', @terms) . ')';
}

sub _expr_not {
    my ($term) = @_;
    return '0' if !defined($term) || !length($term) || $term eq '1';
    return '1' if $term eq '0';
    return "(! $term)";
}

sub _mark_rule_assignments_resource_suppressed {
    my ($dt, $higher_rules) = @_;
    for my $assignment (@{$dt->{assignments} || []}) {
        my %seen = map { $_ => 1 } @{$assignment->{resource_suppressed_by} || []};
        for my $higher (@$higher_rules) {
            next if $seen{$higher}++;
            push @{$assignment->{resource_suppressed_by}}, $higher;
        }
    }
}

sub _resource_arbitration_error {
    my ($code, $resource_name, $reason) = @_;
    confess "ISF resource arbitration '$code' on resource '$resource_name': $reason\n";
}

sub _apply_rule_priority_resolution {
    my ($ir, $actor) = @_;
    my $model = _build_rule_priority_model($actor);
    my @records = _rule_data_assignment_refs($ir);
    my %by_target;
    my @issues;
    my @resolutions;

    for my $record (@records) {
        push @{$by_target{$record->{target}}}, $record;
    }

    for my $target (sort keys %by_target) {
        my $target_records = $by_target{$target};
        next unless @$target_records > 1;

        for my $left_idx (0 .. $#$target_records) {
            my $left = $target_records->[$left_idx];
            for my $right_idx ($left_idx + 1 .. $#$target_records) {
                my $right = $target_records->[$right_idx];
                next if _rule_assignment_pair_compatible($left, $right);
                next if _condition_terms_prove_disjoint($left, $right);

                if (($left->{operator} // '') ne ($right->{operator} // '')) {
                    push @issues, _priority_conflict_issue(
                        code         => 'isf_priority_mixed_timing_conflict',
                        proof_status => 'mixed_timing',
                        target       => $target,
                        reason       => 'priority cannot resolve mixed timing operators',
                        left         => $left,
                        right        => $right,
                    );
                    next;
                }

                my $left_over_right = _priority_dominates($model, $left->{rule}, $right->{rule});
                my $right_over_left = _priority_dominates($model, $right->{rule}, $left->{rule});

                if ($left_over_right && $right_over_left) {
                    push @issues, _priority_conflict_issue(
                        code         => 'isf_priority_cycle_conflict',
                        proof_status => 'priority_cycle',
                        target       => $target,
                        reason       => 'priority cycle leaves no unique winner',
                        left         => $left,
                        right        => $right,
                    );
                    next;
                }

                if ($left_over_right) {
                    _suppress_priority_assignment($right, $left, \@resolutions);
                } elsif ($right_over_left) {
                    _suppress_priority_assignment($left, $right, \@resolutions);
                }
            }
        }
    }

    _apply_rule_assignment_suppressions(\@records);

    return {
        resolutions => \@resolutions,
        issues      => \@issues,
    };
}

sub _apply_rule_transaction_priority_resolution {
    my ($ir, $actor) = @_;
    my $model = _build_owner_priority_model($actor);
    my @records = (
        _rule_data_assignment_refs($ir),
        _transaction_data_assignment_refs($ir),
        _drive_data_assignment_refs($ir),
    );
    my %by_target;
    my %ambiguous_issue_seen;
    my @issues;
    my @resolutions;

    for my $record (@records) {
        push @{$by_target{$record->{target}}}, $record;
    }

    for my $target (sort keys %by_target) {
        my $target_records = $by_target{$target};
        next unless @$target_records > 1;

        for my $left_idx (0 .. $#$target_records) {
            my $left = $target_records->[$left_idx];
            for my $right_idx ($left_idx + 1 .. $#$target_records) {
                my $right = $target_records->[$right_idx];
                next if _rule_assignment_pair_compatible($left, $right);

                if (_owner_kind_pair($left, $right, 'rule', 'drive')) {
                    my ($rule_record, $drive_record) = ($left->{owner_kind} // '') eq 'rule'
                        ? ($left, $right)
                        : ($right, $left);
                    next unless _ambiguous_drive_priority_is_declared(
                        $model,
                        $rule_record,
                        $drive_record,
                    );

                    my $issue_key = join "\0",
                        $target,
                        _priority_record_owner($rule_record),
                        $drive_record->{drive} // _priority_record_owner($drive_record);
                    next if $ambiguous_issue_seen{$issue_key}++;
                    push @issues, _ambiguous_rule_drive_priority_issue(
                        $target,
                        $rule_record,
                        $drive_record,
                    );
                    next;
                }

                next unless _owner_kind_pair($left, $right, 'rule', 'transaction');

                if (($left->{operator} // '') ne ($right->{operator} // '')) {
                    push @issues, _priority_conflict_issue(
                        code         => 'isf_priority_mixed_timing_conflict',
                        proof_status => 'mixed_timing',
                        target       => $target,
                        reason       => 'priority cannot resolve mixed timing operators',
                        left         => $left,
                        right        => $right,
                    );
                    next;
                }

                my $left_owner = _priority_record_owner($left);
                my $right_owner = _priority_record_owner($right);
                my $left_over_right = _priority_dominates($model, $left_owner, $right_owner);
                my $right_over_left = _priority_dominates($model, $right_owner, $left_owner);

                if ($left_over_right && $right_over_left) {
                    push @issues, _priority_conflict_issue(
                        code         => 'isf_priority_cycle_conflict',
                        proof_status => 'priority_cycle',
                        target       => $target,
                        reason       => 'priority cycle leaves no unique winner',
                        left         => $left,
                        right        => $right,
                    );
                    next;
                }

                if (!$left_over_right && !$right_over_left) {
                    push @issues, _priority_conflict_issue(
                        code         => 'isf_conflicting_rule_transaction_writes',
                        proof_status => 'proved_conflict',
                        target       => $target,
                        reason       => 'overlapping rule/transaction data writes need actor-level priority',
                        left         => $left,
                        right        => $right,
                    );
                    next;
                }

                my ($winner, $loser) = $left_over_right ? ($left, $right) : ($right, $left);
                _suppress_priority_assignment($loser, $winner, \@resolutions);
            }
        }
    }

    _apply_rule_assignment_suppressions(\@records);

    return {
        resolutions => \@resolutions,
        issues      => \@issues,
    };
}

sub _merge_priority_resolution {
    my @results = @_;
    my @resolutions;
    my @issues;

    for my $result (@results) {
        next unless ref($result) eq 'HASH';
        push @resolutions, @{$result->{resolutions} || []};
        push @issues, @{$result->{issues} || []};
    }

    return {
        resolutions => \@resolutions,
        issues      => \@issues,
    };
}

sub _build_rule_priority_model {
    my ($actor) = @_;
    my %rules = map { $_->{name} => 1 } @{$actor->{rules} || []};
    my %edges;

    for my $priority (@{$actor->{priorities} || []}) {
        my ($higher, undef, $lower) = @$priority;
        next unless $rules{$higher} && $rules{$lower};
        $edges{$higher}{$lower} = 1;
    }

    for my $rule (@{$actor->{rules} || []}) {
        my $higher = $rule->{name};
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY'
                && defined($action->[0])
                && !ref($action->[0])
                && $action->[0] eq 'priority';
            my $lower = $action->[2];
            next unless $rules{$higher} && $rules{$lower};
            $edges{$higher}{$lower} = 1;
        }
    }

    return { edges => \%edges };
}

sub _build_owner_priority_model {
    my ($actor) = @_;
    my %owners = (
        map({ $_->{name} => 1 } @{$actor->{rules} || []}),
        map({ $_->{name} => 1 } @{$actor->{transactions} || []}),
    );
    my %rules = map { $_->{name} => 1 } @{$actor->{rules} || []};
    my %edges;

    for my $priority (@{$actor->{priorities} || []}) {
        my ($higher, undef, $lower) = @$priority;
        next unless $owners{$higher} && $owners{$lower};
        $edges{$higher}{$lower} = 1;
    }

    for my $rule (@{$actor->{rules} || []}) {
        my $higher = $rule->{name};
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY'
                && defined($action->[0])
                && !ref($action->[0])
                && $action->[0] eq 'priority';
            my $lower = $action->[2];
            next unless $rules{$higher} && $rules{$lower};
            $edges{$higher}{$lower} = 1;
        }
    }

    return { edges => \%edges };
}

sub _rule_data_assignment_refs {
    my ($ir) = @_;
    my @records;

    for my $dt (@{$ir->{dt_blocks} || []}) {
        next unless ($dt->{kind} // '') eq 'rule';
        my $assignment_index = 0;
        my $rule_condition = _guard_condition_expr($dt->{dte_guard}) // '1';
        my $rule_condition_terms = $dt->{dte_guard_terms};
        for my $assignment (@{$dt->{assignments} || []}) {
            if (($assignment->{source_kind} // '') eq 'rule_action' && defined $assignment->{lhs}) {
                my $activation_condition = _combine_condition_exprs(
                    $rule_condition,
                    _guard_condition_expr($assignment->{guard}),
                );
                push @records, {
                    rule             => $dt->{name},
                    owner            => $dt->{name},
                    owner_kind       => 'rule',
                    source_kind      => 'rule_action',
                    target           => $assignment->{lhs},
                    operator         => $assignment->{op},
                    rhs              => $assignment->{rhs},
                    assignment       => $assignment,
                    rule_condition   => $activation_condition,
                    owner_condition  => $activation_condition,
                    condition_terms   => $rule_condition_terms,
                    assignment_index => $assignment_index,
                };
            }
            $assignment_index++;
        }
    }

    return @records;
}

sub _transaction_data_assignment_refs {
    my ($ir) = @_;
    my @records;

    for my $state (@{$ir->{states} || []}) {
        my $transaction = _transaction_owner_from_state_name($state->{name});
        next unless defined($transaction) && length($transaction);

        my $assignment_index = 0;
        for my $assignment (@{$state->{assignments} || []}) {
            my $current_index = $assignment_index++;
            my $source_kind = _state_assignment_source_kind($state, $assignment);
            next unless _assignment_domain_hint($assignment, $source_kind) eq 'data';
            next unless defined $assignment->{lhs};

            push @records, {
                transaction      => $transaction,
                owner            => $transaction,
                owner_kind       => 'transaction',
                source_kind      => $source_kind,
                target           => $assignment->{lhs},
                operator         => $assignment->{op},
                rhs              => $assignment->{rhs},
                assignment       => $assignment,
                state            => $state->{name},
                state_kind       => $state->{kind},
                owner_condition  => _combine_condition_exprs(
                    _state_active_condition_expr($state->{name}),
                    _guard_condition_expr($assignment->{guard}) // '1',
                ),
                assignment_index => $current_index,
            };
        }
    }

    for my $dt (@{$ir->{dt_blocks} || []}) {
        next unless ($dt->{kind} // '') eq 'spawn_port_binding';
        next unless (_dt_assignment_owner_kind($dt) // '') eq 'transaction';

        my $assignment_index = 0;
        for my $assignment (@{$dt->{assignments} || []}) {
            my $current_index = $assignment_index++;
            my $source_kind = _dt_assignment_source_kind($dt, $assignment);
            next unless _assignment_domain_hint($assignment, $source_kind) eq 'data';
            next unless defined $assignment->{lhs};

            push @records, {
                transaction      => _dt_assignment_owner($dt),
                owner            => _dt_assignment_owner($dt),
                owner_kind       => 'transaction',
                source_kind      => $source_kind,
                target           => $assignment->{lhs},
                operator         => $assignment->{op},
                rhs              => $assignment->{rhs},
                assignment       => $assignment,
                state            => $dt->{name},
                state_kind       => $dt->{kind},
                owner_condition  => _combine_condition_exprs(
                    _guard_condition_expr($dt->{dte_guard}) // '1',
                    _guard_condition_expr($assignment->{guard}) // '1',
                ),
                assignment_index => $current_index,
            };
        }
    }

    return @records;
}

sub _drive_data_assignment_refs {
    my ($ir) = @_;
    my @records;

    for my $dt (@{$ir->{dt_blocks} || []}) {
        next unless ($dt->{kind} // '') eq 'drive';

        my @local_callers = @{$dt->{local_transaction_callers} || []};
        my @generated_sources = @{$dt->{generated_call_sources} || []};
        my $has_unique_local_owner = @local_callers == 1 && !@generated_sources;
        my $assignment_index = 0;

        for my $assignment (@{$dt->{assignments} || []}) {
            my $current_index = $assignment_index++;
            my $source_kind = _dt_assignment_source_kind($dt, $assignment);
            next unless _assignment_domain_hint($assignment, $source_kind) eq 'data';
            next unless defined $assignment->{lhs};

            my $logical_owner = $has_unique_local_owner ? $local_callers[0] : $dt->{name};
            push @records, {
                transaction              => $has_unique_local_owner ? $local_callers[0] : undef,
                owner                    => $logical_owner,
                owner_kind               => $has_unique_local_owner ? 'transaction' : 'drive',
                drive                    => $dt->{name},
                source_kind              => $source_kind,
                target                   => $assignment->{lhs},
                operator                 => $assignment->{op},
                rhs                      => $assignment->{rhs},
                assignment               => $assignment,
                state                    => $dt->{name},
                state_kind               => $dt->{kind},
                owner_condition          => _combine_condition_exprs(
                    _guard_condition_expr($dt->{dte_guard}) // '1',
                    _guard_condition_expr($assignment->{guard}) // '1',
                ),
                local_transaction_callers => [@local_callers],
                generated_call_sources    => [map { _clone_provenance_value($_) } @generated_sources],
                assignment_index          => $current_index,
            };
        }
    }

    return @records;
}

sub _ambiguous_drive_priority_is_declared {
    my ($model, $rule_record, $drive_record) = @_;
    my $rule = _priority_record_owner($rule_record);

    for my $candidate (_ambiguous_drive_priority_candidates($drive_record)) {
        return 1 if _priority_dominates($model, $rule, $candidate);
        return 1 if _priority_dominates($model, $candidate, $rule);
    }

    return 0;
}

sub _ambiguous_drive_priority_candidates {
    my ($record) = @_;
    my %candidates = map { $_ => 1 } @{$record->{local_transaction_callers} || []};
    for my $source (@{$record->{generated_call_sources} || []}) {
        next unless ref($source) eq 'HASH';
        my $transaction = $source->{child_transaction};
        $candidates{$transaction} = 1
            if defined($transaction) && !ref($transaction) && length($transaction);
    }
    return sort keys %candidates;
}

sub _ambiguous_rule_drive_priority_issue {
    my ($target, $rule_record, $drive_record) = @_;
    my $rule = _priority_record_owner($rule_record);
    my $drive = $drive_record->{drive} // _priority_record_owner($drive_record);
    my @local_callers = @{$drive_record->{local_transaction_callers} || []};
    my @generated_sources = @{$drive_record->{generated_call_sources} || []};
    my @generated_descriptors = map {
        _format_generated_drive_source_descriptor($_)
    } @generated_sources;
    my @candidate_transactions = _ambiguous_drive_priority_candidates($drive_record);
    my $ambiguity_class = _drive_priority_ambiguity_class(\@local_callers, \@generated_sources);
    my $reason = "actor priority between rule '$rule' and drive '$drive' has ambiguous drive caller ownership"
        . "; ambiguity_class=$ambiguity_class"
        . '; local_callers=[' . _format_diagnostic_list(@local_callers) . ']'
        . '; generated_sources=[' . _format_diagnostic_list(@generated_descriptors) . ']'
        . '; candidate_transactions=[' . _format_diagnostic_list(@candidate_transactions) . ']';

    return _priority_conflict_issue(
        code         => 'isf_ambiguous_rule_transaction_drive_priority',
        proof_status => 'ambiguous_drive_caller',
        target       => $target,
        reason       => $reason,
        left         => $rule_record,
        right        => $drive_record,
    );
}

sub _drive_priority_ambiguity_class {
    my ($local_callers, $generated_sources) = @_;
    my $local_count = @{$local_callers || []};
    my $generated_count = @{$generated_sources || []};
    return 'multiple_local_and_generated_sources' if $local_count > 1 && $generated_count;
    return 'mixed_local_and_generated_sources' if $local_count == 1 && $generated_count;
    return 'multiple_local_callers' if $local_count > 1;
    return 'generated_sources' if $generated_count;
    return 'unused_drive';
}

sub _format_generated_drive_source_descriptor {
    my ($source) = @_;
    return '' unless ref($source) eq 'HASH';
    return join ',', map {
        $_ . '=' . ($source->{$_} // '')
    } qw(source_kind activation_kind child_transaction instance owner_kind owner prefix);
}

sub _format_diagnostic_list {
    return 'none' unless @_;
    return join ', ', @_;
}

sub _state_active_condition_expr {
    my ($state_name) = @_;
    return undef unless defined($state_name) && length($state_name);
    return "(state_active $state_name)";
}

sub _rule_assignment_pair_compatible {
    my ($left, $right) = @_;
    return ($left->{operator} // '') eq ($right->{operator} // '')
        && _priority_record_rhs($left) eq _priority_record_rhs($right);
}

sub _priority_record_rhs {
    my ($record) = @_;
    return defined($record->{rhs}) ? "$record->{rhs}" : '';
}

sub _priority_dominates {
    my ($model, $higher, $lower) = @_;
    return 0 unless defined($higher) && defined($lower) && length($higher) && length($lower);
    return _priority_dominates_walk($model->{edges} || {}, $higher, $lower, {});
}

sub _priority_dominates_walk {
    my ($edges, $current, $target, $seen) = @_;
    my $next_edges = $edges->{$current} || {};
    return 1 if $next_edges->{$target};
    return 0 if $seen->{$current}++;

    for my $next (sort keys %$next_edges) {
        return 1 if _priority_dominates_walk($edges, $next, $target, $seen);
    }

    return 0;
}

sub _suppress_priority_assignment {
    my ($lower, $higher, $resolutions) = @_;
    my $higher_owner = _priority_record_owner($higher);
    my $lower_owner = _priority_record_owner($lower);
    # One owner can contribute distinct state or drive predicates to this target.
    # Preserve every conflicting writer instead of replacing the earlier one.
    $lower->{suppressed_by}{$higher_owner}{_priority_record_condition($higher)} = 1;
    push @$resolutions, {
        target      => $lower->{target},
        winner      => $higher_owner,
        winner_kind => $higher->{owner_kind} // 'rule',
        loser       => $lower_owner,
        loser_kind  => $lower->{owner_kind} // 'rule',
    };
}

sub _apply_rule_assignment_suppressions {
    my ($records) = @_;

    for my $record (@$records) {
        my $suppressed_by = $record->{suppressed_by} || {};
        my @higher_rules = sort keys %$suppressed_by;
        next unless @higher_rules;

        my $assignment = $record->{assignment};
        my %merged = map { $_ => 1 } @{$assignment->{priority_suppressed_by} || []};
        $merged{$_} = 1 for @higher_rules;
        $assignment->{priority_suppressed_by} = [sort keys %merged];
        $assignment->{guard} = _combine_assignment_guard_with_priority_suppressors(
            $assignment->{guard},
            [ map { _expr_or(sort keys %{$suppressed_by->{$_}}) } @higher_rules ],
        );
    }
}

sub _priority_record_owner {
    my ($record) = @_;
    return $record->{owner} if defined($record->{owner}) && length($record->{owner});
    return $record->{rule} if defined($record->{rule}) && length($record->{rule});
    return $record->{transaction} if defined($record->{transaction}) && length($record->{transaction});
    return '';
}

sub _priority_record_condition {
    my ($record) = @_;
    return $record->{owner_condition}
        if defined($record->{owner_condition}) && length($record->{owner_condition});
    return $record->{rule_condition}
        if defined($record->{rule_condition}) && length($record->{rule_condition});
    return '1';
}

sub _combine_assignment_guard_with_priority_suppressors {
    my ($guard, $suppressor_conditions) = @_;
    my @terms;
    my $existing = _guard_condition_expr($guard);
    push @terms, $existing if defined($existing) && $existing ne '1';
    push @terms, map { _negated_condition_expr($_) } @$suppressor_conditions;

    return undef unless @terms;
    return { expr => $terms[0] } if @terms == 1;
    return { expr => '(& ' . join(' ', @terms) . ')' };
}

sub _combine_condition_exprs {
    my @raw_conditions = grep {
        defined($_) && length($_) && $_ ne '1'
    } @_;

    my @conditions = map { _condition_and_terms($_) } @raw_conditions;
    return '1' unless @conditions;
    return $conditions[0] if @conditions == 1;
    return '(& ' . join(' ', @conditions) . ')';
}

sub _condition_and_terms {
    my ($condition) = @_;
    return () unless defined($condition) && !ref($condition) && length($condition);
    return () if $condition eq '1';

    my @terms = _split_top_level_and_expr($condition);
    return map { _condition_and_terms($_) } @terms
        if @terms > 1 || (@terms == 1 && $terms[0] ne $condition);
    return ($condition);
}

sub _split_top_level_and_expr {
    my ($condition) = @_;
    return ($condition)
        unless defined($condition)
            && !ref($condition)
            && $condition =~ /\A\(&\s+(.+)\)\z/s;

    my $body = $1;
    my @terms;
    my $term = '';
    my $depth = 0;

    for my $idx (0 .. length($body) - 1) {
        my $char = substr($body, $idx, 1);
        if ($char =~ /\s/ && $depth == 0) {
            push @terms, $term if length $term;
            $term = '';
            next;
        }

        $term .= $char;
        if ($char eq '(') {
            $depth++;
        } elsif ($char eq ')') {
            $depth--;
            return ($condition) if $depth < 0;
        }
    }

    return ($condition) if $depth != 0;
    push @terms, $term if length $term;
    return @terms ? @terms : ($condition);
}

sub _guard_condition_expr {
    my ($guard) = @_;
    return undef unless $guard && ref($guard) eq 'HASH';
    return undef if defined($guard->{port}) && $guard->{port} eq '1';
    return $guard->{port} if defined($guard->{port}) && length($guard->{port});
    return $guard->{expr} if defined($guard->{expr}) && length($guard->{expr});
    if (defined($guard->{signal}) && defined($guard->{op})) {
        return "$guard->{signal}$guard->{op}$guard->{value}";
    }
    return undef;
}

sub _guard_literal_terms {
    my ($guard) = @_;
    return _condition_literal_terms($guard->{expr_ast})
        if $guard && ref($guard) eq 'HASH' && exists $guard->{expr_ast};
    my $condition = _guard_condition_expr($guard);
    return {} unless defined($condition);
    return _condition_literal_terms($condition);
}

sub _merge_literal_term_sets {
    my @sets = grep { defined $_ } @_;
    return undef unless @sets;
    return _merge_condition_term_sets(@sets);
}

sub _condition_literal_terms {
    my ($condition) = @_;
    return {} unless defined($condition);

    if (!ref($condition)) {
        return {} if $condition eq '1';
        return { $1 => 0 } if $condition =~ /\A!([A-Za-z_]\w*)\z/;
        return { "eq:$1" => _condition_term_value($3) }
            if $condition =~ /\A([A-Za-z_]\w*(?:\[[^\]]+\])?)(==|=)(.+)\z/
                && defined(_condition_term_value($3));
        return { $condition => 1 } if _is_condition_signal_term($condition);
        return undef;
    }

    return undef unless ref($condition) eq 'ARRAY' && @$condition;
    my $head = $condition->[0];
    return undef unless defined($head) && !ref($head);

    if ($head eq '&') {
        return _merge_condition_term_sets(
            grep { defined $_ }
            map { _condition_literal_terms($_) } @{$condition}[1 .. $#$condition]
        );
    }

    if ($head eq '|') {
        my @alternatives;
        for my $operand (@{$condition}[1 .. $#$condition]) {
            my $terms = _condition_literal_terms($operand);
            return undef unless defined $terms;
            push @alternatives, @{_satisfying_term_alternatives($terms)};
        }
        return _terms_from_alternatives(\@alternatives);
    }

    if (($head eq '==' || $head eq '=') && @$condition == 3) {
        my ($signal, $value) = @{$condition}[1, 2];
        return undef unless defined($signal) && !ref($signal) && _is_condition_signal_term($signal);
        my $term_value = _condition_term_value($value);
        return undef unless defined $term_value;
        return { "eq:$signal" => $term_value };
    }

    if (($head eq '!' || $head eq '~') && @$condition == 2) {
        my $operand = $condition->[1];
        return { $operand => 0 }
            if defined($operand) && !ref($operand) && _is_condition_signal_term($operand);
        if (ref($operand) eq 'ARRAY'
            && @$operand >= 2
            && defined($operand->[0])
            && !ref($operand->[0])
            && $operand->[0] eq '|') {
            return _condition_literal_terms([
                '&',
                map { ['!', $_] } @{$operand}[1 .. $#$operand],
            ]);
        }
        if (ref($operand) eq 'ARRAY'
            && @$operand == 2
            && defined($operand->[0])
            && !ref($operand->[0])
            && ($operand->[0] eq '!' || $operand->[0] eq '~')
            && defined($operand->[1])
            && !ref($operand->[1])
            && _is_condition_signal_term($operand->[1])) {
            return { $operand->[1] => 1 };
        }
        return undef;
    }

    return undef;
}

sub _merge_condition_term_sets {
    my @sets = grep { defined $_ } @_;
    return undef unless @sets;

    my @merged_alternatives = ({});
    for my $terms (@sets) {
        next unless ref($terms) eq 'HASH';
        my $alternatives = _satisfying_term_alternatives($terms);
        return { __unsat => 1 } unless @$alternatives;

        my @next;
        for my $left (@merged_alternatives) {
            for my $right (@$alternatives) {
                my $merged = _merge_term_maps($left, $right);
                push @next, $merged if defined $merged;
            }
        }
        return { __unsat => 1 } unless @next;
        @merged_alternatives = @next;
    }

    return _terms_from_alternatives(\@merged_alternatives);
}

sub _merge_term_maps {
    my ($left, $right) = @_;
    my %merged = %{$left || {}};

    for my $signal (sort keys %{$right || {}}) {
        next if $signal eq '__unsat' || $signal eq '__dnf';
        if (exists($merged{$signal})) {
            return undef
                if $signal =~ /\Aeq:/ && $merged{$signal} ne $right->{$signal};
            return undef
                if $signal !~ /\Aeq:/ && $merged{$signal} != $right->{$signal};
        }
        $merged{$signal} = $right->{$signal};
    }

    return \%merged;
}

sub _satisfying_term_alternatives {
    my ($terms) = @_;
    return [] unless ref($terms) eq 'HASH';
    return [] if $terms->{__unsat};
    return $terms->{__dnf} if ref($terms->{__dnf}) eq 'ARRAY';
    return [$terms];
}

sub _terms_from_alternatives {
    my ($alternatives) = @_;
    my @satisfying = grep { ref($_) eq 'HASH' && !$_->{__unsat} } @{$alternatives || []};
    return { __unsat => 1 } unless @satisfying;
    return $satisfying[0] if @satisfying == 1;
    return { __dnf => \@satisfying };
}

sub _condition_term_value {
    my ($value) = @_;
    return undef unless defined($value) && !ref($value);
    $value =~ s/\A\s+|\s+\z//g;
    return undef unless _is_numeric_or_exact_width_literal($value);
    return $value;
}

sub _is_condition_signal_term {
    my ($term) = @_;
    return defined($term)
        && !ref($term)
        && $term =~ /\A[A-Za-z_]\w*(?:\[[^\]]+\])?\z/;
}

sub _condition_terms_prove_disjoint {
    my ($left, $right) = @_;
    my $left_terms = $left->{condition_terms};
    my $right_terms = $right->{condition_terms};

    return 0 unless ref($left_terms) eq 'HASH' && ref($right_terms) eq 'HASH';

    my $left_alternatives = _satisfying_term_alternatives($left_terms);
    my $right_alternatives = _satisfying_term_alternatives($right_terms);
    return 1 unless @$left_alternatives && @$right_alternatives;

    for my $left_terms (@$left_alternatives) {
        for my $right_terms (@$right_alternatives) {
            return 0 unless _term_maps_prove_disjoint($left_terms, $right_terms);
        }
    }

    return 1;
}

sub _term_maps_prove_disjoint {
    my ($left_terms, $right_terms) = @_;
    for my $signal (sort keys %$left_terms) {
        next if $signal eq '__unsat' || $signal eq '__dnf';
        next unless exists $right_terms->{$signal};
        return 1 if $signal =~ /\Aeq:/ && $left_terms->{$signal} ne $right_terms->{$signal};
        return 1 if $signal !~ /\Aeq:/ && $left_terms->{$signal} != $right_terms->{$signal};
    }

    return 0;
}

sub _negated_condition_expr {
    my ($condition) = @_;
    $condition = '1' unless defined($condition) && length($condition);
    return "(! $condition)";
}

sub _priority_conflict_issue {
    my (%args) = @_;
    return {
        code         => $args{code},
        severity     => 'error',
        proof_status => $args{proof_status},
        target       => $args{target},
        domain       => 'data',
        reason       => $args{reason},
        sources      => [
            _priority_source_summary($args{left}),
            _priority_source_summary($args{right}),
        ],
    };
}

sub _priority_source_summary {
    my ($record) = @_;
    return {
        owner            => _priority_record_owner($record),
        owner_kind       => $record->{owner_kind} // 'rule',
        source_kind      => $record->{source_kind} // 'rule_action',
        target           => $record->{target},
        operator         => $record->{operator},
        rhs              => $record->{rhs},
        domain           => 'data',
        assignment_index => $record->{assignment_index},
    };
}

sub _finalize_ir {
    my ($ir) = @_;
    $ir->{priority_resolution} ||= { resolutions => [], issues => [] };
    $ir->{assignment_provenance} = _build_assignment_provenance($ir);
    $ir->{compatible_fanin_groups} = _build_compatible_fanin_groups($ir->{assignment_provenance});
    $ir->{conflict_issues} = [
        @{$ir->{priority_resolution}{issues} || []},
        @{_build_conflict_issues($ir->{assignment_provenance})},
    ];
    _confess_conflict_issues($ir->{conflict_issues});
    return $ir;
}

sub _build_assignment_provenance {
    my ($ir) = @_;
    my @records;

    for my $state (@{$ir->{states} || []}) {
        my $assignment_index = 0;
        for my $assignment (@{$state->{assignments} || []}) {
            push @records, _state_assignment_provenance($state, $assignment, $assignment_index++);
        }
    }

    for my $dt (@{$ir->{dt_blocks} || []}) {
        my $assignment_index = 0;
        for my $assignment (@{$dt->{assignments} || []}) {
            push @records, _dt_assignment_provenance($dt, $assignment, $assignment_index++);
        }
    }

    return \@records;
}

sub _state_assignment_provenance {
    my ($state, $assignment, $assignment_index) = @_;
    my $owner = _transaction_owner_from_state_name($state->{name});
    my $source_kind = _state_assignment_source_kind($state, $assignment);

    return {
        owner            => $owner // $state->{name},
        owner_kind       => defined($owner) ? 'transaction' : 'generated',
        source_kind      => $source_kind,
        target           => $assignment->{lhs},
        operator         => $assignment->{op},
        rhs              => $assignment->{rhs},
        domain           => _assignment_domain_hint($assignment, $source_kind),
        condition_terms   => _guard_literal_terms($assignment->{guard}),
        assignment_index => $assignment_index,
        priority_suppressed_by => _assignment_priority_suppressed_by($assignment),
        resource_suppressed_by => _assignment_resource_suppressed_by($assignment),
        activation       => {
            container_kind   => 'state',
            container_name   => $state->{name},
            state_kind       => $state->{kind},
            state_guard      => _clone_provenance_value($state->{guard}),
            assignment_guard => _clone_provenance_value($assignment->{guard}),
        },
    };
}

sub _dt_assignment_provenance {
    my ($dt, $assignment, $assignment_index) = @_;
    my $source_kind = _dt_assignment_source_kind($dt, $assignment);

    my $record = {
        owner            => _dt_assignment_owner($dt),
        owner_kind       => _dt_assignment_owner_kind($dt),
        source_kind      => $source_kind,
        target           => $assignment->{lhs},
        operator         => $assignment->{op},
        rhs              => $assignment->{rhs},
        domain           => _assignment_domain_hint($assignment, $source_kind),
        condition_terms   => _merge_literal_term_sets(
            (($dt->{kind} // '') eq 'rule' ? $dt->{dte_guard_terms} : _guard_literal_terms($dt->{dte_guard})),
            _guard_literal_terms($assignment->{guard}),
        ),
        assignment_index => $assignment_index,
        priority_suppressed_by => _assignment_priority_suppressed_by($assignment),
        resource_suppressed_by => _assignment_resource_suppressed_by($assignment),
        activation       => {
            container_kind   => 'dt',
            container_name   => $dt->{name},
            dt_kind          => $dt->{kind},
            dte_guard        => _clone_provenance_value($dt->{dte_guard}),
            assignment_guard => _clone_provenance_value($assignment->{guard}),
        },
    };
    $record->{invoking_transactions} = _clone_provenance_value($assignment->{invoking_transactions})
        if ref($assignment->{invoking_transactions}) eq 'ARRAY';
    return $record;
}

sub _transaction_owner_from_state_name {
    my ($name) = @_;
    return undef unless defined $name;
    return $1 if $name =~ /^(.+)_(?:idle|drive|await|done|repeat|sample|max_chk|when|switch|update|set|shift|asm|ext|extract|store|load|do|spawn|phase|stage|contract|wait|while|until)_/;
    return $1 if $name =~ /^(.+)_timeout$/;
    return undef;
}

sub _state_assignment_source_kind {
    my ($state, $assignment) = @_;
    return $assignment->{source_kind} if defined $assignment->{source_kind};

    my $name = $state->{name} // '';
    my $kind = $state->{kind} // '';
    my $target = $assignment->{lhs} // '';
    my $op = $assignment->{op} // '';

    return 'scheduler_can_accept' if $target eq 'can_accept';
    return 'drive_call_start' if $name =~ /_drive_/ && $target =~ /_start\z/ && $op eq '=';
    return 'drive_call_param' if $name =~ /_drive_/ && $op eq '=';
    return 'do_start' if $name =~ /_do_/ && $target =~ /_start\z/;
    return 'spawn_start' if $name =~ /_spawn_/ && $target =~ /_start\z/;
    return 'timeout_pulse' if $name =~ /_timeout\z/ && $op =~ /^<[0-9]+$/;
    return 'timeout_status' if $name =~ /_timeout\z/;
    return 'complete_pulse' if $kind eq 'terminal' && $op =~ /^<[0-9]+$/;
    return 'sample_capture' if $name =~ /_(?:idle|sample)_/ && $op eq '<=';
    return 'extract_capture' if $name =~ /_ext_/ && $op eq '<=';
    return 'latency_counter_init' if $target =~ /_cc\z/ && $op eq '<-';
    return 'latency_increment_request' if $target =~ /_inc\z/ && $op eq '=';
    return 'latency_error' if $target =~ /_lerr\z/;
    return 'repeat_counter' if $name =~ /_repeat_/;
    return 'update' if $name =~ /_update_/;
    return 'set' if $name =~ /_set_/;
    return 'shift' if $name =~ /_shift_/;
    return 'assemble' if $name =~ /_asm_/;
    return 'inline_drive' if $name =~ /_drive_/;
    return 'state_assignment';
}

sub _dt_assignment_source_kind {
    my ($dt, $assignment) = @_;
    return $assignment->{source_kind} if defined $assignment->{source_kind};

    my $kind = $dt->{kind} // '';
    my $target = $assignment->{lhs} // '';
    my $op = $assignment->{op} // '';

    return 'rule_trigger_source'
        if $kind eq 'rule' && $op =~ /^<[0-9]+$/ && $target =~ /^\Q$dt->{name}\E_/;
    return 'rule_action' if $kind eq 'rule';
    return 'rule_trigger_fanin' if $kind eq 'rule_trigger_fanin';
    return 'drive_body' if $kind eq 'drive';
    return 'latency_counter' if $kind eq 'latency_counter';
    return 'contract_monitor' if $kind eq 'temporal_contract_monitor';
    return 'dt_assignment';
}

sub _dt_assignment_owner {
    my ($dt) = @_;
    return $dt->{owner} if defined($dt->{owner}) && length($dt->{owner});
    return $1 if ($dt->{kind} // '') eq 'rule_trigger_fanin' && ($dt->{name} // '') =~ /^(.+)_trigger_fanin\z/;
    return $dt->{name};
}

sub _dt_assignment_owner_kind {
    my ($dt) = @_;
    return $dt->{owner_kind} if defined($dt->{owner_kind}) && length($dt->{owner_kind});
    my $kind = $dt->{kind} // '';
    return 'rule' if $kind eq 'rule';
    return 'drive' if $kind eq 'drive';
    return 'transaction' if $kind eq 'rule_trigger_fanin';
    return 'generated';
}

sub _assignment_domain_hint {
    my ($assignment, $source_kind) = @_;
    my $target = $assignment->{lhs} // '';
    my $op = $assignment->{op} // '';
    my $rhs = defined($assignment->{rhs}) ? "$assignment->{rhs}" : '';

    return 'request' if $source_kind =~ /(?:_start|_fanin)\z/ && $rhs eq '1';
    return 'request' if $target =~ /_start\z/ && $op eq '=' && $rhs eq '1';
    return 'request' if $source_kind eq 'rule_trigger_fanin';
    return 'pulse' if $op =~ /^<[0-9]+$/ && $rhs eq '1';
    return 'capture' if $source_kind =~ /(?:sample|extract)_capture/;
    return 'helper' if $source_kind =~ /^(?:scheduler_|latency_|repeat_|timeout_status|contract_)/;
    return 'data';
}

sub _clone_provenance_value {
    my ($value) = @_;
    return undef unless defined $value;
    if (ref($value) eq 'HASH') {
        my %copy;
        for my $key (sort keys %$value) {
            $copy{$key} = _clone_provenance_value($value->{$key});
        }
        return \%copy;
    }
    if (ref($value) eq 'ARRAY') {
        return [ map { _clone_provenance_value($_) } @$value ];
    }
    return $value;
}

sub _assignment_priority_suppressed_by {
    my ($assignment) = @_;
    return [] unless ref($assignment->{priority_suppressed_by}) eq 'ARRAY';
    return [ @{$assignment->{priority_suppressed_by}} ];
}

sub _assignment_resource_suppressed_by {
    my ($assignment) = @_;
    return [] unless ref($assignment->{resource_suppressed_by}) eq 'ARRAY';
    return [ @{$assignment->{resource_suppressed_by}} ];
}

sub _build_compatible_fanin_groups {
    my ($records) = @_;
    my @groups;

    push @groups, _same_target_value_groups($records);
    push @groups, _domain_fanin_groups($records, 'request');
    push @groups, _domain_fanin_groups($records, 'pulse');
    push @groups, _rule_trigger_fanin_groups($records);

    return \@groups;
}

sub _same_target_value_groups {
    my ($records) = @_;
    return _group_compatible_records(
        $records,
        sub {
            my ($record) = @_;
            return undef if ($record->{domain} // '') eq 'helper';
            return _group_key(
                'same_target_value',
                $record->{domain},
                $record->{target},
                $record->{operator},
                _record_rhs($record),
            );
        },
        sub {
            my ($key, $members) = @_;
            return {
                kind     => 'same_target_value',
                domain   => $members->[0]{domain},
                target   => $members->[0]{target},
                operator => $members->[0]{operator},
                rhs      => _record_rhs($members->[0]),
                sources  => [ map { _fanin_source_summary($_) } @$members ],
            };
        },
    );
}

sub _domain_fanin_groups {
    my ($records, $domain) = @_;
    return _group_compatible_records(
        $records,
        sub {
            my ($record) = @_;
            return undef unless ($record->{domain} // '') eq $domain;
            return undef if $domain eq 'pulse' && !_is_one_cycle_pulse_record($record);
            return _group_key($domain, $record->{target});
        },
        sub {
            my ($key, $members) = @_;
            my $group = {
                kind    => $domain,
                domain  => $domain,
                target  => $members->[0]{target},
                sources => [ map { _fanin_source_summary($_) } @$members ],
            };
            if ($domain eq 'pulse') {
                $group->{operator} = $members->[0]{operator};
                $group->{rhs} = _record_rhs($members->[0]);
            }
            return $group;
        },
    );
}

sub _rule_trigger_fanin_groups {
    my ($records) = @_;
    return _group_compatible_records(
        $records,
        sub {
            my ($record) = @_;
            return undef unless ($record->{source_kind} // '') eq 'rule_trigger_source';
            my $target = _rule_trigger_target_transaction($record);
            return undef unless defined $target && length $target;
            return _group_key('rule_trigger_fanin', $target);
        },
        sub {
            my ($key, $members) = @_;
            my $target = _rule_trigger_target_transaction($members->[0]);
            return {
                kind               => 'rule_trigger_fanin',
                domain             => 'request',
                target_transaction => $target,
                fanin_target       => "${target}_start",
                sources            => [ map { _fanin_source_summary($_) } @$members ],
            };
        },
    );
}

sub _group_compatible_records {
    my ($records, $key_for, $group_builder) = @_;
    my %by_key;
    my @order;

    for my $record (@$records) {
        my $key = $key_for->($record);
        next unless defined $key;
        push @order, $key unless exists $by_key{$key};
        push @{$by_key{$key}}, $record;
    }

    my @groups;
    for my $key (@order) {
        my $members = $by_key{$key};
        next unless @$members > 1;
        push @groups, $group_builder->($key, $members);
    }

    return @groups;
}

sub _group_key {
    return join "\0", map { defined($_) ? $_ : '' } @_;
}

sub _record_rhs {
    my ($record) = @_;
    return defined($record->{rhs}) ? "$record->{rhs}" : '';
}

sub _is_one_cycle_pulse_record {
    my ($record) = @_;
    return ($record->{operator} // '') =~ /^<[0-9]+$/ && _record_rhs($record) eq '1';
}

sub _rule_trigger_target_transaction {
    my ($record) = @_;
    my $owner = $record->{owner};
    my $target = $record->{target};
    return undef unless defined($owner) && defined($target);
    my $prefix = "${owner}_";
    return undef unless index($target, $prefix) == 0;
    return substr($target, length($prefix));
}

sub _fanin_source_summary {
    my ($record) = @_;
    return {
        owner            => $record->{owner},
        owner_kind       => $record->{owner_kind},
        source_kind      => $record->{source_kind},
        target           => $record->{target},
        operator         => $record->{operator},
        rhs              => $record->{rhs},
        domain           => $record->{domain},
        activation       => _clone_provenance_value($record->{activation}),
        assignment_index => $record->{assignment_index},
        priority_suppressed_by => _clone_provenance_value($record->{priority_suppressed_by}),
    };
}

sub _build_conflict_issues {
    my ($records) = @_;
    my @issues;
    my @data_records = grep { ($_->{domain} // '') eq 'data' && defined $_->{target} } @$records;

    for my $left_idx (0 .. $#data_records) {
        my $left = $data_records[$left_idx];
        for my $right_idx ($left_idx + 1 .. $#data_records) {
            my $right = $data_records[$right_idx];
            next unless ($left->{target} // '') eq ($right->{target} // '');
            next if _compatible_record_pair($left, $right);
            next if _condition_terms_prove_disjoint($left, $right);
            next if _priority_resolved_record_pair($left, $right);
            next if _resource_resolved_record_pair($left, $right);

            if (_both_owner_kind($left, $right, 'rule')) {
                push @issues, _conflict_issue(
                    code         => 'isf_conflicting_rule_writes',
                    severity     => 'error',
                    proof_status => 'proved_conflict',
                    target       => $left->{target},
                    reason       => 'overlapping rule data writes select different values',
                    left         => $left,
                    right        => $right,
                );
                next;
            }

            if (_owner_kind_pair($left, $right, 'rule', 'drive')) {
                push @issues, _conflict_issue(
                    code         => 'isf_unproven_rule_drive_overlap',
                    severity     => 'warning',
                    proof_status => 'not_doable',
                    target       => $left->{target},
                    reason       => 'compile-time proof for rule/drive overlap is not doable yet',
                    left         => $left,
                    right        => $right,
                );
            }
        }
    }

    return \@issues;
}

sub _compatible_record_pair {
    my ($left, $right) = @_;
    return 0 unless ($left->{target} // '') eq ($right->{target} // '');

    if (($left->{domain} // '') eq ($right->{domain} // '')
        && ($left->{domain} // '') ne 'helper'
        && ($left->{operator} // '') eq ($right->{operator} // '')
        && _record_rhs($left) eq _record_rhs($right)) {
        return 1;
    }

    return 1 if ($left->{domain} // '') eq 'request' && ($right->{domain} // '') eq 'request';
    return 1 if ($left->{domain} // '') eq 'pulse'
        && ($right->{domain} // '') eq 'pulse'
        && _is_one_cycle_pulse_record($left)
        && _is_one_cycle_pulse_record($right);

    return 0;
}

sub _priority_resolved_record_pair {
    my ($left, $right) = @_;
    my ($left_owner, $left_kind) = _record_logical_priority_identity($left);
    my ($right_owner, $right_kind) = _record_logical_priority_identity($right);
    return 0 unless _priority_resolvable_owner_kind_pair($left_kind, $right_kind);
    return 1 if _record_priority_suppressed_by($left, $right_owner);
    return 1 if _record_priority_suppressed_by($right, $left_owner);
    return 0;
}

sub _priority_resolvable_owner_kind_pair {
    my ($left_kind, $right_kind) = @_;
    my %allowed = map { $_ => 1 } qw(rule transaction);
    return $allowed{$left_kind // ''} && $allowed{$right_kind // ''};
}

sub _record_logical_priority_identity {
    my ($record) = @_;
    my $owner = $record->{owner};
    my $owner_kind = $record->{owner_kind} // '';
    if ($owner_kind eq 'drive'
        && ref($record->{invoking_transactions}) eq 'ARRAY'
        && @{$record->{invoking_transactions}} == 1)
    {
        return ($record->{invoking_transactions}[0], 'transaction');
    }
    return ($owner, $owner_kind);
}

sub _resource_resolved_record_pair {
    my ($left, $right) = @_;
    return 0 unless _both_owner_kind($left, $right, 'rule');
    return 1 if _record_resource_suppressed_by($left, $right->{owner});
    return 1 if _record_resource_suppressed_by($right, $left->{owner});
    return 0;
}

sub _record_priority_suppressed_by {
    my ($record, $owner) = @_;
    return 0 unless defined($owner);
    my $suppressed_by = $record->{priority_suppressed_by};
    return 0 unless ref($suppressed_by) eq 'ARRAY';
    for my $higher (@$suppressed_by) {
        return 1 if defined($higher) && $higher eq $owner;
    }
    return 0;
}

sub _record_resource_suppressed_by {
    my ($record, $owner) = @_;
    return 0 unless defined($owner);
    my $suppressed_by = $record->{resource_suppressed_by};
    return 0 unless ref($suppressed_by) eq 'ARRAY';
    for my $higher (@$suppressed_by) {
        return 1 if defined($higher) && $higher eq $owner;
    }
    return 0;
}

sub _both_owner_kind {
    my ($left, $right, $kind) = @_;
    return ($left->{owner_kind} // '') eq $kind && ($right->{owner_kind} // '') eq $kind;
}

sub _owner_kind_pair {
    my ($left, $right, $first, $second) = @_;
    my $left_kind = $left->{owner_kind} // '';
    my $right_kind = $right->{owner_kind} // '';
    return 1 if $left_kind eq $first && $right_kind eq $second;
    return 1 if $left_kind eq $second && $right_kind eq $first;
    return 0;
}

sub _conflict_issue {
    my (%args) = @_;
    return {
        code         => $args{code},
        severity     => $args{severity},
        proof_status => $args{proof_status},
        target       => $args{target},
        domain       => 'data',
        reason       => $args{reason},
        sources      => [
            _fanin_source_summary($args{left}),
            _fanin_source_summary($args{right}),
        ],
    };
}

sub _confess_conflict_issues {
    my ($issues) = @_;
    for my $issue (@$issues) {
        next unless ($issue->{severity} // '') eq 'error';
        confess _format_conflict_issue($issue) . "\n";
    }
}

sub _format_conflict_issue {
    my ($issue) = @_;
    my ($left, $right) = @{$issue->{sources}};
    return "ISF conflict '$issue->{code}' on target '$issue->{target}': "
        . "$issue->{reason}; "
        . _format_conflict_source($left)
        . ' conflicts with '
        . _format_conflict_source($right);
}

sub _format_conflict_source {
    my ($source) = @_;
    my $rhs = defined($source->{rhs}) ? $source->{rhs} : '';
    return "$source->{owner_kind} '$source->{owner}' "
        . "($source->{source_kind}, $source->{operator} $rhs)";
}

# --- Post-processing ---
sub _link_states {
    my ($st,$tn)=@_;
    return unless @$st;

    my $e = $st->[0]{name};
    my %idx_by_name = map { $st->[$_]{name} => $_ } 0 .. $#$st;
    my %branch_exit_target;

    for my $i (0 .. $#$st) {
        my $s = $st->[$i];
        next unless $s->{kind} eq 'switch';

        my $last_branch_idx = $i;
        for my $name (@{$s->{branch_state_names} || []}) {
            next unless defined $idx_by_name{$name};
            $last_branch_idx = $idx_by_name{$name} if $idx_by_name{$name} > $last_branch_idx;
        }

        my $exit_target = $last_branch_idx < $#$st ? $st->[$last_branch_idx + 1]{name} : $e;
        $s->{switch_exit_target} = $exit_target;
        for my $name (@{$s->{branch_end_names} || []}) {
            $branch_exit_target{$name} = $exit_target;
        }
    }

    for my $i (0 .. $#$st) {
        my $s = $st->[$i];
        next unless $s->{kind} eq 'branch';

        my $last_branch_idx = $i;
        for my $name (@{$s->{branch_state_names} || []}) {
            next unless defined $idx_by_name{$name};
            $last_branch_idx = $idx_by_name{$name} if $idx_by_name{$name} > $last_branch_idx;
        }

        my $exit_target = $last_branch_idx < $#$st ? $st->[$last_branch_idx + 1]{name} : $e;
        if ($last_branch_idx > $i) {
            my $body_tail = $st->[$last_branch_idx]{name};
            $exit_target = $branch_exit_target{$body_tail} if $branch_exit_target{$body_tail};
        } elsif ($branch_exit_target{$s->{name}}) {
            $exit_target = $branch_exit_target{$s->{name}};
        }
        $s->{branch_exit_target} = $exit_target;
    }

    for my $i (0 .. $#$st) {
        my $s = $st->[$i];
        next unless ($s->{kind} eq 'loop_while' || $s->{kind} eq 'loop_until') && $s->{loop_entry};

        my $last_loop_idx = $i;
        for my $name (
            @{$s->{loop_body_state_names} || []},
            @{$s->{loop_decision_state_names} || []},
        ) {
            next unless defined $idx_by_name{$name};
            $last_loop_idx = $idx_by_name{$name} if $idx_by_name{$name} > $last_loop_idx;
        }

        my $exit_target = $last_loop_idx < $#$st ? $st->[$last_loop_idx + 1]{name} : $e;
        for my $name (@{$s->{loop_decision_state_names} || []}) {
            next unless defined $idx_by_name{$name};
            $st->[$idx_by_name{$name}]{loop_exit_target} = $exit_target;
            $st->[$idx_by_name{$name}]{loop_body_start} = $s->{loop_body_start};
        }
        # ISF-LOOP-EARLY-EXIT / ISF-LOOP-CONTINUE: stamp the TRUE target onto this
        # loop's `(exit-when)` / `(continue-when)` decision states (both kind
        # `loop_exit_when`). An `(exit-when)` jumps to the loop exit; a
        # `(continue-when)` (marked `loop_continue_when`) jumps to the loop's TAIL
        # check — the last decision state, which re-evaluates the condition and either
        # loops again or exits.
        my $continue_target = (@{$s->{loop_decision_state_names} || []})
            ? $s->{loop_decision_state_names}[-1] : $exit_target;
        for my $name (@{$s->{loop_body_state_names} || []}) {
            next unless defined $idx_by_name{$name};
            my $body_state = $st->[$idx_by_name{$name}];
            next unless ($body_state->{kind} // '') eq 'loop_exit_when';
            $body_state->{loop_exit_target} =
                $body_state->{loop_continue_when} ? $continue_target : $exit_target;
        }
        $s->{loop_exit_target} = $exit_target;
    }

    # ISF-LOOP-EARLY-EXIT / ISF-LOOP-CONTINUE: an `(exit-when)` / `(continue-when)` is
    # only valid inside a loop. After the per-loop pass has stamped the TRUE target
    # onto every such state that belongs to a loop, any remaining un-stamped
    # `loop_exit_when` is not inside a loop (e.g. a `(when ...)` not nested in a
    # `while`/`until`) — fail closed, naming the actual clause. (A direct while/until
    # body use is gated by the clause allow-list; this catches the when-nested case,
    # where `when` is allowed both top-level and in a loop.)
    for my $s (@$st) {
        next unless ($s->{kind} // '') eq 'loop_exit_when';
        next if defined $s->{loop_exit_target};
        my $clause = $s->{loop_continue_when} ? 'continue-when' : 'exit-when';
        confess "Transaction '$tn': '($clause ...)' is only valid inside a 'while'/'until' loop body\n";
    }

    for my $i (0 .. $#$st) {
        my $s = $st->[$i];
        next unless $s->{dynamic_wait_entry};

        my $last_idx = _state_region_last_index(\%idx_by_name, $s->{wait_state_names}, $i);
        my $exit_idx = $last_idx + 1;
        my $exit_target = $exit_idx <= $#$st ? $st->[$exit_idx]{name} : $e;
        $s->{dynamic_wait_next_wait_state} = $st->[$exit_idx]
            if $exit_idx <= $#$st && $st->[$exit_idx]{dynamic_wait_entry};
        $s->{dynamic_wait_exit_target} = $exit_target;
        if (defined($s->{dynamic_wait_loop_state})) {
            my $loop_state = _state_by_name(\%idx_by_name, $st, $s->{dynamic_wait_loop_state});
            if ($loop_state) {
                $loop_state->{dynamic_wait_next_wait_state} = $s->{dynamic_wait_next_wait_state};
                $loop_state->{dynamic_wait_exit_target} = $exit_target;
            }
        }
    }

    for my $i(0..$#$st){my $s=$st->[$i];my $n=$i<$#$st?$st->[$i+1]{name}:undef;my $next=$branch_exit_target{$s->{name}}||$n;
        my $next_state = $i < $#$st ? $st->[$i + 1] : undef;
        if($s->{dynamic_wait_entry}){_link_dynamic_wait_state($s)}
        elsif($s->{dynamic_wait_loop_for}){_link_dynamic_wait_loop_state($s)}
        elsif($s->{kind}eq'repeat_init'){_link_repeat_init_state($s,\%idx_by_name,$st,$next_state,$next,$e)}
        elsif($s->{kind}eq'switch'){_link_switch_state($s,\%idx_by_name,$st,$n,$e)}
        elsif($s->{kind}eq'loop_while'||$s->{kind}eq'loop_until'){_link_loop_state($s,\%idx_by_name,$st)}
        elsif($s->{kind}eq'loop_exit_when'){_link_loop_exit_when_state($s,$next_state,$next)}
        elsif($next_state&&$next_state->{dynamic_wait_entry}){_link_dynamic_wait_predecessor($tn,$s,$next_state)}
        elsif($s->{kind}eq'entry'&&$n){push @{$s->{transitions}},{target=>$n,condition=>$s->{guard}}}
        elsif ($s->{kind} eq 'await' && $next) {
            push @{$s->{transitions}}, {target => $next, condition => $s->{guard}};
            # A blocking call can await completion without a watchdog. Do not
            # create a dangling timeout edge that the emitter merely ignores.
            if (defined($s->{watchdog}) && defined($s->{watchdog}{name})) {
                push @{$s->{transitions}}, {
                    target => "${tn}_timeout",
                    condition => {signal => $s->{watchdog}{name}, op => '=', value => 0},
                };
            }
        }
        elsif($s->{kind}eq'stage'&&$next){push @{$s->{transitions}},{target=>$next,condition=>{port=>$s->{ready}}}}
        elsif($s->{kind}eq'repeat_check'){_link_repeat_check_state($s,\%idx_by_name,$st,$next)}
        elsif(($s->{kind}eq'sequential'||$s->{kind}eq'contract'||$s->{kind}eq'wait'||$s->{kind}eq'bank_store'||$s->{kind}eq'bank_load')&&$next){push @{$s->{transitions}},{target=>$next}}
        elsif($s->{kind}eq'branch'){my$skip=$s->{branch_exit_target}||$n||$e;push @{$s->{transitions}},{target=>$skip}}
        elsif ($s->{kind} eq 'sync_all' || $s->{kind} eq 'sync_any') {
            # A trailing join holds here; only an explicit complete rearms the
            # transaction. Keep a real target for the emitted completion guard,
            # including an empty pending set, instead of an empty state body.
            push @{$s->{transitions}}, {target => $next // $s->{name}};
        }
        elsif($s->{kind}eq'terminal'){push @{$s->{transitions}},{target=>$e}}}

    _append_dynamic_wait_zero_sample_clones($st,\%idx_by_name);
}

sub _link_repeat_init_state {
    my ($state, $idx_by_name, $states, $next_state, $next_target, $entry_target) = @_;

    # ISF-COUNTED-REPEAT-TERMINATION (check-first): the init state loads the counter once
    # and flows unconditionally to the repeat_check (the last state of the repeat region).
    # The check performs the count==0 -> exit test and the per-iteration decrement + body
    # dispatch, so it subsumes the old runtime zero-branch (which used to skip the body at
    # init when a runtime count was 0). Looping back to the check (not init) means the
    # counter is loaded exactly once.
    my $check_name = ($state->{repeat_state_names} && @{$state->{repeat_state_names}})
        ? $state->{repeat_state_names}[-1]
        : $next_target;
    return unless defined($check_name) && length($check_name);
    push @{$state->{transitions}}, { target => $check_name };
}

sub _link_repeat_check_state {
    my ($state, $idx_by_name, $states, $next_target) = @_;
    my $loop_target = $state->{loop_target};
    my $counter = $state->{counter};
    my $loop_state = _state_by_name($idx_by_name, $states, $loop_target);

    if ($loop_state && $loop_state->{dynamic_wait_entry}) {
        _link_dynamic_wait_entry_edge($state, $loop_state, "(!= $counter 0)");
    } else {
        push @{$state->{transitions}}, {
            target    => $loop_target,
            condition => { signal => $counter, op => '!=', value => 0 },
        } if defined($loop_target) && length($loop_target);
    }

    push @{$state->{transitions}}, {
        target    => $next_target,
        condition => { signal => $counter, op => '=', value => 0 },
    } if defined($next_target) && length($next_target);
}

sub _link_loop_exit_when_state {
    my ($state, $next_state, $next_target) = @_;
    my $condition = _loop_exit_when_condition_expr($state);

    if ($next_state && $next_state->{dynamic_wait_entry}) {
        $state->{loop_transitions_materialized} = 1;
        push @{$state->{transitions}}, {
            target    => $state->{loop_exit_target},
            condition => { expr => $condition },
        } if defined($state->{loop_exit_target});

        _link_dynamic_wait_entry_edge(
            $state,
            $next_state,
            _negated_condition_expr($condition),
        ) if defined($next_target) && length($next_target);
        return;
    }

    push @{$state->{transitions}}, {
        target    => $state->{loop_exit_target},
        condition => { loop_branch => 1 },
    } if defined($state->{loop_exit_target});

    return unless defined($next_target) && length($next_target);

    push @{$state->{transitions}}, {
        target    => $next_target,
        condition => { loop_branch => 0 },
    };
}

sub _loop_exit_when_condition_expr {
    my ($state) = @_;
    my $condition = $state->{exit_when_condition} // $state->{condition};
    return !ref($condition) ? $condition : _format_isf_expr($condition);
}

sub _state_region_last_index {
    my ($idx_by_name, $state_names, $fallback_idx) = @_;
    my $last_idx = $fallback_idx;
    for my $name (@{$state_names || []}) {
        next unless defined $name;
        next unless exists $idx_by_name->{$name};
        $last_idx = $idx_by_name->{$name}
            if $idx_by_name->{$name} > $last_idx;
    }
    return $last_idx;
}

sub _link_switch_state {
    my ($state, $idx_by_name, $states, $next_target, $entry_target) = @_;
    my $skip = $state->{switch_exit_target} || $next_target || $entry_target;
    my @explicit_conditions;
    my $has_dynamic_branch;

    for my $branch (@{$state->{branches} || []}) {
        next if _is_default_switch_value($branch->{value});
        push @explicit_conditions, _switch_value_condition_expr($state->{signal}, $branch->{value});
    }

    for my $branch (@{$state->{branches} || []}) {
        my $body = _state_by_name($idx_by_name, $states, $branch->{body_start});
        if ($body && $body->{dynamic_wait_entry}) {
            $has_dynamic_branch = 1;
            last;
        }
    }

    if (!$has_dynamic_branch) {
        push @{$state->{transitions}}, { target => $skip }
            unless $state->{has_default_branch};
        for my $branch (@{$state->{branches} || []}) {
            next if _is_default_switch_value($branch->{value});
            push @{$state->{transitions}}, {
                target    => $branch->{body_start},
                condition => {
                    signal => $state->{signal},
                    value  => $branch->{value},
                },
            };
        }
        return;
    }

    my $default_condition = _switch_default_condition_expr(\@explicit_conditions);
    $state->{switch_transitions_materialized} = 1;

    for my $branch (@{$state->{branches} || []}) {
        my $body = _state_by_name($idx_by_name, $states, $branch->{body_start});
        my $condition = _is_default_switch_value($branch->{value})
            ? $default_condition
            : _switch_value_condition_expr($state->{signal}, $branch->{value});

        if ($body && $body->{dynamic_wait_entry}) {
            _link_dynamic_wait_entry_edge($state, $body, $condition);
        } elsif (_is_default_switch_value($branch->{value})) {
            push @{$state->{transitions}}, {
                target    => $branch->{body_start},
                condition => { expr => $condition },
            };
        } else {
            push @{$state->{transitions}}, {
                target    => $branch->{body_start},
                condition => {
                    signal => $state->{signal},
                    value  => $branch->{value},
                },
            };
        }
    }

    if (!$state->{has_default_branch}) {
        push @{$state->{transitions}}, {
            target    => $skip,
            condition => { expr => $default_condition },
        };
    }
}

sub _state_by_name {
    my ($idx_by_name, $states, $name) = @_;
    return undef unless defined $name;
    return undef unless ref($idx_by_name) eq 'HASH' && exists $idx_by_name->{$name};
    return $states->[$idx_by_name->{$name}];
}

sub _switch_value_condition_expr {
    my ($signal, $value) = @_;
    return "(== $signal $value)";
}

sub _switch_default_condition_expr {
    my ($explicit_conditions) = @_;
    my @conditions = grep { defined($_) && length($_) } @{$explicit_conditions || []};
    return '1' unless @conditions;
    return _negated_condition_expr($conditions[0]) if @conditions == 1;
    return _negated_condition_expr('(| ' . join(' ', @conditions) . ')');
}

sub _link_loop_state {
    my ($state, $idx_by_name, $states) = @_;
    my $condition = _loop_condition_expr($state);
    my @edges;

    if (($state->{kind} // '') eq 'loop_while') {
        @edges = (
            {
                branch    => 1,
                target    => $state->{loop_body_start},
                condition => $condition,
            },
            {
                branch    => 0,
                target    => $state->{loop_exit_target},
                condition => _negated_condition_expr($condition),
            },
        );
    } else {
        @edges = (
            {
                branch    => 1,
                target    => $state->{loop_exit_target},
                condition => $condition,
            },
            {
                branch    => 0,
                target    => $state->{loop_body_start},
                condition => _negated_condition_expr($condition),
            },
        );
    }

    my $materialize = 0;
    for my $edge (@edges) {
        my $target_state = _state_by_name($idx_by_name, $states, $edge->{target});
        if ($target_state && $target_state->{dynamic_wait_entry}) {
            $materialize = 1;
            last;
        }
    }

    if (!$materialize) {
        for my $edge (@edges) {
            next unless $edge->{target};
            push @{$state->{transitions}}, {
                target    => $edge->{target},
                condition => { loop_branch => $edge->{branch} },
            };
        }
        return;
    }

    $state->{loop_transitions_materialized} = 1;
    for my $edge (@edges) {
        next unless $edge->{target};
        my $target_state = _state_by_name($idx_by_name, $states, $edge->{target});
        if ($target_state && $target_state->{dynamic_wait_entry}) {
            _link_dynamic_wait_entry_edge($state, $target_state, $edge->{condition});
        } else {
            push @{$state->{transitions}}, {
                target    => $edge->{target},
                condition => { expr => $edge->{condition} },
            };
        }
    }
}

sub _loop_condition_expr {
    my ($state) = @_;
    my $condition = $state->{condition};
    return !ref($condition) ? $condition : _format_isf_expr($condition);
}

sub _link_dynamic_wait_state {
    my ($state) = @_;
    my $counter = $state->{wait_counter};
    my $exit_target = $state->{dynamic_wait_exit_target};
    my $width = $state->{wait_counter_width} // 1;

    confess "Runtime dynamic wait state '$state->{name}' has no sampled counter\n"
        unless defined($counter) && length($counter);
    confess "Runtime dynamic wait state '$state->{name}' has no exit target\n"
        unless defined($exit_target) && length($exit_target);

    my $final_cycle_condition = "(== $counter 1)";
    my $next_dynamic_wait = $state->{dynamic_wait_next_wait_state};
    if ($next_dynamic_wait) {
        _link_dynamic_wait_entry_edge(
            $state,
            $next_dynamic_wait,
            $final_cycle_condition,
        );
    } else {
        push @{$state->{transitions}}, {
            target    => $exit_target,
            condition => { signal => $counter, op => '=', value => 1 },
        };
    }
    my $loop_target = $state->{dynamic_wait_loop_state} // $state->{name};
    push @{$state->{transitions}}, {
        target    => $loop_target,
        condition => { signal => $counter, op => '>', value => 1 },
    } if $width > 1;
}

sub _link_dynamic_wait_loop_state {
    my ($state) = @_;
    my $counter = $state->{wait_counter};
    my $exit_target = $state->{dynamic_wait_exit_target};
    my $width = $state->{wait_counter_width} // 1;

    confess "Runtime dynamic wait loop state '$state->{name}' has no sampled counter\n"
        unless defined($counter) && length($counter);
    confess "Runtime dynamic wait loop state '$state->{name}' has no exit target\n"
        unless defined($exit_target) && length($exit_target);

    my $final_cycle_condition = "(== $counter 1)";
    my $next_dynamic_wait = $state->{dynamic_wait_next_wait_state};
    if ($next_dynamic_wait) {
        _link_dynamic_wait_entry_edge(
            $state,
            $next_dynamic_wait,
            $final_cycle_condition,
        );
    } else {
        push @{$state->{transitions}}, {
            target    => $exit_target,
            condition => { signal => $counter, op => '=', value => 1 },
        };
    }
    push @{$state->{transitions}}, {
        target    => $state->{name},
        condition => { signal => $counter, op => '>', value => 1 },
    } if $width > 1;
}

sub _link_dynamic_wait_predecessor {
    my ($tn, $state, $wait_state) = @_;
    my $kind = $state->{kind} // '';
    my $source = $wait_state->{wait_count_source};

    my $base_condition = _dynamic_wait_predecessor_condition_expr($state);
    confess "Transaction '$tn': runtime dynamic wait count '$source' cannot follow state '$state->{name}' of kind '$kind' in the current dynamic-wait slice\n"
        unless defined $base_condition;

    _preserve_dynamic_wait_predecessor_alternatives($tn, $state);
    _link_dynamic_wait_entry_edge($state, $wait_state, $base_condition);
}

sub _dynamic_wait_predecessor_condition_expr {
    my ($state) = @_;
    my $kind = $state->{kind} // '';

    return _guard_condition_expr($state->{guard}) // '1'
        if $kind eq 'entry';
    return '1'
        if $kind eq 'sequential'
            || $kind eq 'contract'
            || $kind eq 'bank_load'
            || $kind eq 'bank_store'
            || ($kind eq 'wait' && !$state->{dynamic_wait_entry});
    return _guard_condition_expr($state->{guard})
        if $kind eq 'await';
    return $state->{ready}
        if $kind eq 'stage' && defined($state->{ready}) && length($state->{ready});
    return "(== $state->{counter} 0)"
        if $kind eq 'repeat_check' && defined($state->{counter}) && length($state->{counter});
    return _sync_all_condition_expr($state->{done_ports})
        if $kind eq 'sync_all';
    return _sync_any_condition_expr($state->{done_ports})
        if $kind eq 'sync_any';
    return _branch_condition_expr($state)
        if $kind eq 'branch';
    return undef;
}

sub _preserve_dynamic_wait_predecessor_alternatives {
    my ($tn, $state) = @_;
    my $kind = $state->{kind} // '';

    if ($kind eq 'await') {
        push @{$state->{transitions}}, {
            target    => "${tn}_timeout",
            condition => { signal => $state->{watchdog}{name}, op => '=', value => 0 },
        } if $state->{watchdog} && defined($state->{watchdog}{name});
    } elsif ($kind eq 'repeat_check') {
        push @{$state->{transitions}}, {
            target    => $state->{loop_target},
            condition => { signal => $state->{counter}, op => '!=', value => 0 },
        } if defined($state->{loop_target}) && defined($state->{counter});
    } elsif ($kind eq 'branch') {
        my $skip = $state->{branch_exit_target};
        my $condition = _branch_condition_expr($state);
        push @{$state->{transitions}}, {
            target    => $skip,
            condition => { expr => _negated_condition_expr($condition) },
        } if defined($skip) && defined($condition);
    }
}

sub _branch_condition_expr {
    my ($state) = @_;
    return undef unless $state && ref($state) eq 'HASH';
    my $condition = $state->{condition};
    return undef unless defined $condition;
    return !ref($condition) ? $condition : _format_isf_expr($condition);
}

sub _sync_all_condition_expr {
    my ($ports) = @_;
    my @ports = grep { defined($_) && length($_) } @{$ports || []};
    return '1' unless @ports;
    return $ports[0] if @ports == 1;
    return '(& ' . join(' ', @ports) . ')';
}

sub _sync_any_condition_expr {
    my ($ports) = @_;
    my @ports = grep { defined($_) && length($_) } @{$ports || []};
    return '1' unless @ports;
    return $ports[0] if @ports == 1;
    return '(| ' . join(' ', @ports) . ')';
}

sub _link_dynamic_wait_entry_edge {
    my ($state, $wait_state, $base_condition, $carried_sample_wait) = @_;
    my $source = $wait_state->{wait_count_source};
    my $counter = $wait_state->{wait_counter};
    my $enter_target = _dynamic_wait_entry_target($wait_state, $carried_sample_wait);

    # '&' is bitwise in the scheduled DSL. Reduce the multi-bit count to a
    # boolean before combining it with scalar predecessor conditions.
    my $enter_condition = _combine_condition_exprs($base_condition, "(!= $source 0)");
    my $bypass_condition = _combine_condition_exprs($base_condition, "(== $source 0)");

    push @{$state->{assignments}}, {
        lhs         => $counter,
        rhs         => $source,
        op          => '<-',
        guard       => { expr => $enter_condition },
        source_kind => 'dynamic_wait_counter_load',
    };
    push @{$state->{transitions}}, {
        target    => $enter_target,
        condition => { expr => $enter_condition },
    };

    my $next_dynamic_wait = $wait_state->{dynamic_wait_next_wait_state};
    my $sample_source_wait = $carried_sample_wait;
    $sample_source_wait //= $wait_state
        if _dynamic_wait_has_pending_samples($wait_state);

    if ($next_dynamic_wait) {
        _link_dynamic_wait_entry_edge(
            $state,
            $next_dynamic_wait,
            $bypass_condition,
            $sample_source_wait,
        );
    } else {
        my $target = _dynamic_wait_zero_bypass_target($wait_state, $sample_source_wait);
        push @{$state->{transitions}}, {
            target    => $target,
            condition => { expr => $bypass_condition },
        };
    }
}

sub _dynamic_wait_entry_target {
    my ($wait_state, $carried_sample_wait) = @_;
    return $wait_state->{name}
        unless _dynamic_wait_has_pending_samples($carried_sample_wait);
    return $wait_state->{name}
        if ($carried_sample_wait->{name} // '') eq ($wait_state->{name} // '');

    return _dynamic_wait_pending_entry_clone_target($wait_state, $carried_sample_wait);
}

sub _dynamic_wait_pending_entry_clone_target {
    my ($wait_state, $carried_sample_wait) = @_;
    my $source_name = $carried_sample_wait->{name};
    my $clone_name = join('_', $wait_state->{name}, 'sample_from', $source_name);

    $wait_state->{dynamic_wait_pending_entry_clone_requests}{$source_name} //= {
        name                       => $clone_name,
        source_name                => $source_name,
        pending_sample_assignments => [
            map { _clone_assignment($_) } @{$carried_sample_wait->{pending_sample_assignments} || []},
        ],
    };

    return $clone_name;
}

sub _dynamic_wait_zero_bypass_target {
    my ($wait_state, $sample_source_wait) = @_;
    $sample_source_wait //= $wait_state;
    return $wait_state->{dynamic_wait_exit_target}
        unless _dynamic_wait_has_pending_samples($sample_source_wait);

    return _dynamic_wait_carried_zero_sample_clone_target($wait_state, $sample_source_wait)
        if ($sample_source_wait->{name} // '') ne ($wait_state->{name} // '');

    my $clone = $wait_state->{dynamic_wait_zero_sample_clone_name}
        //= "$wait_state->{name}_zero_sample";
    return $clone;
}

sub _dynamic_wait_carried_zero_sample_clone_target {
    my ($wait_state, $sample_source_wait) = @_;
    my $source_name = $sample_source_wait->{name};
    my $clone_name = join('_', $source_name, 'zero_sample_after', $wait_state->{name});

    $wait_state->{dynamic_wait_carried_zero_sample_clone_requests}{$source_name} //= {
        name                       => $clone_name,
        source_name                => $source_name,
        pending_sample_assignments => [
            map { _clone_assignment($_) } @{$sample_source_wait->{pending_sample_assignments} || []},
        ],
    };

    return $clone_name;
}

sub _dynamic_wait_has_pending_samples {
    my ($wait_state) = @_;
    return 0 unless $wait_state && ref($wait_state) eq 'HASH';
    return ref($wait_state->{pending_sample_assignments}) eq 'ARRAY'
        && @{$wait_state->{pending_sample_assignments}};
}

sub _append_dynamic_wait_zero_sample_clones {
    my ($states, $idx_by_name) = @_;
    my @clones;
    my %planned_clone;

    for my $wait_state (@$states) {
        next unless ($wait_state->{dynamic_wait_entry} // 0);
        my $clone_name = $wait_state->{dynamic_wait_zero_sample_clone_name};
        if (_dynamic_wait_has_pending_samples($wait_state) && defined($clone_name) && length($clone_name)) {
            next if exists $idx_by_name->{$clone_name} || $planned_clone{$clone_name}++;

            my $target_name = $wait_state->{dynamic_wait_exit_target};
            my $target_state = _state_by_name($idx_by_name, $states, $target_name);
            confess "Runtime dynamic wait '$wait_state->{name}' cannot build zero-count sample target '$target_name'\n"
                unless $target_state;
            push @clones, _clone_dynamic_wait_zero_sample_target(
                $wait_state,
                $target_state,
                $clone_name,
            );
        }

        for my $source_name (sort keys %{$wait_state->{dynamic_wait_pending_entry_clone_requests} || {}}) {
            my $request = $wait_state->{dynamic_wait_pending_entry_clone_requests}{$source_name};
            my $entry_clone_name = $request->{name};
            next unless defined($entry_clone_name) && length($entry_clone_name);
            next if exists $idx_by_name->{$entry_clone_name} || $planned_clone{$entry_clone_name}++;

            push @clones, _clone_dynamic_wait_pending_entry_target(
                $wait_state,
                $request,
            );
        }

        for my $source_name (sort keys %{$wait_state->{dynamic_wait_carried_zero_sample_clone_requests} || {}}) {
            my $request = $wait_state->{dynamic_wait_carried_zero_sample_clone_requests}{$source_name};
            my $carried_clone_name = $request->{name};
            next unless defined($carried_clone_name) && length($carried_clone_name);
            next if exists $idx_by_name->{$carried_clone_name} || $planned_clone{$carried_clone_name}++;

            my $target_name = $wait_state->{dynamic_wait_exit_target};
            my $target_state = _state_by_name($idx_by_name, $states, $target_name);
            confess "Runtime dynamic wait '$request->{source_name}' cannot build carried zero-count sample target '$target_name'\n"
                unless $target_state;
            my %sample_wait = (
                name                       => $request->{source_name},
                pending_sample_assignments => [
                    map { _clone_assignment($_) } @{$request->{pending_sample_assignments} || []},
                ],
            );
            push @clones, _clone_dynamic_wait_zero_sample_target(
                \%sample_wait,
                $target_state,
                $carried_clone_name,
            );
        }
    }

    for my $clone (@clones) {
        $idx_by_name->{$clone->{name}} = scalar(@$states);
        push @$states, $clone;
    }
}

sub _clone_dynamic_wait_pending_entry_target {
    my ($wait_state, $request) = @_;

    my %clone = %$wait_state;
    $clone{name} = $request->{name};
    $clone{assignments} = [
        map { _clone_assignment($_) } @{$request->{pending_sample_assignments} || []},
        map { _clone_assignment($_) } @{$wait_state->{assignments} || []},
    ];
    $clone{transitions} = [
        map { _clone_transition($_) } @{$wait_state->{transitions} || []},
    ];
    $clone{carried_sample_entry_clone_of} = $wait_state->{name};
    $clone{carried_sample_source_wait} = $request->{source_name};
    delete $clone{wait_entry};
    delete $clone{wait_state_names};
    delete $clone{wait_cycles};
    delete $clone{wait_count_kind};
    delete $clone{wait_count_source};
    delete $clone{wait_counter};
    delete $clone{wait_counter_width};
    delete $clone{dynamic_wait_entry};
    delete $clone{dynamic_wait_loop_for};
    delete $clone{dynamic_wait_loop_state};
    delete $clone{dynamic_wait_exit_target};
    delete $clone{dynamic_wait_next_wait_state};
    delete $clone{dynamic_wait_zero_sample_clone_name};
    delete $clone{dynamic_wait_pending_entry_clone_requests};
    delete $clone{dynamic_wait_carried_zero_sample_clone_requests};
    delete $clone{pending_sample_assignments};
    delete $clone{loop_entry};

    return \%clone;
}

sub _clone_dynamic_wait_zero_sample_target {
    my ($wait_state, $target_state, $clone_name) = @_;

    confess "Runtime dynamic wait '$wait_state->{name}' with pending samples cannot zero-bypass to state '$target_state->{name}' because that state cannot materialize pending samples without changing timing in the current pending-sample slice\n"
        unless _dynamic_wait_zero_sample_target_accepts_samples($wait_state, $target_state);

    my %clone = %$target_state;
    $clone{name} = $clone_name;
    $clone{assignments} = [
        map { _clone_assignment($_) } @{$wait_state->{pending_sample_assignments}},
        map { _clone_assignment($_) } @{$target_state->{assignments} || []},
    ];
    $clone{transitions} = [
        map { _clone_transition($_) } @{$target_state->{transitions} || []},
    ];
    $clone{zero_sample_clone_of} = $target_state->{name};
    delete $clone{wait_entry};
    delete $clone{wait_state_names};
    delete $clone{wait_cycles};
    delete $clone{wait_count_kind};
    delete $clone{wait_count_source};
    delete $clone{wait_counter};
    delete $clone{wait_counter_width};
    delete $clone{dynamic_wait_entry};
    delete $clone{dynamic_wait_loop_for};
    delete $clone{dynamic_wait_loop_state};
    delete $clone{dynamic_wait_exit_target};
    delete $clone{dynamic_wait_next_wait_state};
    delete $clone{dynamic_wait_zero_sample_clone_name};
    delete $clone{dynamic_wait_pending_entry_clone_requests};
    delete $clone{dynamic_wait_carried_zero_sample_clone_requests};
    delete $clone{pending_sample_assignments};
    delete $clone{loop_entry};

    return \%clone;
}

sub _dynamic_wait_zero_sample_target_accepts_samples {
    my ($wait_state, $target_state) = @_;
    my $kind = $target_state->{kind} // '';
    return 0 if $target_state->{dynamic_wait_entry} || $target_state->{dynamic_wait_loop_for};

    return 1 if $kind eq 'wait';
    return 1 if $kind eq 'await'
        && !(grep { ($_->{source_kind} // '') =~ /\Ado_/ } @{$target_state->{assignments} || []});
    return 1 if $kind eq 'terminal'
        && @{$target_state->{assignments} || []}
        && !(grep { ($_->{source_kind} // '') ne 'complete_pulse' } @{$target_state->{assignments} || []});
    return 1 if $kind eq 'stage'
        && _dynamic_wait_zero_sample_target_is_independent_data_op($wait_state, $target_state, qw(stage_valid latency_increment_request));
    return 1 if $kind eq 'contract'
        && _dynamic_wait_zero_sample_target_is_independent_data_op($wait_state, $target_state, qw(contract_arm_request latency_increment_request));
    return 1 if ($kind eq 'repeat_check' || $kind eq 'loop_while' || $kind eq 'loop_until')
        && _dynamic_wait_zero_sample_target_is_independent_control_state($wait_state, $target_state);
    return 1 if ($kind eq 'sync_all' || $kind eq 'sync_any')
        && _dynamic_wait_zero_sample_target_is_independent_sync_state($wait_state, $target_state);
    return 1 if _dynamic_wait_zero_sample_target_is_phase_marker($target_state);

    if ($kind eq 'sequential') {
        for my $assignment (@{$target_state->{assignments} || []}) {
            my $source_kind = $assignment->{source_kind} // '';
            return 1
                if $source_kind eq 'drive_call_start'
                    || $source_kind eq 'inline_drive'
                    || $source_kind eq 'sample_capture';
        }
        return 1 if _dynamic_wait_zero_sample_target_is_independent_setter($wait_state, $target_state);
        return 1 if _dynamic_wait_zero_sample_target_is_independent_data_op($wait_state, $target_state, qw(shift latency_increment_request));
        return 1 if _dynamic_wait_zero_sample_target_is_independent_data_op($wait_state, $target_state, qw(assemble latency_increment_request));
        return 1 if _dynamic_wait_zero_sample_target_is_independent_data_op($wait_state, $target_state, qw(extract_capture latency_increment_request));
        return 1 if _dynamic_wait_zero_sample_target_is_independent_data_op($wait_state, $target_state, qw(spawn_start latency_increment_request));
    }
    return 1 if $kind eq 'bank_load'
        && _dynamic_wait_zero_sample_target_is_independent_data_op($wait_state, $target_state, qw(bank_load latency_increment_request));
    return 1 if $kind eq 'bank_store'
        && _dynamic_wait_zero_sample_target_is_independent_data_op($wait_state, $target_state, qw(bank_store latency_increment_request));

    return 0;
}

sub _dynamic_wait_zero_sample_target_is_independent_setter {
    my ($wait_state, $target_state) = @_;
    return _dynamic_wait_zero_sample_target_is_independent_data_op($wait_state, $target_state, qw(set update latency_increment_request));
}

sub _dynamic_wait_zero_sample_target_is_independent_control_state {
    my ($wait_state, $target_state) = @_;
    return 0 unless _dynamic_wait_has_pending_samples($wait_state);

    my %pending_sample = _dynamic_wait_pending_sample_names($wait_state);
    return 0 unless %pending_sample;

    for my $assignment (@{$target_state->{assignments} || []}) {
        return 0 if _dynamic_wait_assignment_touches_pending_sample($assignment, \%pending_sample);
    }

    for my $transition (@{$target_state->{transitions} || []}) {
        return 0 if _dynamic_wait_condition_touches_pending_sample($transition->{condition}, \%pending_sample);
    }

    for my $condition ($target_state->{loop_condition}, $target_state->{condition}) {
        my $text = ref($condition) ? _format_isf_expr($condition) : $condition;
        return 0 if _dynamic_wait_text_touches_pending_sample($text, \%pending_sample);
    }

    return @{$target_state->{transitions} || []} ? 1 : 0;
}

sub _dynamic_wait_zero_sample_target_is_phase_marker {
    my ($target_state) = @_;
    return 0 unless ($target_state->{kind} // '') eq 'sequential';
    return 0 unless defined($target_state->{phase_name}) && length($target_state->{phase_name});
    return 0 if @{$target_state->{assignments} || []};
    return @{$target_state->{transitions} || []} ? 1 : 0;
}

sub _dynamic_wait_zero_sample_target_is_independent_sync_state {
    my ($wait_state, $target_state) = @_;
    return 0 unless _dynamic_wait_has_pending_samples($wait_state);

    my %pending_sample = _dynamic_wait_pending_sample_names($wait_state);
    return 0 unless %pending_sample;

    for my $port (@{$target_state->{done_ports} || []}) {
        return 0 if _dynamic_wait_text_touches_pending_sample($port, \%pending_sample);
    }

    for my $transition (@{$target_state->{transitions} || []}) {
        return 0 if _dynamic_wait_condition_touches_pending_sample($transition->{condition}, \%pending_sample);
    }

    return @{$target_state->{transitions} || []} ? 1 : 0;
}

sub _dynamic_wait_zero_sample_target_is_independent_data_op {
    my ($wait_state, $target_state, @source_kinds) = @_;
    return 0 unless _dynamic_wait_has_pending_samples($wait_state);

    my %pending_sample = _dynamic_wait_pending_sample_names($wait_state);
    return 0 unless %pending_sample;

    my %accepted_source_kind = map { $_ => 1 } @source_kinds;
    my $has_data_op = 0;
    for my $assignment (@{$target_state->{assignments} || []}) {
        my $source_kind = $assignment->{source_kind} // '';
        return 0 unless $accepted_source_kind{$source_kind};
        $has_data_op = 1 unless $source_kind eq 'latency_increment_request';
        return 0 if _dynamic_wait_assignment_touches_pending_sample($assignment, \%pending_sample);
    }

    for my $transition (@{$target_state->{transitions} || []}) {
        return 0 if _dynamic_wait_condition_touches_pending_sample($transition->{condition}, \%pending_sample);
    }

    return $has_data_op ? 1 : 0;
}

sub _dynamic_wait_pending_sample_names {
    my ($wait_state) = @_;
    return map {
        my $lhs = $_->{lhs};
        defined($lhs) && !ref($lhs) && length($lhs) ? ($lhs => 1) : ();
    } @{$wait_state->{pending_sample_assignments} || []};
}

sub _dynamic_wait_assignment_touches_pending_sample {
    my ($assignment, $pending_sample) = @_;
    return 1 if $pending_sample->{$assignment->{lhs} // ''};
    return 1 if _dynamic_wait_text_touches_pending_sample($assignment->{rhs}, $pending_sample);
    return _dynamic_wait_condition_touches_pending_sample($assignment->{guard}, $pending_sample);
}

sub _dynamic_wait_condition_touches_pending_sample {
    my ($condition, $pending_sample) = @_;
    return 0 unless ref($condition) eq 'HASH';
    for my $key (qw(expr signal port)) {
        return 1 if _dynamic_wait_text_touches_pending_sample($condition->{$key}, $pending_sample);
    }
    return 0;
}

sub _dynamic_wait_text_touches_pending_sample {
    my ($text, $pending_sample) = @_;
    return 0 unless defined($text) && !ref($text);
    for my $name (keys %$pending_sample) {
        return 1 if $text =~ /(?<![A-Za-z0-9_])\Q$name\E(?![A-Za-z0-9_])/;
    }
    return 0;
}

sub _clone_assignment {
    my ($assignment) = @_;
    my %clone = %$assignment;
    $clone{guard} = { %{$assignment->{guard}} }
        if ref($assignment->{guard}) eq 'HASH';
    return \%clone;
}

sub _clone_transition {
    my ($transition) = @_;
    my %clone = %$transition;
    $clone{condition} = { %{$transition->{condition}} }
        if ref($transition->{condition}) eq 'HASH';
    return \%clone;
}

sub _inj_watchdog {
    my ($st,$tn,$wn,$lim,$ctrs)=@_;
    $ctrs->{last_error} = 1;
    unshift @{$st->[0]{assignments}},{lhs=>$wn,rhs=>"(- $lim 1)",op=>'<=',source_kind=>'watchdog_init'};
    push @$st,{name=>"${tn}_timeout",kind=>'terminal',assignments=>[{lhs=>'done',rhs=>1,op=>'<1',source_kind=>'timeout_pulse'},{lhs=>'last_error',rhs=>1,op=>'<-',source_kind=>'timeout_status'}],transitions=>[]};
}

sub _inj_latency {
    my ($st,$tn,$lat,$ha,$ctrs)=@_;
    $ctrs->{last_error} = 1; my $cc="${tn}_cc";my $inc="${tn}_inc";my $err="${tn}_lerr";my $min=$lat->{min}//1;my $max=$lat->{max}//256;
    unshift @{$st->[0]{assignments}},{lhs=>$cc,rhs=>0,op=>'<-',source_kind=>'latency_counter_init'};
    for my $s(@$st){next if $s->{kind}eq'entry'||$s->{kind}eq'terminal'||$s->{name}=~/_timeout$/;unshift @{$s->{assignments}},{lhs=>$inc,rhs=>1,op=>'=',source_kind=>'latency_increment_request'}}
    my($done)=grep{$_->{kind}eq'terminal'&&$_->{name}!~/_timeout$/}@$st;
    if($done){push @{$done->{assignments}},{lhs=>$err,rhs=>1,op=>'=',guard=>{signal=>$cc,op=>'<',value=>$min},source_kind=>'latency_error'}}
    if(!$ha&&$max){my $mc="${tn}_max_chk";push @$st,{name=>$mc,kind=>'sequential',assignments=>[],transitions=>[{target=>"${tn}_timeout",condition=>{signal=>$cc,op=>'=',value=>$max}}]};
        push @$st,{name=>"${tn}_timeout",kind=>'terminal',assignments=>[{lhs=>$err,rhs=>1,op=>'=',source_kind=>'latency_error'},{lhs=>'done',rhs=>1,op=>'<1',source_kind=>'timeout_pulse'},{lhs=>'last_error',rhs=>1,op=>'<-',source_kind=>'timeout_status'}],transitions=>[]}}
    my $dt={name=>"${tn}_cc_inc",kind=>'latency_counter',assignments=>[{lhs=>$cc,rhs=>"(+ $cc 1)",op=>'<-',guard=>{port=>$inc},source_kind=>'latency_counter'}]};
    return ($cc,$inc,$err,$dt);
}

sub _build_rules {
    my ($self, $actor, $ctrs, $bank_accesses, $generated_children, $storage_roles) = @_;
    my @d;
    my %fanin_by_transaction;
    my %payload_by_transaction;
    my %seen_fanin_source;
    my %generated_trigger_ordinals;
    my $widths = _build_signal_width_map($actor, { clauses => [] });
    my %transaction_by_name = map { $_->{name} => $_ } @{$actor->{transactions} || []};
    $generated_children ||= {};

    for my $r (@{$actor->{rules} || []}) {
        my $c = $self->_rule_cond($r->{when});
        my $terms = _rule_cond_terms($r->{when});
        my @a;

        for my $ac (@{$r->{actions}}) {
            next unless ref($ac) eq 'ARRAY';
            my $a0 = $ac->[0];

            if ($a0 eq 'trigger') {
                my $target = $ac->[1];
                my $generated_trigger = $generated_children->{$target} ? 1 : 0;
                my $trigger_ordinal;
                if ($generated_trigger) {
                    my $key = "$r->{name}\0$target";
                    $trigger_ordinal = $generated_trigger_ordinals{$key}++;
                }
                my $source = _rule_trigger_source_name($r->{name}, $target, $trigger_ordinal);
                push @a, { lhs => $source, rhs => 1, op => '<1', source_kind => 'rule_trigger_source' };
                $ctrs->{$source} = 1 if $ctrs;
                $storage_roles->{$source} = 'rule_trigger_source'
                    if ref($storage_roles) eq 'HASH';
                $ctrs->{"${target}_start"} = 1 if $ctrs && !$generated_trigger;
                my %target_ports = _transaction_port_map($transaction_by_name{$target});
                for my $binding (@{_activation_bindings_from_clause($ac, $r->{name}, 'rule trigger')}) {
                    next unless $binding->{role} eq 'input';
                    my $payload = _rule_trigger_payload_source_name($r->{name}, $target, $target_ports{$binding->{port}}{source_name}, $trigger_ordinal);
                    my $width = ($target_ports{$binding->{port}} || {})->{width} // 1;
                    push @a, {
                        lhs         => $payload,
                        rhs         => _activation_binding_actor_expr_text($binding),
                        op          => '<-',
                        source_kind => 'rule_trigger_payload_source',
                    };
                    $ctrs->{$payload} = $width if $ctrs;
                    $storage_roles->{$payload} = 'rule_trigger_payload_source'
                        if ref($storage_roles) eq 'HASH';
                    $ctrs->{$binding->{port}} = $width if $ctrs;
                    push @{$payload_by_transaction{$target}{$binding->{port}}}, {
                        trigger_source => $source,
                        payload_source => $payload,
                        width          => $width,
                    };
                }
                if (!$generated_trigger) {
                    push @{$fanin_by_transaction{$target}}, $source
                        unless $seen_fanin_source{"$target\0$source"}++;
                }
            } elsif ($a0 eq 'atl_trigger') {
                push @a, {
                    lhs         => $ac->[1],
                    rhs         => 1,
                    op          => '<1',
                    source_kind => 'atl_actor_transaction_trigger',
                };
            } elsif ($a0 eq 'priority') {
                # Parsed metadata; arbitration enforcement is a later slice.
            } elsif ($a0 eq 'pulse') {
                push @a, {
                    lhs         => $ac->[1],
                    rhs         => 1,
                    op          => '<1',
                    source_kind => 'rule_pulse_action',
                };
            } elsif ($a0 eq 'store' || $a0 eq 'load') {
                my $spec = _parse_bank_access_for_lowering($ac, $actor, $widths, $r->{name}, 'rule');
                push @a, _bank_access_assignments($spec);
                push @$bank_accesses, _bank_access_metadata(
                    $spec,
                    owner          => $r->{name},
                    owner_kind     => 'rule',
                    container_kind => 'dt',
                    container_name => $r->{name},
                ) if ref($bank_accesses) eq 'ARRAY';
            } elsif ($a0 eq 'set') {
                push @a, {
                    lhs         => $ac->[1],
                    rhs         => _format_isf_expr($ac->[2]),
                    op          => '<-',
                    source_kind => 'rule_action',
                };
            } else {
                push @a, { lhs => $a0, rhs => _format_isf_expr($ac->[1]), op => '<-', source_kind => 'rule_action' };
            }
        }

        push @d, {
            name            => $r->{name},
            kind            => 'rule',
            source_owner    => {kind => 'rule', name => $r->{name}},
            dte_guard       => $c,
            dte_guard_terms => $terms,
            assignments     => \@a,
        };
    }

    for my $target (sort keys %fanin_by_transaction) {
        my @sources = @{$fanin_by_transaction{$target}};
        my $rhs = @sources == 1 ? $sources[0] : '(| ' . join(' ', @sources) . ')';
        push @d, {
            name        => "${target}_trigger_fanin",
            kind        => 'rule_trigger_fanin',
            owner       => $target,
            owner_kind  => 'transaction',
            assignments => [
                { lhs => "${target}_start", rhs => $rhs, op => '=', source_kind => 'rule_trigger_fanin' },
                _rule_trigger_payload_fanin_assignments($payload_by_transaction{$target} || {}),
            ],
        };
    }

    return @d;
}
sub _rule_trigger_source_name {
    my ($rule, $target, $ordinal) = @_;
    return defined($ordinal)
        ? "${rule}_${target}_trigger_$ordinal"
        : "${rule}_${target}";
}
sub _rule_trigger_payload_source_name {
    my ($rule, $target, $port, $ordinal) = @_;
    return defined($ordinal)
        ? "${rule}_${target}_trigger_${ordinal}_${port}_payload"
        : "${rule}_${target}_$port";
}
sub _rule_trigger_payload_fanin_assignments {
    my ($by_port) = @_;
    my @assignments;
    for my $port (sort keys %$by_port) {
        for my $source (@{$by_port->{$port} || []}) {
            push @assignments, {
                lhs         => $port,
                rhs         => $source->{payload_source},
                op          => '=',
                guard       => { port => $source->{trigger_source} },
                source_kind => 'rule_trigger_payload_fanin',
            };
        }
    }
    return @assignments;
}
# Plan from actual owned states and fan-in assignments in both detached source
# preparation and executable lowering. Raw formals need not have compatible
# parent widths here: only declaration membership is merged for allocation.
sub _local_rule_payload_snapshot_products {
    my ($actor, $declaration_names, $states, $dts) = @_;
    my %reserved = %$declaration_names;
    my (%ports, %types, %initial);
    for my $tx (@{$actor->{transactions} || []}) {
        $ports{$tx->{name}} = { _transaction_port_map($tx) };
        $types{$tx->{name}} = { _transaction_port_signal_type_refs($tx) };
        # Projection frees raw formal spellings. Keep them reserved so helper
        # identities cannot change when the same producer sees projected source.
        $reserved{$_->{source_name}} = 1 for values %{$ports{$tx->{name}}};
    }
    for my $state (@$states) {
        my $owner = $state->{transaction};
        next unless defined $owner;
        $initial{$owner} //= $state;
    }
    my $products = {signal_widths => {}, storage_roles => {}, signal_type_refs => {},
        explicit_internal_signals => [], dt_blocks => [], bindings => []};
    for my $dt (sort {$a->{name} cmp $b->{name}} @$dts) {
        next unless ($dt->{kind} // '') eq 'rule_trigger_fanin';
        my @payloads = grep { ($_->{source_kind} // '') eq 'rule_trigger_payload_fanin' }
            @{$dt->{assignments} || []};
        next unless @payloads;
        my $owner = $dt->{owner};
        confess "Local rule payload fan-in '$dt->{name}' lacks an owned initial state\n"
            unless defined($owner) && $initial{$owner};
        my $entry = $initial{$owner};
        my $active = _state_active_condition_expr($entry->{name});
        # An unguarded target retains its authored free-running first state.
        # Later entry states must never accept a replacement for this invocation.
        my $accept = ($entry->{kind} // '') eq 'entry'
            ? (_guard_condition_expr($entry->{guard}) // '1') : '1';
        my %by_port;
        push @{$by_port{$_->{lhs}}}, $_ for @payloads;
        my $replacement = _clone_isf_value($dt);
        $replacement->{assignments} = [grep {
            ($_->{source_kind} // '') ne 'rule_trigger_payload_fanin'
        } @{$replacement->{assignments}}];
        for my $port (sort { $ports{$owner}{$a}{source_name} cmp $ports{$owner}{$b}{source_name} } keys %by_port) {
            my $formal = $ports{$owner}{$port};
            confess "Local rule payload '$owner.$port' is not an input formal\n"
                unless $formal && $formal->{direction} eq 'input';
            my $held = FSM::Support::HDLInstanceIdentifierPolicy->allocate_generated_instance_identifier(
                desired => "isf_snapshot_${owner}_$formal->{source_name}",
                role => 'payload', reserved => \%reserved);
            $products->{signal_widths}{$held} = $formal->{width};
            $products->{storage_roles}{$held} = 'transaction_port_binding';
            $products->{signal_type_refs}{$held} = $types{$owner}{$port}
                if exists $types{$owner}{$port};
            push @{$products->{explicit_internal_signals}}, $held;
            push @{$products->{bindings}}, {
                identity => ['transaction_port', $actor->{actor_name}, $owner, $formal->{source_name}],
                formal_signal => $port, held_signal => $held, initial_state => $entry->{name},
            };
            my @visible;
            for my $source (@{$by_port{$port}}) {
                my $request = _guard_condition_expr($source->{guard});
                confess "Local rule payload '$owner.$port' lacks a source guard\n"
                    unless defined $request;
                # The bypass must not depend on the authored entry guard: that
                # guard may read this formal. Only the register capture uses it.
                my $visible = _combine_condition_exprs($active, $request);
                push @visible, $visible;
                my $view = _clone_isf_value($source);
                $view->{guard} = {expr => $visible};
                push @{$replacement->{assignments}}, $view, {
                    lhs => $held, rhs => $source->{rhs}, op => '<-',
                    source_kind => 'rule_trigger_payload_capture',
                    guard => {expr => _combine_condition_exprs($visible, $accept)},
                };
            }
            my $visible = @visible == 1 ? $visible[0] : '(| ' . join(' ', @visible) . ')';
            push @{$replacement->{assignments}}, {
                lhs => $port, rhs => $held, op => '=',
                source_kind => 'rule_trigger_payload_held_view',
                guard => {expr => _negated_condition_expr($visible)},
            };
        }
        push @{$products->{dt_blocks}}, $replacement;
    }
    return $products;
}

sub _apply_local_rule_payload_snapshots {
    my ($ir, $products) = @_;
    my %replacement = map { $_->{name} => $_ } @{$products->{dt_blocks}};
    $ir->{dt_blocks} = [map { $replacement{$_->{name}} // $_ } @{$ir->{dt_blocks}}];
    for my $name (keys %{$products->{signal_widths}}) {
        $ir->{counters}{$name} = $ir->{signal_widths}{$name} = $products->{signal_widths}{$name};
        $ir->{storage_roles}{$name} = $products->{storage_roles}{$name};
    }
    _merge_signal_type_refs($ir->{signal_type_refs}, $products->{signal_type_refs});
    push @{$ir->{explicit_internal_signals}}, @{$products->{explicit_internal_signals}};
}

sub _rule_cond {
    my ($self, $w) = @_;
    return { port => '1' } unless $w && ref($w) eq 'ARRAY' && @$w >= 2;
    return ref($w->[1])
        ? { expr => _format_isf_expr($w->[1]) }
        : { port => $w->[1] };
}
sub _rule_cond_terms {
    my ($w) = @_;
    return {} unless $w && ref($w) eq 'ARRAY' && @$w >= 2;
    return _condition_literal_terms($w->[1]);
}

sub _substitute_named_drive_body_expr {
    my ($value, $param_signal) = @_;
    if (ref($value) eq 'ARRAY') {
        return [ map { _substitute_named_drive_body_expr($_, $param_signal) } @$value ];
    }
    return $param_signal->{$value}
        if defined($value) && !ref($value) && exists $param_signal->{$value};
    if (defined($value) && !ref($value)) {
        my $token = $value;
        if ($token =~ /\A([A-Za-z_]\w*)(\[\d+(?::\d+)?\])\z/) {
            my ($root, $selector) = ($1, $2);
            return $param_signal->{$root} . $selector if exists $param_signal->{$root};
        }
    }
    return $value;
}

sub _build_drive_dts {
    my (
        $self,
        $actor,
        $dts,
        $ctrs,
        $local_drive_filter,
        $local_drive_callers,
        $extra_drive_sources,
        $storage_roles,
    ) = @_;
    my $drives = $actor->{drives} || {};
    for my $name (sort keys %$drives) {
        my $def = $drives->{$name};
        my $body = $def->{body};
        my @params = @{$def->{params}};
        my @local_callers = sort keys %{($local_drive_callers || {})->{$name} || {}};
        my @extra_sources = @{($extra_drive_sources || {})->{$name} || []};
        my @generated_call_sources = sort {
            _generated_drive_source_sort_key($a) cmp _generated_drive_source_sort_key($b)
        } map { _generated_drive_source_metadata($_) } @extra_sources;
        my @sources;

        push @sources, {
            prefix => $name, source_kind => 'drive_body',
            drive_invocation => {
                kind => 'local', drive => $name, request_signal => "${name}_start",
                local_transactions => [@local_callers],
            },
        } if !$local_drive_filter || $local_drive_filter->{$name};
        push @sources, map { +{
            %$_,
            drive_invocation => {
                kind => 'generated', drive => $name, request_signal => "$_->{prefix}_start",
                generated_source => _generated_drive_source_metadata($_),
            },
        } } @extra_sources;
        next unless @sources;

        my @assignments;

        for my $source (@sources) {
            my $prefix = $source->{prefix};
            $ctrs->{"${prefix}_start"} = 1;
            $storage_roles->{"${prefix}_start"} = 'drive_request'
                if ref($storage_roles) eq 'HASH';
            for my $p (@params) {
                $ctrs->{"${prefix}_$p"} = _drive_param_width($actor, $name, $p);
                $storage_roles->{"${prefix}_$p"} = 'drive_payload'
                    if ref($storage_roles) eq 'HASH';
            }

            my %param_signal = map { $_ => "${prefix}_$_" } @params;
            for my $pair (@$body) {
                next unless ref($pair) eq 'ARRAY' && @$pair >= 2;
                my $lhs = $pair->[0];
                my $rhs = _substitute_named_drive_body_expr($pair->[1], \%param_signal);
                push @assignments, {
                    lhs         => $lhs,
                    rhs         => _format_isf_expr($rhs),
                    op          => '<-',
                    guard       => { port => "${prefix}_start" },
                    source_kind => $source->{source_kind} || 'drive_body',
                    invoking_transactions => [@local_callers],
                    drive_invocation => _clone_isf_value($source->{drive_invocation}),
                };
            }
        }

        push @$dts, {
            name                      => $name,
            kind                      => 'drive',
            source_owner              => {kind => 'drive', name => $name},
            local_transaction_callers => \@local_callers,
            generated_call_sources    => \@generated_call_sources,
            assignments               => \@assignments,
        };
    }
}

sub _generated_drive_source_metadata {
    my ($source) = @_;
    return {
        activation_kind   => $source->{activation_kind} // 'spawn',
        child_transaction => $source->{child_transaction} // '',
        instance          => $source->{instance} // '',
        owner             => $source->{owner} // '',
        owner_kind        => $source->{owner_kind} // '',
        prefix            => $source->{prefix} // '',
        source_kind       => $source->{source_kind} // 'spawn_drive_body',
    };
}

sub _generated_drive_source_sort_key {
    my ($source) = @_;
    return join "\0", map { $source->{$_} // '' } qw(
        source_kind activation_kind child_transaction instance owner_kind owner prefix
    );
}

# ISF-LOCAL-VARIABLES: `(local NAME (width N))` declares an internal register at an
# explicit width, emitted in `+size` (vs. an implicit internal scalar whose width is
# inferred). Returns (name, width); registers the width in the transaction's signal
# map. Fails closed on a missing/invalid width or a collision with an interface port
# or an already-declared transaction signal.
sub _parse_local_decl {
    my ($cl, $tn, $actor, $ct) = @_;
    my $name = $cl->[1];
    confess "Transaction '$tn': '(local ...)' requires a name\n"
        unless defined($name) && !ref($name) && length($name);
    confess "Transaction '$tn': local name '$name' must be a scalar HDL identifier\n"
        unless _is_hdl_identifier($name);
    my ($width, $default, $reset);
    my %seen;
    for my $sub (@{$cl}[2 .. $#$cl]) {
        confess "Transaction '$tn': local options require '(width N)', '(default V)', '(init V)' or '(reset V)'\n"
            unless ref($sub) eq 'ARRAY' && @$sub == 2
                && defined($sub->[0]) && !ref($sub->[0]) && defined($sub->[1]);
        my $option = $sub->[0];
        confess "Transaction '$tn': unsupported local option '$option'\n"
            unless $option =~ /\A(?:width|default|init|reset)\z/;
        my $role = $option eq 'default' || $option eq 'init' ? 'initialization' : $option;
        confess "Transaction '$tn': duplicate local initialization option (default/init)\n"
            if $role eq 'initialization' && $seen{$role};
        confess "Transaction '$tn': duplicate local '$option' option\n"
            if $seen{$role}++;
        $width   = $sub->[1] if $sub->[0] eq 'width';
        # `(default V)` and `(init V)` are accepted synonyms for the initial value.
        $default = $sub->[1] if $sub->[0] eq 'default' || $sub->[0] eq 'init';
        # `(reset V)` — the HARDWARE reset value (the value the register holds out of
        # reset), distinct from the init-on-entry `(default V)`/`(init V)`.
        $reset   = $sub->[1] if $sub->[0] eq 'reset';
    }
    confess "Transaction '$tn': '(local $name ...)' requires a '(width N)' with a positive integer\n"
        unless defined($width) && !ref($width) && $width =~ /\A[1-9][0-9]*\z/;
    # Optional `(default V)` / `(init V)` — a non-negative integer literal that fits in
    # the width, materialized as a set on transaction entry (a transaction-local is
    # re-initialized to its default each time the transaction runs).
    if (defined $default) {
        confess "Transaction '$tn': '(local $name ... (default V))' requires a non-negative integer literal\n"
            unless !ref($default) && $default =~ /\A[0-9]+\z/;
        confess "Transaction '$tn': '(local $name (width $width) (default $default))' default value does not fit in $width bit(s)\n"
            if $default + 0 >= (2 ** ($width + 0));
    }
    # Optional `(reset V)` — a non-negative integer literal that fits in the width; emitted
    # in `+size` as `(name width (reset V))` so the register powers up at V on hardware
    # reset. Unspecified -> resets to all-0s, unchanged.
    if (defined $reset) {
        confess "Transaction '$tn': '(local $name ... (reset V))' requires a non-negative integer literal\n"
            unless !ref($reset) && $reset =~ /\A[0-9]+\z/;
        confess "Transaction '$tn': '(local $name (width $width) (reset $reset))' reset value does not fit in $width bit(s)\n"
            if $reset + 0 >= (2 ** ($width + 0));
    }
    for my $dir (qw(inputs outputs)) {
        confess "Transaction '$tn': '(local $name ...)' collides with interface port '$name'\n"
            if grep { ($_->{name} // '') eq $name } @{$actor->{interface}{$dir} || []};
    }
    confess "Transaction '$tn': '(local $name ...)' collides with an already-declared signal '$name'\n"
        if ref($ct) eq 'HASH' && exists $ct->{$name};
    return ($name, $width + 0, (defined $default ? $default + 0 : undef), (defined $reset ? $reset + 0 : undef));
}

sub _parse_latency {
    my ($cl, $tn, $actor) = @_;
    my %result;

    my @options = grep { defined } @{$cl}[1 .. $#$cl];

    confess "Transaction '$tn': latency requires '(latency (min N) (max M))'\n"
        unless @options;

    for my $option (@options) {
        confess "Transaction '$tn': latency options must be '(min N)' or '(max N)'\n"
            unless ref($option) eq 'ARRAY'
                && @$option == 2
                && defined($option->[0])
                && !ref($option->[0])
                && ($option->[0] eq 'min' || $option->[0] eq 'max')
                && defined($option->[1])
                && !ref($option->[1]);

        my $key = $option->[0];
        confess "Transaction '$tn': duplicate latency '$key' option\n"
            if exists $result{$key};
        $result{$key} = _latency_bound_cycles($option->[1], $key, $tn, $actor);
    }

    confess "Transaction '$tn': latency min must be less than or equal to max\n"
        if exists($result{min}) && exists($result{max}) && $result{min} > $result{max};

    return \%result;
}

sub _latency_bound_cycles {
    my ($token, $key, $tn, $actor) = @_;

    return 0 + $token
        if defined($token) && !ref($token) && $token =~ /\A[1-9][0-9]*\z/;

    confess "Transaction '$tn': latency $key cycles must be positive in transaction body\n"
        if defined($token) && !ref($token) && $token =~ /\A0+\z/;

    my $package_bound = _latency_package_constant_bound_cycles($token, $key, $tn, $actor);
    return $package_bound if defined $package_bound;

    if (defined($token) && !ref($token) && _is_hdl_identifier($token)) {
        my $transaction_param = _transaction_param_by_name($actor, $tn, $token);
        if ($transaction_param) {
            my $param_value = _non_negative_integer_from_literal(_param_resolved_value($transaction_param));
            confess "Transaction '$tn': latency $key transaction parameter '$token' must resolve to a positive cycle count in transaction body\n"
                unless defined($param_value) && $param_value > 0;
            return $param_value;
        }

        my $constant = _actor_constant_by_name($actor, $token);
        if ($constant) {
            my $constant_value = _non_negative_integer_from_literal(_constant_resolved_value($constant));
            confess "Transaction '$tn': latency $key constant '$token' must resolve to a positive cycle count in transaction body\n"
                unless defined($constant_value) && $constant_value > 0;
            return $constant_value;
        }

        my $param = _actor_param_by_name($actor, $token);
        if ($param) {
            my $param_value = _non_negative_integer_from_literal(_param_resolved_value($param));
            confess "Transaction '$tn': latency $key parameter '$token' must resolve to a positive cycle count in transaction body\n"
                unless defined($param_value) && $param_value > 0;
            return $param_value;
        }

        confess "Transaction '$tn': latency $key token '$token' is a runtime interface signal; latency bounds accept positive integer literals, same-transaction scalar parameters, actor constants, actor scalar parameters, or qualified package scalar constants only in transaction body\n"
            if _actor_interface_signal_by_name($actor, $token);

        confess "Transaction '$tn': latency $key token '$token' is not a same-transaction scalar parameter, declared actor constant, actor scalar parameter, or qualified package scalar constant in transaction body\n";
    }

    confess "Transaction '$tn': latency options must be '(min N)' or '(max N)'\n";
}

sub _latency_package_constant_bound_cycles {
    my ($token, $key, $tn, $actor) = @_;
    return undef unless defined($token) && !ref($token);

    my $package_constant = _actor_package_constant_reference($actor, $token);
    if (!$package_constant) {
        confess "Transaction '$tn': latency $key references unknown package constant '$token' in transaction body\n"
            if _is_package_constant_reference_shape($token);
        return undef;
    }

    my ($package_name, $constant_name, $suffix) = @$package_constant;
    my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
    if (defined $constant_payload) {
        confess "Transaction '$tn': latency $key token '$token' is ambiguous: it matches local enum member '$token' and imported package constant '$token' in transaction body\n"
            if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
        confess "Transaction '$tn': latency $key package constant '$package_name.$constant_name' aggregate/member path '$token' remains deferred; latency bounds accept only qualified package scalar constants in this slice\n"
            if $suffix ne '';
        my $constant_value = _package_constant_scalar_value($constant_payload);
        my $integer_value = defined($constant_value) && !ref($constant_value)
            ? _non_negative_integer_from_literal($constant_value)
            : undef;
        confess "Transaction '$tn': latency $key package constant '$package_name.$constant_name' must resolve to a positive integer scalar cycle count in transaction body\n"
            unless defined($integer_value) && $integer_value > 0;
        return $integer_value;
    }

    confess "Transaction '$tn': latency $key references unknown package constant '$token' in transaction body\n"
        if !_actor_local_enum_member_exists($actor, $package_name, $constant_name);

    return undef;
}

sub _watchdog_limit_cycles {
    my ($token, $actor, $tn, $label) = @_;
    my $await_local = $label eq 'await watchdog override';
    my $accepted_sources = $await_local
        ? 'positive integer literals, same-transaction scalar parameters, actor constants, actor scalar parameters, or qualified package scalar constants'
        : 'positive integer literals, actor constants, actor scalar parameters, or qualified package scalar constants';

    return 0 + $token
        if defined($token) && !ref($token) && $token =~ /\A[1-9][0-9]*\z/;

    confess "Transaction '$tn': watchdog limit must be positive in $label\n"
        if defined($token) && !ref($token) && $token =~ /\A0+\z/;

    my $package_limit = _watchdog_package_constant_limit_cycles($token, $actor, $tn, $label);
    return $package_limit if defined $package_limit;

    if (defined($token) && !ref($token) && _is_hdl_identifier($token)) {
        if ($await_local) {
            my $transaction_param = _transaction_param_by_name($actor, $tn, $token);
            if ($transaction_param) {
                my $param_value = _non_negative_integer_from_literal(_param_resolved_value($transaction_param));
                confess "Transaction '$tn': watchdog transaction parameter '$token' must resolve to a positive cycle count in $label\n"
                    unless defined($param_value) && $param_value > 0;
                return $param_value;
            }
        }

        my $constant = _actor_constant_by_name($actor, $token);
        if ($constant) {
            my $constant_value = _non_negative_integer_from_literal(_constant_resolved_value($constant));
            confess "Transaction '$tn': watchdog constant '$token' must resolve to a positive cycle count in $label\n"
                unless defined($constant_value) && $constant_value > 0;
            return $constant_value;
        }

        confess "Transaction '$tn': watchdog token '$token' is a transaction parameter; watchdog limits accept $accepted_sources only in $label\n"
            if _transaction_param_by_name($actor, $tn, $token);

        my $param = _actor_param_by_name($actor, $token);
        if ($param) {
            my $param_value = _non_negative_integer_from_literal(_param_resolved_value($param));
            confess "Transaction '$tn': watchdog parameter '$token' must resolve to a positive cycle count in $label\n"
                unless defined($param_value) && $param_value > 0;
            return $param_value;
        }

        confess "Transaction '$tn': watchdog token '$token' is a runtime interface signal; watchdog limits accept $accepted_sources only in $label\n"
            if _actor_interface_signal_by_name($actor, $token);

        my $unknown_sources = $await_local
            ? 'same-transaction scalar parameter, declared actor constant, actor scalar parameter, or qualified package scalar constant'
            : 'declared actor constant, actor scalar parameter, or qualified package scalar constant';
        confess "Transaction '$tn': watchdog token '$token' is not a $unknown_sources in $label\n";
    }

    confess "Transaction '$tn': watchdog limits accept $accepted_sources only in $label\n";
}

sub _watchdog_package_constant_limit_cycles {
    my ($token, $actor, $tn, $label) = @_;
    return undef unless defined($token) && !ref($token);

    my $package_constant = _actor_package_constant_reference($actor, $token);
    if (!$package_constant) {
        confess "Transaction '$tn': watchdog references unknown package constant '$token' in $label\n"
            if _is_package_constant_reference_shape($token);
        return undef;
    }

    my ($package_name, $constant_name, $suffix) = @$package_constant;
    my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
    if (defined $constant_payload) {
        confess "Transaction '$tn': watchdog token '$token' is ambiguous: it matches local enum member '$token' and imported package constant '$token' in $label\n"
            if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
        confess "Transaction '$tn': watchdog package constant '$package_name.$constant_name' aggregate/member path '$token' remains deferred; watchdog limits accept only qualified package scalar constants in this slice\n"
            if $suffix ne '';
        my $constant_value = _package_constant_scalar_value($constant_payload);
        my $integer_value = defined($constant_value) && !ref($constant_value)
            ? _non_negative_integer_from_literal($constant_value)
            : undef;
        confess "Transaction '$tn': watchdog package constant '$package_name.$constant_name' must resolve to a positive integer scalar cycle count in $label\n"
            unless defined($integer_value) && $integer_value > 0;
        return $integer_value;
    }

    confess "Transaction '$tn': watchdog references unknown package constant '$token' in $label\n"
        if !_actor_local_enum_member_exists($actor, $package_name, $constant_name);

    return undef;
}

sub _transaction_watchdog_limit {
    my ($states, $default_limit, $tn) = @_;

    my %limits;
    for my $state (@$states) {
        next unless ref($state) eq 'HASH' && $state->{kind} eq 'await';
        my $limit = (($state->{watchdog} || {})->{limit}) // $default_limit // 65535;
        $limits{$limit} = 1;
    }

    my @limits = sort { $a <=> $b } keys %limits;
    confess "Transaction '$tn': multiple distinct await watchdog limits are not supported by the current single watchdog counter\n"
        if @limits > 1;

    return @limits ? $limits[0] : ($default_limit // 65535);
}

sub _parse_await_wd {
    my ($cl, $tn) = @_;
    for my $i (2 .. $#$cl) {
        my $option = $cl->[$i];
        next unless ref($option) eq 'ARRAY'
            && defined($option->[0])
            && !ref($option->[0])
            && $option->[0] eq 'watchdog';
        confess "Transaction '$tn': await watchdog override requires '(watchdog N)'\n"
            unless @$option == 2 && defined($option->[1]) && !ref($option->[1]);
        return $option->[1];
    }
    return undef;
}

sub _await_watchdog_limit {
    my ($cl, $actor, $tn, $default_limit) = @_;
    my $wd_override = _parse_await_wd($cl, $tn);
    return defined($wd_override)
        ? _watchdog_limit_cycles($wd_override, $actor, $tn, 'await watchdog override')
        : $default_limit;
}

sub _wire_do_children {
    my ($self,$st,$ctrs,$actor,$generated_children)=@_;
    $generated_children ||= {};
    my %ctx = map { $_->{name} => 1 } @{$actor->{transactions}};
    my %need;
    for my $tx (@{$actor->{transactions}}) {
        for my $ref (_live_child_action_refs_from_transaction_clauses($tx->{clauses}, $tx->{name}, $actor)) {
            next unless ($ref->{keyword} // '') eq 'do';
            my $target = $ref->{clause}[1];
            next if $generated_children->{$target};
            $need{$target} = 1 if $ctx{$target};
        }
    }
    for my $c (sort keys %need) {my $s="${c}_start";my $d="${c}_done";
        $ctrs->{$s}=1 if ref($ctrs)eq'HASH';
        $ctrs->{$d}=1 if ref($ctrs)eq'HASH';
        my($en)=grep{$_->{name}=~/^\Q$c\E_idle_/}@$st;if($en){$en->{guard}={port=>$s};$en->{transitions}=[];my($nx)=grep{$_->{name}=~/^\Q$c\E_/&&$_->{kind}ne'entry'&&$_->{name}!~/_timeout$/}@$st;push @{$en->{transitions}},{target=>$nx->{name},condition=>$en->{guard}}if$nx}
        my($tm)=grep{$_->{name}=~/^\Q$c\E_(?:done|complete)_/&&$_->{kind}eq'terminal'}@$st;unshift @{$tm->{assignments}},{lhs=>$d,rhs=>1,op=>'<1'}if$tm}
}

# Cross-domain activation handshake lowering (ISF-CROSS-DOMAIN-ACTIVATION-VIA-CROSSING).
#
# When a blocking `(do child)` crosses a clock-domain boundary through a declared
# `(crossings (activation child (from SRC)(to DEST)))`, the calling transaction
# and `child` lower into separate per-domain modules, so the activation
# start/done handshake that is module-internal for a same-domain `(do)` must be
# promoted to inter-module PORTS and routed through CDC synchronizers in the top.
#
# This routine consumes `$actor->{external_activations}` (only ever set by the
# multi-domain partition when building a per-domain actor) and promotes the
# handshake signals to ports on the per-domain module:
#   - role 'caller' (SRC side, owning the `(do child)`): `<start>` becomes an
#     OUTPUT and `<done>` an INPUT. The do-state emitted by `_ir_do` already
#     asserts `<start>` and guards on `<done>`; here we only promote the signals
#     from module-internal `+size` registers to interface ports.
#   - role 'callee' (DEST side, owning `child`): `<start>` becomes an INPUT and
#     `<done>` an OUTPUT, and `child`'s idle state is gated on `<start>` with its
#     terminal asserting `<done>` (the same rewrite `_wire_do_children` performs
#     for a same-domain sibling `(do)`, but for an activation whose `(do)` clause
#     lives in the other domain's module).
sub _wire_external_activations {
    my ($self, $st, $ports, $ctrs, $actor) = @_;
    my $activations = $actor->{external_activations};
    return unless ref($activations) eq 'ARRAY' && @$activations;

    for my $activation (@$activations) {
        my $child = $activation->{child};
        next unless defined($child) && !ref($child) && length($child);
        my $role  = $activation->{role} // '';
        my $start = $activation->{start_signal} // "${child}_start";
        my $done  = $activation->{done_signal}  // "${child}_done";

        # Promote the handshake signals from module-internal `+size` registers to
        # interface ports, removing the internal duplicate so the emitted module
        # exposes each signal exactly once.
        delete $ctrs->{$start} if ref($ctrs) eq 'HASH';
        delete $ctrs->{$done}  if ref($ctrs) eq 'HASH';

        if ($role eq 'caller') {
            my $ready = "${start}_ready";
            _ensure_port($ports, $start, 'output', 1,
                "external activation '$child' caller start handoff");
            _ensure_port($ports, $done, 'input', 1,
                "external activation '$child' caller done handoff");
            _ensure_port($ports, $ready, 'input', 1,
                "external activation '$child' caller start-ready handshake");
            delete $ctrs->{$ready} if ref($ctrs) eq 'HASH';

            # The cross-domain `<start>` routes through an acknowledged-event CDC
            # child. Mirror the event-crossing source idiom: AWAIT `<start>_ready`
            # (CDC idle, request accepted on the next pulse) and then assert
            # `<start>` for exactly ONE cycle. Holding `<start>` would re-toggle the
            # CDC and re-trigger `child`; awaiting `<start>_ready` consumes the CDC
            # `ready` output (the composition requires every child output to be
            # consumed) and guarantees the single request pulse is accepted.
            #
            # `_ir_do` emits one await state that asserts `<start>` and guards on
            # `<done>`. Restructure it into:
            #   <do>_ready (await <start>_ready) -> <do>_req (one-cycle <start>)
            #   -> <do> (await <done>).
            my ($do_state) = grep {
                ($_->{kind} // '') eq 'await'
                    && grep { ($_->{lhs} // '') eq $start } @{$_->{assignments} || []}
            } @$st;
            if ($do_state) {
                $do_state->{assignments} = [
                    grep { ($_->{lhs} // '') ne $start } @{$do_state->{assignments} || []}
                ];
                my $request = {
                    name        => "$do_state->{name}_req",
                    transaction => $do_state->{transaction},
                    kind        => 'sequential',
                    assignments => [
                        { lhs => $start, rhs => 1, op => '=', source_kind => 'cross_domain_do_start' },
                    ],
                    transitions => [{ target => $do_state->{name} }],
                };
                my $ready_wait = {
                    name        => "$do_state->{name}_ready",
                    transaction => $do_state->{transaction},
                    kind        => 'await',
                    assignments => [],
                    guard       => { port => $ready },
                    transitions => [{ target => $request->{name}, condition => { port => $ready } }],
                };
                my ($do_index) = grep { $st->[$_] == $do_state } 0 .. $#$st;
                splice(@$st, $do_index, 0, $ready_wait, $request);
                # Redirect every reference to the do-state — a predecessor's plain
                # transition target, OR a branch/loop ENTRY target that is rendered
                # from a dedicated field rather than `transitions` (a `when`/branch
                # state's `true_target`, a `switch` branch's `body_start`, a loop's
                # `loop_body_start`) — to the ready-await, so the inserted
                # ready -> req -> do(await done) chain runs before the do-state in
                # every context (top-level, repeat body, and branch/loop body). When a
                # `repeat_check` loop-back targets the do-state (the first body state),
                # this redirect catches it too, so the handshake re-arms via the
                # ready-await on every iteration.
                for my $state (@$st) {
                    next if $state == $request || $state == $ready_wait;
                    for my $transition (@{$state->{transitions} || []}) {
                        $transition->{target} = $ready_wait->{name}
                            if ($transition->{target} // '') eq $do_state->{name};
                    }
                    $state->{true_target} = $ready_wait->{name}
                        if ($state->{true_target} // '') eq $do_state->{name};
                    $state->{loop_body_start} = $ready_wait->{name}
                        if ($state->{loop_body_start} // '') eq $do_state->{name};
                    for my $branch (@{$state->{branches} || []}) {
                        $branch->{body_start} = $ready_wait->{name}
                            if ($branch->{body_start} // '') eq $do_state->{name};
                    }
                }
            }
        }
        elsif ($role eq 'callee') {
            my $ready = "${done}_ready";
            _ensure_port($ports, $start, 'input', 1,
                "external activation '$child' callee start handoff");
            _ensure_port($ports, $done, 'output', 1,
                "external activation '$child' callee done handoff");
            _ensure_port($ports, $ready, 'input', 1,
                "external activation '$child' callee done-ready handshake");
            delete $ctrs->{$ready} if ref($ctrs) eq 'HASH';

            # Gate `child`'s entry on the activation `<start>` pulse. A cross-domain
            # `child` is activated by the CDC pulse, not by its own `(on ...)`
            # trigger, so synthesize a start-gated entry when the transaction has
            # none (e.g. a body-only transaction).
            my @child_states = grep { $_->{name} =~ /^\Q$child\E_/ } @$st;
            my ($entry) = grep { $_->{kind} eq 'entry' } @child_states;
            if (!$entry && @child_states) {
                my $first = $child_states[0];
                my ($first_index) = grep { $st->[$_] == $first } 0 .. $#$st;
                $entry = {
                    name        => "${child}_idle_ext",
                    transaction => $child,
                    kind        => 'entry',
                    guard       => { port => $start },
                    assignments => [],
                    transitions => [],
                };
                splice(@$st, $first_index, 0, $entry);
                @child_states = grep { $_->{name} =~ /^\Q$child\E_/ } @$st;
            }
            if ($entry) {
                $entry->{guard} = { port => $start };
                $entry->{transitions} = [];
                my ($next) = grep {
                    $_->{kind} ne 'entry' && $_->{name} !~ /_timeout$/
                } @child_states;
                push @{$entry->{transitions}}, { target => $next->{name}, condition => $entry->{guard} }
                    if $next;

                # The activation `<done>` mirrors the start handshake in reverse:
                # await `<done>_ready` (the done CDC idle) and then pulse `<done>`
                # for one cycle before returning to idle. Awaiting `<done>_ready`
                # consumes the done CDC `ready` output and guarantees a single
                # accepted done pulse. Route every terminal through this chain.
                my $done_req = {
                    name        => "${child}_done_req",
                    transaction => $child,
                    kind        => 'sequential',
                    assignments => [{ lhs => $done, rhs => 1, op => '<1' }],
                    transitions => [{ target => $entry->{name} }],
                };
                my $done_ready_wait = {
                    name        => "${child}_done_ready",
                    transaction => $child,
                    kind        => 'await',
                    assignments => [],
                    guard       => { port => $ready },
                    transitions => [{ target => $done_req->{name}, condition => { port => $ready } }],
                };
                push @$st, $done_ready_wait, $done_req;
                for my $state (@child_states) {
                    next unless $state->{kind} eq 'terminal';
                    $state->{transitions} = [{ target => $done_ready_wait->{name} }];
                }
            }
        }
        else {
            confess "FSM::Scheduler::ISF::LoweringIR: external activation '$child' has unknown role '$role'\n";
        }
    }
    return 1;
}

sub _merge_sequential {
    my ($st) = @_;
    my @merged;
    for my $s (@$st) {
        if (@merged && $merged[-1]{kind} eq 'sequential' && $s->{kind} eq 'sequential'
            && $merged[-1]{name} !~ /_repeat_check/ && $merged[-1]{name} !~ /_repeat_init/
            && $s->{name} !~ /_repeat_init/) {
            push @{$merged[-1]{assignments}}, @{$s->{assignments}};
            $merged[-1]{transitions} = $s->{transitions};
            $merged[-1]{name} = $s->{name};
        } else {
            push @merged, $s;
        }
    }
    @$st = @merged;
}

1;

